// Üretilen dosya: tool/ozgun/uret.py. Toplum ve Sosyal Bilimler · Bilişsel psikoloji, bellek ve algı (orta).
const ozSocialscience9Orta = <(String, String, List<String>, String)>[
  ('1967\'de yayımladığı ve alana adını veren "Cognitive Psychology" kitabıyla bilişsel psikolojinin babası sayılan psikolog kimdir?', 'Ulric Neisser', ['Donald Broadbent', 'Edward Tolman', 'Endel Tulving'], 'Neisser\'in 1967 tarihli kitabı, algı, dikkat ve bellek araştırmalarını tek bir alan adı altında toplamış ve "bilişsel psikoloji" teriminin yaygınlaşmasını sağlamıştır.'),
  ('Noam Chomsky\'nin 1959\'da B. F. Skinner\'ın "Sözel Davranış" kitabına yazdığı eleştiri bilişsel devrime nasıl katkı sağlamıştır?', 'Dilin yalnız pekiştirmeyle açıklanamayacağını gösterip zihinsel yapılara dikkat çekerek', ['Dil ediniminin tümüyle koşullanmayla gerçekleştiğini ilk kez deneysel olarak kanıtlayarak', 'Bilinçdışı süreçlerin dil sürçmelerinde görüldüğünü ileri sürerek', 'Hayvanların insan dilini öğrenebileceğini göstererek'], 'Chomsky, çocukların hiç duymadıkları cümleleri kurabildiğini vurgulayıp davranışçı açıklamanın yetersizliğini ortaya koydu; bu eleştiri zihnin iç yapısını inceleyen yaklaşımı güçlendirdi.'),
  ('Donald Hebb\'in 1949\'da ileri sürdüğü ve "birlikte ateşlenen nöronlar birbirine bağlanır" diye özetlenen öğrenme ilkesi neyi açıklar?', 'Eşzamanlı etkin nöronlar arasındaki bağlantının güçlenmesini', ['Nöronların yalnız tek tek ateşlendiğinde öğrenme olmasını', 'Uyarılmayan sinapsların zamanla kendiliğinden ve kalıcı olarak güçlenmesini', 'Duyusal bilginin hiç değişmeden depolanmasını'], 'Hebb kuralına göre iki nöron birlikte etkinleştikçe aralarındaki sinaptik bağ güçlenir; bu düşünce sonraki bellek ve sinir ağı modellerinin temelidir.'),
  ('Bilgi işleme yaklaşımının davranışçılıktan temel farkı, araştırmacıların gözlenemeyen süreçler hakkında nasıl çıkarım yapmasında görülür. Bu yaklaşım zihinsel süreçleri en çok hangi ölçümle sınar?', 'Tepki süreleri ve hata örüntüleri', ['Yalnızca katılımcıların içebakış raporları', 'Rüya içeriklerinin yorumlanması', 'Kişilik envanteri puanları'], 'Bilişsel psikologlar zihni doğrudan gözleyemedikleri için tepki süresi ve hata türleri gibi ölçülebilir davranışlardan iç süreçlere ilişkin modeller kurar.'),
  ('David Marr\'ın bilgi işleme sistemlerinin üç çözümleme düzeyinden "uygulama" (implementasyon) düzeyi hangi soruyu yanıtlar?', 'Sistem fiziksel olarak, örneğin nöronlarla nasıl gerçekleşir?', ['Sistem hangi amaca hizmet eder ve neyi hesaplar?', 'Sistem hangi temsilleri hangi adımlarla, hangi sırayla dönüştürür?', 'Sistemin evrimsel kökeni nedir?'], 'Marr\'a göre hesaplama düzeyi amacı, algoritma düzeyi süreç ve temsilleri, uygulama düzeyi ise bunların donanımda (beyin ya da devre) nasıl gerçekleştiğini inceler.'),
  ('1986\'da David Rumelhart ve James McClelland\'ın öncülük ettiği, bilginin çok sayıda basit birim arasındaki bağlantı ağırlıklarında dağıtık olarak tutulduğunu savunan yaklaşım hangisidir?', 'Bağlantıcılık (paralel dağıtık işleme)', ['Yapısalcılık', 'Simgesel mantık programlama (kural tabanlı)', 'Gestalt alan kuramı'], 'Bağlantıcı modellerde bilgi tek bir yerde değil, ağdaki bağlantıların ağırlıklarında dağıtık olarak bulunur ve öğrenme bu ağırlıkların değişmesiyle olur.'),
  ('Frank Rosenblatt\'ın 1958\'de tanıttığı, girdileri ağırlıklandırıp eşik değerine göre karar veren ilk öğrenebilen yapay sinir ağı modeli hangisidir?', 'Algılayıcı', ['Mantık kuramcısı', 'Genel problem çözücü', 'Eliza programı'], 'Perceptron, örneklerden ağırlıklarını ayarlayarak sınıflandırma yapmayı öğrenebilen ilk yapay sinir ağı modellerindendir.'),
  ('John Anderson\'ın geliştirdiği ve bildirimsel bilgi ile "eğer-ise" kurallarından oluşan üretim sistemiyle insan bilişini modelleyen bilişsel mimari hangisidir?', 'ACT-R', ['Pandemonium', 'Genel Problem Çözücü', 'TRACE'], 'ACT-R, bildirimsel bellek birimleri ile işlemsel üretim kurallarını birleştirerek öğrenme, bellek ve problem çözmeyi bilgisayarda benzeten bir mimaridir.'),
  ('"Bedenlenmiş biliş" yaklaşımının temel savı hangisidir?', 'Düşünme, bedenin duyusal-motor deneyimlerinden ayrı düşünülemez', ['Zihin, bedenden tamamen bağımsız çalışan ve her donanıma aktarılabilen soyut bir yazılımdır', 'Bütün bilişsel süreçler doğuştan hazır modüllerle yürür', 'Biliş yalnızca dil aracılığıyla gerçekleşir'], 'Bu yaklaşım, kavramların ve düşüncenin beden hareketleri, algı ve çevresel bağlamla biçimlendiğini savunarak salt simgesel zihin görüşüne karşı çıkar.'),
  ('Franciscus Donders\'ın 1868\'de geliştirdiği "çıkarma yöntemi" neyi ölçmeyi amaçlar?', 'Bir zihinsel aşamanın süresini, iki görevin tepki süresi farkından', ['Bir uyarıcının algılanabildiği en düşük şiddeti', 'Bellekte aynı anda tutulabilen öğe sayısını ve bunların unutulma hızını', 'Beyin bölgelerindeki kan akışını'], 'Donders, basit tepki ile seçim gerektiren tepki süresini karşılaştırarak, aradaki farkın eklenen karar aşamasının süresini verdiğini ileri sürdü.'),
  ('İşlevsel manyetik rezonans görüntüleme (fMRI) beyin etkinliğini doğrudan değil, hangi dolaylı sinyal üzerinden ölçer?', 'Kandaki oksijen düzeyine bağlı değişimler', ['Radyoaktif işaretli şekerin beyin dokusundaki yayınımı', 'Beyin omurilik sıvısı basıncındaki değişimler', 'Kas gerginliğindeki küçük değişimler'], 'fMRI\'deki BOLD sinyali, etkin bölgelere giden oksijenli kan miktarındaki değişimlere dayanır; bu yüzden nöron etkinliğini dolaylı ve birkaç saniyelik gecikmeyle yansıtır.'),
  ('EEG ile fMRI karşılaştırıldığında EEG\'nin belirgin üstünlüğü hangisidir?', 'Zamansal çözünürlüğünün milisaniye düzeyinde yüksek olması', ['Derin beyin yapılarını tam olarak gösterebilmesi', 'Hiç elektrot gerektirmemesi ve katılımcının serbestçe dolaşabilmesi', 'Kan akışını doğrudan ölçebilmesi'], 'EEG elektriksel etkinliği anında kaydettiğinden zamanlamayı çok iyi gösterir; ancak etkinliğin beyinde tam olarak nerede oluştuğunu fMRI kadar iyi belirleyemez.'),
  ('Transkraniyal manyetik uyarım (TMS) yönteminin görüntüleme yöntemlerine göre sağladığı önemli avantaj nedir?', 'Bir bölgeyi geçici olarak aksatıp o bölgeyle davranış arasında nedensellik sınayabilmesi', ['Beynin tamamının ayrıntılı ve üç boyutlu yapısal haritasını tek seferde çıkarması', 'Kandaki hormon düzeylerini doğrudan ölçmesi', 'Tek tek nöronların kimyasal yapısını göstermesi'], 'Görüntüleme yalnızca ilişki gösterir; TMS ise belirli bir bölgenin çalışmasını kısa süre aksatarak o bölgenin görev için gerekli olup olmadığını sınamayı sağlar.'),
  ('Bir deneyde sık tekrarlanan seslerin arasına seyrek olarak farklı bir ses yerleştirilir ve beyinde bu nadir sese yaklaşık 300 milisaniye sonra belirgin bir olumlu dalga görülür. Olaya ilişkin bu potansiyel bileşeni hangisidir?', 'P300', ['N400', 'Alfa ritmi', 'Uyku iğciği'], 'P300, beklenmedik ya da görevle ilgili seyrek uyarıcılara karşı yaklaşık 300 ms\'de ortaya çıkan olumlu dalgadır ve dikkat ile uyarıcı değerlendirmesiyle ilişkilendirilir.'),
  ('Michael Gazzaniga, bölünmüş beyin hastalarının sol yarım kürelerinin, sağ yarım kürenin başlattığı davranışlar için akla yatkın ama uydurma gerekçeler ürettiğini gözlemlemiştir. Gazzaniga bu sol yarım küre sistemine ne ad vermiştir?', 'Yorumlayıcı', ['Merkezi yürütücü', 'Denetleyici dikkat sistemi', 'Bilişsel harita'], 'Sol yarım küredeki yorumlayıcı, nedenini bilmediği davranışları anlamlı bir öyküye oturtarak açıklamaya çalışır; bu, bilincin tutarlı bir anlatı kurma eğilimini gösterir.'),
  ('Broadbent\'in filtre modeline göre birden çok mesaj arasından hangisinin işleneceği seçimi nasıl yapılır?', 'Anlamdan önce, sesin yönü ve tonu gibi fiziksel özelliklere göre', ['Bütün mesajların anlamı çözüldükten sonra', 'Rastgele, kişinin isteğinden bağımsız olarak', 'Yalnızca uzun süreli bellekteki duygusal izlere ve kişisel önceliklere göre'], 'Broadbent, seçimin bilgi işlemenin erken bir aşamasında fiziksel özelliklere dayanarak yapıldığını ve dikkat edilmeyen mesajın anlam düzeyinde işlenmediğini savundu.'),
  ('Broadbent\'in "bölünmüş dizi" deneyinde bir kulağa 7-2-6, öbür kulağa 4-9-3 rakamları eşzamanlı verilmiştir. Katılımcıların çoğu rakamları hangi sırayla hatırlamayı yeğlemiştir?', '7-2-6-4-9-3', ['7-4-2-9-6-3', '4-7-9-2-3-6', '3-6-9-2-4-7'], 'Katılımcılar rakamları geliş sırasına göre çiftler hâlinde değil, kulak kulak hatırlamayı yeğlemiştir; Broadbent bunu kanalların fiziksel özelliklere göre seçildiğinin kanıtı saydı.'),
  ('Anne Treisman\'ın zayıflatma (attenuation) modeli Broadbent\'in filtre modelinden hangi yönüyle ayrılır?', 'Dikkat edilmeyen mesajın engellenmeyip zayıflatılarak işlenmesiyle', ['Seçimin bütünüyle tepki aşamasında, anlam çözüldükten sonra yapılmasıyla', 'Hiçbir filtre bulunmadığını savunmasıyla', 'Yalnızca görsel bilgiye uygulanmasıyla'], 'Treisman\'a göre ilgisiz kanal kapatılmaz, "sesi kısılır"; bu yüzden önemli ya da beklenen sözcükler zayıflatılmış kanaldan da bilince ulaşabilir.'),
  ('Deutsch ve Deutsch\'un 1963\'te önerdiği geç seçim kuramına göre dikkat seçimi hangi aşamada gerçekleşir?', 'Bütün girdilerin anlamı çözüldükten sonra, tepki verme aşamasına yakın', ['Duyu almaçlarında, uyarı sinir sistemine girmeden önce', 'Yalnızca uyarıcının şiddeti ölçülürken', 'Bilgi uzun süreli belleğe yerleştikten yıllar sonra'], 'Geç seçim kuramı, bütün mesajların anlam düzeyinde tam olarak işlendiğini, ancak hangisine tepki verileceğinin daha sonra seçildiğini savunur.'),
  ('Colin Cherry\'nin ikili dinleme deneylerinde katılımcıların bir kulağa gelen mesajı duydukları anda yüksek sesle tekrarlamasına ne ad verilir?', 'Gölgeleme', ['Öbekleme', 'Tarama', 'Maskeleme işlemi'], 'Gölgeleme (shadowing), katılımcının dikkatini bir kulağa vermesini sağlamak için kullanılan tekniktir; böylece öbür kulaktan neyin fark edildiği incelenebilir.'),
  ('Cherry\'nin gölgeleme deneylerinde katılımcılar dikkat edilmeyen kulakla ilgili en çok hangi değişikliği fark edebilmiştir?', 'Konuşanın erkek sesinden kadın sesine geçmesi', ['Konuşmanın İngilizceden Almancaya geçmesi ve sonra geri dönmesi', 'Aynı sözcüğün birkaç kez tekrarlanması', 'Mesajın konusunun değişmesi'], 'Katılımcılar dikkat edilmeyen kanalda sesin cinsiyeti ya da bir ton sesi gibi fiziksel değişiklikleri fark etmiş, dil ve içerik değişikliklerini ise büyük ölçüde gözden kaçırmıştır.'),
  ('Neville Moray 1959\'da dikkat edilmeyen kulağa aynı sözcük listesini 35 kez sunmuştur. Sonraki tanıma testinde ne bulunmuştur?', 'Sözcüklerin yeni sözcüklerden daha iyi tanınmadığı', ['Sözcüklerin tamamının, sırası da korunarak kusursuz biçimde hatırlandığı', 'Tekrar sayısı arttıkça gölgelemenin imkânsızlaştığı', 'Katılımcıların sözcükleri ters sırayla hatırladığı'], 'Çok sayıda tekrara rağmen sözcüklerin tanınmaması, dikkat edilmeyen kanaldaki bilginin belleğe çok az geçtiğini gösterdi; ancak aynı çalışmada kişinin kendi adına yönelik dikkat kaymaları da gözlendi.'),
  ('Görsel dikkati, ışığının düştüğü bölgedeki bilgiyi daha iyi işlenir kılan ve uzayda kaydırılabilen bir ışık huzmesine benzeten metafor hangisidir?', 'Spot ışığı metaforu', ['Ayna benlik metaforu', 'Buzdağı metaforu', 'Demir kafes metaforu'], 'Posner ve arkadaşlarının kullandığı spot ışığı benzetmesine göre dikkat görsel alanın belirli bir bölgesine yönelir ve o bölgedeki işlem daha hızlı ve doğru olur.'),
  ('Norman Mackworth\'ün İkinci Dünya Savaşı sırasında radar operatörlerinin sorunlarından yola çıkarak geliştirdiği "saat testi" dikkatin hangi yönünü ölçer?', 'Uzun süre seyrek hedefleri bekleyebilme, yani sürekli dikkati', ['İki görevi aynı anda yapabilme becerisini', 'Görsel tarama hızını', 'Renkleri ayırt etme hızını'], 'Mackworth saat testinde ibrenin seyrek olarak çift adım attığı anları yakalamak gerekir; performansın ilk yarım saatte belirgin biçimde düştüğü gözlenmiştir.'),
  ('Michael Posner\'ın ipucu paradigmasında hedefin çıkacağı yeri doğru gösteren ipuçlarından sonra tepkiler hızlanırken, yanlış yeri gösteren ipuçlarından sonra yavaşlar. Bu bulgu neyi gösterir?', 'Dikkatin gözler kıpırdamadan bir konuma yöneltilebildiğini', ['Gözlerin her zaman ipucunun gösterdiği yere bakmak zorunda olduğunu', 'İpuçlarının tepki süresini hiç etkilemediğini', 'Dikkatin yalnızca işitsel uyarıcılara yöneldiğini'], 'Katılımcılar gözlerini ortadaki noktadan ayırmadığı hâlde ipucu etkisi görülmesi, dikkatin örtük biçimde uzayda kaydırılabildiğini gösterir.'),
  ('Gözler bir noktaya sabitken dikkatin başka bir konuma kaydırılmasına ne ad verilir?', 'Örtük dikkat yönelimi', ['Sürekli dikkat', 'Bölünmüş dikkat', 'Seçici unutma'], 'Açık yönelimde göz ve baş uyarıcıya döner; örtük yönelimde ise göz hareketi olmadan yalnızca dikkat başka bir konuma kayar.'),
  ('Görüş alanının kenarında aniden yanıp sönen bir ışığın dikkati istemsizce çekmesi ile ekranın ortasındaki bir okun kişiyi bilinçli olarak dikkatini sağa vermeye yöneltmesi arasındaki fark nasıl adlandırılır?', 'Dışsal (refleksif) ve içsel (istemli) yönlendirme', ['Birincil ve ikincil pekiştirme tarifeleri', 'Yakınsak ve ıraksak düşünme', 'İleriye ve geriye ket vurma'], 'Ani çevresel uyarıcılar dikkati dışsal ve otomatik biçimde çeker; merkezdeki sembolik ipuçları ise kişinin hedefe yönelik, içsel kontrolüyle dikkatin yönlendirilmesini sağlar.'),
  ('Bir ekranda çok sayıda yeşil harf arasında tek bir kırmızı harf aranırken ekrandaki harf sayısı artırılırsa arama süresi nasıl değişir?', 'Neredeyse değişmez, çünkü hedef "göze batar"', ['Harf sayısı arttıkça kısalır, çünkü hedef daha belirgin olur', 'Harf sayısıyla doğrusal olarak artar', 'Harf sayısının karesiyle artar'], 'Tek bir temel özellikle (renk) ayrılan hedef dikkat öncesi ve paralel olarak bulunur; bu "fırlama" (pop-out) etkisinde çeldirici sayısı süreyi pek etkilemez.'),
  ('Kırmızı X\'ler ve yeşil T\'ler arasında kırmızı bir T aranan görevde, çeldirici sayısı arttıkça arama süresinin düzenli olarak uzamasının nedeni Treisman\'a göre nedir?', 'Hedefin renk-biçim birleşimiyle tanımlanıp öğelerin tek tek taranmasının gerekmesi', ['Kırmızı rengin görme sisteminde yeşilden daha geç ve daha yavaş işlenmesi', 'T harfinin X harfinden daha karmaşık olması', 'Çeldiricilerin bellekte unutulması'], 'Birleşim aramasında hedef tek bir özellikle ayrılamaz; özelliklerin bağlanması odaklanmış dikkat gerektirdiği için öğeler sırayla taranır ve süre çeldirici sayısıyla artar.'),
  ('Anne Treisman ve Garry Gelade\'nin 1980\'de ortaya koyduğu, temel görsel özelliklerin önce ayrı ayrı ve paralel çözümlendiğini, sonra dikkat yardımıyla nesne olarak birleştirildiğini savunan kuram hangisidir?', 'Özellik bütünleştirme kuramı', ['Şablon eşleme kuramı', 'Geon (bileşen) kuramı', 'Doğrudan algı kuramı'], 'Kuram, renk ve yönelim gibi özelliklerin dikkat öncesi aşamada kaydedildiğini, bunların doğru bağlanması için ise odaklanmış dikkatin "yapıştırıcı" görevi gördüğünü öne sürer.'),
  ('Hızlı dizisel görsel sunumda iki hedef ardı ardına geldiğinde, ilk hedeften sonraki yaklaşık 200–500 milisaniye içinde gelen ikinci hedefin sıklıkla fark edilmemesine ne ad verilir?', 'Dikkat kırpması', ['Kör nokta', 'Geriye doğru ket vurma', 'Geri ket vurma'], 'Raymond, Shapiro ve Arnell\'in tanımladığı dikkat kırpmasında, ilk hedefin işlenmesi sürerken ikinci hedef bilince ulaşamaz; çok kısa ya da daha uzun aralıklarda ise sorun azalır.'),
  ('Simons ve Levin\'in "kapı" deneyinde yol tarif eden bir yaya, önünden kapı taşıyan iki kişi geçerken konuştuğu kişinin başka biriyle değiştirildiğini çoğunlukla fark etmemiştir. Bu olgu nedir?', 'Değişim körlüğü', ['Prozopagnozi', 'Dikkat kırpması', 'Yanlış bilgi etkisi'], 'Değişim körlüğü, sahnedeki belirgin değişikliklerin, değişim anı bir kesintiyle örtüldüğünde fark edilmemesidir; ayrıntılı bir görsel temsili sürekli korumadığımızı gösterir.'),
  ('Rensink\'in "titreme" yönteminde iki fotoğraf arasında kısa boş bir ekranla gidip gelinir ve aradaki farkı bulmak çok uzun sürer. Boş ekran kaldırıldığında fark neden çabucak bulunur?', 'Değişimin dikkati otomatik çeken yerel bir hareket sinyali oluşturması', ['Fotoğrafların bu kez daha yüksek çözünürlükte ve daha uzun süre görülmesi', 'Boş ekran kısa süreli belleği güçlendirdiği için', 'Katılımcılar farkı önceden öğrendiği için'], 'Boş ekran olmadan değişen bölgede ani bir parlaklık değişimi olur ve dikkat oraya çekilir; kesinti bu sinyali gizlediğinde fark ancak tek tek bölgeler taranarak bulunur.'),
  ('Eriksen işaret görevinde ortadaki harfe yanıt verilirken, yanlarındaki harflerin farklı bir tepki gerektirdiği durumda tepkilerin yavaşlaması neyi gösterir?', 'Dışarıda tutulmaya çalışılan yakın uyarıcıların da işlenip tepkiyi etkilediğini', ['Ortadaki harfin hiç algılanmadığını', 'Yan harflerin görme alanında hiç görünmediğini ve yalnız ortadakinin seçildiğini', 'Kişinin harfleri okuyamadığını'], 'Yan uyarıcıların uyumsuz olduğu durumda ortaya çıkan gecikme, bu uyarıcıların seçimden kaçarak tepki seçimi düzeyine kadar işlendiğini gösterir.'),
  ('Sağ pariyetal lobunda inme geçiren bir hasta tabağının yalnızca sağ yarısındaki yemeği yiyor, saati çizerken bütün sayıları sağ tarafa yerleştiriyor. Görme yetisi sağlam olan bu hastadaki bozukluk hangisidir?', 'Tek yanlı uzamsal ihmal', ['Akromatopsi', 'Prosopagnozi', 'Kör görme'], 'Uzamsal ihmalde göz sağlam olduğu hâlde, genellikle sağ pariyetal hasar sonrası uzayın sol yarısına dikkat edilmez ve bu taraftaki uyarıcılar yok sayılır.'),
  ('Shiffrin ve Schneider\'in 1977\'deki ayrımına göre otomatik süreçlerin belirgin özelliği hangisidir?', 'Hızlı olmaları, kapasite gerektirmemeleri ve durdurulmalarının güç olması', ['Yavaş ilerlemeleri ve her adımda bilinçli denetim gerektirmeleri', 'Yalnızca yeni ve alışılmamış görevlerde ortaya çıkmaları', 'Başka bir görevle birlikte yapıldıklarında hemen ve tamamen bozulmaları'], 'Uzun alıştırmayla gelişen otomatik süreçler dikkat kaynağı tüketmez ve paralel yürür; denetimli süreçler ise yavaş, sıralı ve kapasite gerektiren süreçlerdir.'),
  ('Spelke, Hirst ve Neisser\'in 1976 çalışmasında iki öğrenci haftalarca alıştırma yaptıktan sonra hikâye okurken aynı anda dikte edilen sözcükleri yazabilmiş ve okuduklarını anlamaları bozulmamıştır. Bu bulgu neyi gösterir?', 'Bölünmüş dikkat becerisinin alıştırmayla büyük ölçüde geliştirilebileceğini', ['İnsanların doğuştan iki görevi aynı anda yapabildiğini ve alıştırmanın gereksiz olduğunu', 'Yazma işinin okumayı her koşulda kalıcı biçimde bozduğunu', 'Dikte edilen sözcüklerin anlamının hiç işlenemeyeceğini'], 'Uzun alıştırma sonrası iki karmaşık görevin birlikte yürütülebilmesi, dikkat kapasitesinin sabit olmadığını ve beceri kazanımıyla yükseltilebileceğini gösterir.'),
  ('Christopher Wickens\'ın çoklu kaynak kuramına göre aşağıdaki görev çiftlerinden hangisinin birbirini en az bozması beklenir?', 'Araba kullanırken radyodan haber dinlemek', ['Bir metni okurken başka bir metni gözden geçirmek', 'Telefonda konuşurken başka biriyle yüz yüze konuşmak', 'Harita okurken bir yol tabelasını okumak'], 'Wickens\'a göre farklı duyu kanalı ve işlem kodu kullanan görevler (görsel-motor sürüş ile işitsel-sözel dinleme) ayrı kaynaklardan beslendiği için birbirine daha az karışır.'),
  ('Strayer ve Johnston\'ın sürüş benzetimi çalışmalarında eller serbest telefonla konuşan sürücülerin kırmızı ışıkları daha sık kaçırdığı bulunmuştur. Bu bulgu en çok neyi gösterir?', 'Sürüşü bozan asıl etkenin telefonu tutmak değil, konuşmanın dikkat talebi olduğunu', ['Eller serbest telefonların sürüş için tamamen güvenli olduğunu ve risk taşımadığını', 'Radyo dinlemenin telefonla konuşmaktan daha çok dikkat dağıttığını', 'Kırmızı ışığın görme sistemi tarafından geç algılandığını'], 'Elleri serbest bırakan cihazlar da benzer bozulmaya yol açtığı için sorun motor değil, bilişseldir; aktif konuşma dikkat kaynaklarını sürüşten çeker.'),
  ('Bir öğrencinin aynı oturumda matematik problemleri ile yabancı dil sözcükleri arasında sürekli geçiş yaparken her geçişte bir miktar yavaşlaması hangi kavramla açıklanır?', 'Görev değiştirme maliyeti', ['Geri dönüş ketlenmesi', 'Fırlama etkisi', 'Aşırı öğrenme etkisi'], 'Görevler arasında geçerken zihnin yeni görev kurallarını yeniden yapılandırması zaman alır; bu nedenle geçiş denemelerinde tepkiler tekrarlı denemelere göre yavaştır.'),
  ('J. R. Simon\'ın adıyla anılan etkiye göre, sol eldeki tuşa basılması gereken bir uyarıcı ekranın sağ tarafında çıktığında ne olur?', 'Tepki, uyarıcı solda çıktığı duruma göre daha yavaş ve hatalı olur', ['Tepki, uyarıcının yerinden etkilenmez ve her iki durumda da aynı hızda kalır', 'Tepki, uyarıcı sağdayken her zaman daha hızlı olur', 'Kişi uyarıcıyı hiç fark etmez'], 'Uyarıcının konumu görevle ilgisiz olsa da otomatik olarak aynı taraftaki tepkiyi etkinleştirir; konum ile tepki tarafı uyuşmadığında çatışma oluşur ve tepki yavaşlar.'),
  ('Hafta sonu markete gitmek için yola çıkan birinin dalgınlıkla her gün gittiği iş yerinin yoluna sapması James Reason\'ın sınıflamasında hangi hatadır?', 'Yakalama (alışkanlık) hatası', ['Bilgi eksikliği hatası', 'Algısal yanılsama', 'Geriye dönük bellek yitimi'], 'Yakalama hatalarında, sık uygulanan ve güçlü bir alışkanlık dizisi, dikkat başka yerdeyken amaçlanan daha zayıf eylem dizisinin yerine geçer.'),
  ('Miyake ve arkadaşlarının 2000 tarihli çalışmasında birbiriyle ilişkili ama ayrışabilen üç temel yürütücü işlev hangileri olarak belirlenmiştir?', 'Ketleme, görevler arası geçiş ve güncelleme', ['Kodlama, depolama ve geri getirme', 'Duyum, algı ve dikkat', 'Tanıma, hatırlama ve yeniden öğrenme'], 'Gizil değişken analizleriyle yapılan çalışma, baskın tepkileri engelleme, zihinsel set değiştirme ve çalışma belleğini güncelleme işlevlerini ayırt etti.'),
  ('Wisconsin Kart Eşleme Testi\'nde, ön lob hasarlı hastaların eşleme kuralı değiştikten sonra eski kurala göre kart eşlemeyi sürdürmesine ne ad verilir?', 'Perseverasyon', ['Konfabulasyon', 'Prozopagnozi', 'Dizi konum etkisi'], 'Kural renkten biçime geçtiğinde eski kurala takılı kalmak, ön lobun esnek kural değiştirme işlevindeki bozukluğun belirtisidir.'),
  ('Tim Shallice\'in geliştirdiği ve renkli topların en az hamlede belirli bir dizilime getirilmesini isteyen "Londra Kulesi" görevi en çok hangi işlevi ölçer?', 'Planlama', ['Duyusal eşik', 'Sözcük dağarcığı', 'Yüz tanıma'], 'Katılımcının hamle dizisini önceden zihninde tasarlaması gerektiğinden görev, ön lobla ilişkili planlama yeteneğinin ölçülmesinde yaygın olarak kullanılır.'),
  ('Bir uyarıcı çıktığında tuşa basılması, başka bir uyarıcı çıktığında ise basılmaması gereken "Git/Gitme" görevinde, bir uyarıcıda tuşa basmama hatası değil, basma hatası yapmak hangi işlevin zayıflığını gösterir?', 'Ketleme', ['Uzun süreli bellek kapasitesi', 'Görsel keskinlik', 'Sözel akıcılık'], 'Sık görülen "git" uyarıcısı güçlü bir basma eğilimi oluşturur; "gitme" uyarıcısında bu baskın tepkiyi durduramamak ketleme denetiminin yetersizliğini gösterir.'),
  ('Bir öğrencinin bir sözcük çiftini çalıştıktan hemen sonra "Bunu yarın kesinlikle hatırlarım" diye verdiği yargıya ne ad verilir ve bu yargılar genellikle hangi durumda daha isabetlidir?', 'Öğrenme yargısı; çalışmadan biraz sonra verildiğinde', ['Tanıma yargısı; çalışırken anında verildiğinde', 'Tanıdıklık yargısı; hiç çalışılmadan önce verildiğinde', 'Kaynak yargısı; sınavdan sonra verildiğinde'], 'Hemen verilen öğrenme yargıları kısa süreli bellekteki geçici erişilebilirlikten etkilenir; gecikmeli verildiğinde ise uzun süreli bellekten geri getirmeye dayandığı için daha isabetli olur.'),
  ('John Sweller\'in bilişsel yük kuramına göre konuyla ilgisiz süslemeler ve dağınık sunum biçimi nedeniyle öğrenene binen gereksiz yük hangi adla anılır?', 'Konu dışı (dışsal) yük', ['Asıl (içsel) yük', 'Yararlı (öğrenmeye dönük) yük', 'Duyusal yük'], 'Sweller, öğrenme malzemesinin doğasından gelen içsel yük ile kötü tasarımdan doğan dışsal yükü ayırır; iyi öğretim tasarımı dışsal yükü azaltmayı hedefler.'),
  ('Örüntü tanımada şablon eşleme kuramına yöneltilen en temel eleştiri hangisidir?', 'Aynı harfin sayısız yazı biçimi, boyutu ve açısı için ayrı şablon gerekeceği', ['Harflerin yalnızca renklerine göre tanınabileceğini öngörmesi', 'Bağlamın tanımayı her durumda tümüyle belirlediğini ileri sürmesi', 'Tanımanın yalnızca işitsel uyarıcılarda ve konuşmada geçerli olduğunu varsayması'], 'Uyarıcıyı bellekteki birebir kopyalarla karşılaştıran şablon görüşü, el yazısı gibi büyük çeşitlilik gösteren girdileri açıklamak için akla aykırı sayıda şablon gerektirir.'),
  ('Oliver Selfridge\'in 1959\'da önerdiği, imge, özellik, bilişsel ve karar "cinleri"nin birbirine bağırarak harf tanıdığı örüntü tanıma modeli hangisidir?', 'Pandemonium', ['Perceptron', 'Logic Theorist', 'Bölünmüş dizi'], 'Pandemonium modelinde özellik cinleri yatay ya da eğik çizgi gibi özellikleri saptar, bilişsel cinler eşleşmeye göre bağırır ve karar cini en yüksek sesi seçer.'),
  ('Kedilerin görme korteksinde belirli yönelimdeki çizgilere seçici yanıt veren hücreleri keşfederek 1981 Nobel Tıp Ödülü\'nü paylaşan araştırmacılar kimlerdir?', 'David Hubel ve Torsten Wiesel', ['Hermann von Helmholtz ve Thomas Young', 'Richard Gregory ve James Gibson', 'Eleanor Gibson ve Richard Walk'], 'Hubel ve Wiesel\'in buldukları basit ve karmaşık hücreler, görsel sistemde özellik dedektörlerinin varlığına fizyolojik kanıt sağlamıştır.'),
  ('Hubel ve Wiesel\'in bulgularında, belirli yönelimdeki bir çizgiye yalnızca alıcı alanın tam belli bir yerinde değil, alan içinde nerede olursa olsun ve özellikle hareket ettiğinde yanıt veren hücreler hangi adla anılır?', 'Karmaşık hücreler', ['Basit hücreler', 'Çubuk hücreler', 'Ganglion hücreleri'], 'Basit hücreler çizginin tam konumuna duyarlıdır; karmaşık hücreler ise yönelim seçiciliğini korurken konumdan daha bağımsızdır ve çoğu zaman harekete güçlü yanıt verir.'),
  ('Reicher\'in 1969 deneyinde çok kısa gösterilen bir harf, tek başına sunulduğunda değil de anlamlı bir sözcüğün içinde sunulduğunda daha doğru tanınmıştır. Bu bulguya ne ad verilir?', 'Sözcük üstünlüğü etkisi', ['Resim üstünlüğü etkisi', 'Dizi konum etkisi', 'Yüz ters çevirme etkisi'], 'Sözcük bağlamı harf tanımayı kolaylaştırır; bu etki, algıda üst düzey bilginin (sözcük bilgisinin) alt düzey işlemeyi desteklediğini gösterir.'),
  ('Aynı belirsiz şekil "THE" sözcüğünde H, "CAT" sözcüğünde A olarak okunuyor. Bu durum hangi işlemleme türünün gücünü gösterir?', 'Yukarıdan aşağıya (kavram güdümlü) işlemleme', ['Aşağıdan yukarıya (veri güdümlü) işlemleme', 'Duyusal uyum', 'Sinyal saptama ölçütü'], 'Fiziksel olarak aynı uyarıcının sözcük bağlamına göre farklı yorumlanması, beklenti ve bilginin algıyı biçimlendirdiğini gösterir.'),
  ('Okuması güç bir el yazısını tek tek harflerden çok cümlenin anlamından yararlanarak çözmeye çalışan kişi algıda hangi kaynağa daha çok dayanmaktadır?', 'Önceki bilgi ve bağlama', ['Yalnızca harflerin fiziksel çizgilerine', 'Duyu almaçlarının uyum düzeyine', 'Retinadaki koni yoğunluğuna'], 'Bağlam ve önceki bilgi, eksik ya da belirsiz duyusal girdiyi tamamlamak için kullanılır; bu, kavram güdümlü işlemlemenin gündelik bir örneğidir.'),
  ('Stephen Palmer\'ın 1975 deneyinde katılımcılara önce bir mutfak sahnesi gösterilmiş, ardından kısa süre bir nesne sunulmuştur. Hangi nesne daha doğru tanınmıştır?', 'Sahneye uygun bir somun ekmek', ['Sahneyle ilgisiz bir posta kutusu', 'Ekmeğe biçimce benzeyen bir posta kutusu', 'Sahneden bağımsız olarak üç nesne de eşit doğrulukla'], 'Sahne bağlamı, uygun nesnelere ilişkin beklenti oluşturarak tanımayı kolaylaştırır; bağlama uymayan nesneler daha zor tanınır.'),
  ('Irving Biederman\'ın "bileşenlerle tanıma" kuramına göre nesneler zihinde hangi temel birimlerden oluşan yapılar olarak temsil edilir?', 'Silindir ve koni gibi basit üç boyutlu biçimler', ['Retinadaki tek tek ışık noktaları', 'Nesnelerin sözlükteki tanımları ve bunların dilbilgisel yapıları', 'Nesnelerin sözel tanımları'], 'Biederman, yaklaşık 36 temel geometrik bileşenin (geon) farklı biçimlerde birleşmesiyle nesnelerin tanındığını ve bu bileşenlerin bakış açısından büyük ölçüde bağımsız olduğunu öne sürdü.'),
  ('Richard Gregory\'nin algıyı "hipotezler" olarak nitelendirmesi hangi görüşü yansıtır?', 'Algının eksik duyusal veriden bilgiyle yapılan çıkarımlara dayandığını', ['Algının çevredeki bilginin hiçbir aracı olmadan doğrudan alınmasından ibaret olduğunu', 'Algının yalnızca doğuştan gelen reflekslerle belirlendiğini', 'Algının dil öğrenilmeden hiç gerçekleşemeyeceğini'], 'Gregory\'nin yapılandırmacı yaklaşımına göre beyin, belirsiz duyusal girdiye en olası açıklamayı bulmak için önceki bilgiyi kullanır; yanılsamalar yanlış hipotezlerin sonucudur.'),
  ('James J. Gibson\'ın "doğrudan algı" kuramı Gregory\'nin yaklaşımından en çok hangi noktada ayrılır?', 'Optik dizilimdeki zengin bilginin çıkarım gerekmeden algılandığını savunması', ['Algıda önceki bilginin ve beklentilerin belirleyici olduğunu savunması', 'Algının laboratuvarda yalnız durağan resimlerle incelenmesi gerektiğini savunması', 'Algının bütünüyle öğrenmeyle kazanıldığını savunması'], 'Gibson\'a göre hareket eden gözlemci için ışık dizilimi, yüzeyler ve uzaklıklar hakkında yeterli bilgi taşır; zihinsel çıkarıma gerek yoktur.'),
  ('Gibson\'ın "olanak sağlama" (affordance) kavramına en iyi örnek hangisidir?', 'Diz yüksekliğindeki düz bir yüzeyin oturma olanağı sunduğunun doğrudan görülmesi', ['Bir sandalyenin adının çocuğa öğretilmesi', 'Bir sandalyenin fiyatının hesaplanması', 'Bir sandalyenin hangi fabrikada ve hangi yıl üretildiğinin hatırlanması'], 'Olanak sağlama, çevredeki nesnelerin bir canlıya sunduğu eylem fırsatlarıdır; Gibson bunların nesnenin anlamı olarak doğrudan algılandığını savunur.'),
  ('İleriye doğru hareket eden bir gözlemcinin görüş alanında, hedeflenen noktadan dışarıya doğru akan doku örüntüsüne ne ad verilir?', 'Optik akış', ['Optik kiazma', 'Kör nokta', 'Retinal ardıl imge'], 'Optik akışın merkezindeki genişleme noktası, hareketin yönünü gösterir; Gibson bu bilginin yön bulma ve çarpışmadan kaçınmada doğrudan kullanıldığını savundu.'),
  ('Nancy Kanwisher ve arkadaşlarının 1997\'de yüzlere diğer nesnelerden çok daha güçlü yanıt verdiğini gösterdiği, şakak lobunun alt yüzündeki bölgeye ne ad verilir?', 'İğsi (fusiform) yüz alanı', ['Broca alanı', 'Birincil işitme korteksi', 'Birincil motor korteks'], 'fMRI çalışmaları, iğsi girustaki bu bölgenin yüz görüntülerine seçici olarak etkinleştiğini göstermiş ve yüz algısının özelleşmiş bir sistem olduğu görüşünü desteklemiştir.'),
  ('Yüzler baş aşağı çevrildiğinde tanınmalarının, evler ya da arabalar gibi diğer nesnelerin baş aşağı çevrilmesine göre çok daha fazla zorlaşmasına ne ad verilir?', 'Yüz ters çevirme etkisi', ['Fırlama etkisi', 'Bütünün önceliği etkisi', 'Biçim değişmezliği'], 'Yin\'in 1969\'da gösterdiği bu etki, yüzlerin parçaların birbirine göre yerleşimine dayanan bütüncül biçimde işlendiğini ve ters çevirmenin bu işlemi bozduğunu düşündürür.'),
  ('Gözleri ve ağzı kendi yerinde ters çevrilmiş bir yüz fotoğrafı baş aşağı gösterildiğinde gariplik pek fark edilmezken, düz çevrildiğinde ürkütücü görünür. Bu yanılsamanın adı nedir?', 'Thatcher yanılsaması', ['Ponzo yanılsaması', 'Ames odası', 'Kanizsa üçgeni'], 'Peter Thompson\'ın 1980\'de tanımladığı bu yanılsama, ters yüzlerde özelliklerin birbirine göre ilişkisinin zayıf işlendiğini gösterir.'),
  ('Bir hastanın annesini gördüğünde onun tıpatıp aynısı olan bir sahtekâr olduğuna inanması, ancak telefonda sesini duyunca onu annesi olarak kabul etmesi hangi sanrıdır?', 'Capgras sanrısı', ['Kişisel masal', 'Korsakoff sendromu', 'Hayali seyirci'], 'Capgras sanrısında yüz görsel olarak tanınır ama tanıdıklığa eşlik eden duygusal tepki eksik kalır; kişi bu uyumsuzluğu sevdiğinin yerine bir sahtekâr konduğu inancıyla açıklar.'),
  ('Bulutlarda, prizlerde ya da araba ön görünümlerinde yüz görme eğilimine ne ad verilir?', 'Pareidoli', ['Prozopagnozi', 'Sinestezi', 'Halüsinasyon'], 'Pareidoli, belirsiz uyarıcılarda tanıdık örüntüler, özellikle yüzler görme eğilimidir; görme sisteminin yüzleri saptamaya ne kadar hazır olduğunu gösterir.'),
  ('Görme keskinliği yeterli olduğu hâlde bir nesnenin biçimini algılayamayan, örneğin bir çizimi kopyalayamayan ve basit şekilleri eşleyemeyen hastadaki agnozi türü hangisidir?', 'Algısal (apersepsiyon) agnozi', ['Çağrışımsal (asosiyatif) agnozi', 'İşitsel agnozi', 'Prozopagnozi'], 'Algısal agnozide sorun biçimin bütünleşik olarak kurulmasındadır; hasta parçaları görür ama tutarlı bir şekil oluşturamaz, bu yüzden kopyalama da bozulur.'),
  ('Oliver Sacks\'ın ünlü kitabına adını veren, karısının başını şapkası sanarak tutmaya çalışan müzik profesörü Dr. P.\'nin bozukluğu hangi gruba girer?', 'Görsel agnozi', ['İşitsel halüsinasyon', 'Uzamsal ihmal', 'Geriye dönük bellek yitimi'], 'Dr. P. görme keskinliği yerinde olduğu hâlde nesneleri ve yüzleri tanıyamıyordu; Sacks\'ın "Karısını Şapka Sanan Adam" adlı kitabı görsel agnoziyi geniş kitlelere tanıttı.'),
  ('Ungerleider ve Mishkin\'in iki görsel yol ayrımına göre şakak lobuna uzanan karın (ventral) yol hangi işlevden sorumludur?', 'Nesnenin ne olduğunun tanınması', ['Nesnenin konumunun ve hareketinin izlenmesi', 'Göz bebeğinin ışığa göre ayarlanması', 'Sesin geldiği yönün belirlenmesi'], 'Ventral "ne" yolu oksipitalden şakak lobuna uzanarak nesne tanımada; dorsal "nerede" yolu ise pariyetal loba uzanarak uzamsal konumun işlenmesinde rol oynar.'),
  ('Birincil görme korteksi hasarı nedeniyle görme alanının bir bölümünde hiçbir şey görmediğini söyleyen hastaların, o bölgedeki uyarıcıların yerini tahmin etmeye zorlandığında şans düzeyinin çok üstünde başarı göstermesine ne ad verilir?', 'Kör görme', ['Kör nokta', 'Değişim körlüğü', 'Dikkatsizlik körlüğü'], 'Lawrence Weiskrantz\'ın incelediği kör görme, bilinçli görsel deneyim olmadan da bazı görsel bilgilerin işlenip davranışı yönlendirebildiğini gösterir.'),
  ('Beyin hasarı sonrası nesneleri durağanken görebilen ama hareketi algılayamayan, örneğin bardağa dökülen çayı donmuş bir buz sütunu gibi gören hastanın bozukluğu hangisidir?', 'Akinetopsi (hareket körlüğü)', ['Akromatopsi', 'Prozopagnozi', 'Simultanagnozi (eşzamanlı agnozi)'], 'Zihl\'in 1983\'te tanımladığı L.M. hastası, hareket işlemede kritik olan MT/V5 bölgesindeki hasar nedeniyle hareketi ardışık donmuş görüntüler olarak algılıyordu.'),
  ('Gözleri sağlam olduğu hâlde beyin hasarı sonrası dünyayı gri tonlarda görmeye başlayan bir ressamın durumu hangi bozuklukla açıklanır ve hangi görsel bölge ile ilişkilidir?', 'Serebral akromatopsi; V4 bölgesi', ['Akinetopsi; V5 bölgesi', 'Kör görme; birincil görme korteksi', 'Prozopagnozi; iğsi yüz alanı'], 'Serebral akromatopside retinadaki koniler sağlamdır; renk bilgisini işleyen V4 bölgesindeki hasar nedeniyle renk deneyimi yitirilir.'),
  ('Birbirine doğru yaklaşan iki eğik çizginin arasına çizilen eşit uzunluktaki iki yatay çubuktan, çizgilerin daralan ucuna yakın olanın daha uzun görünmesi hangi yanılsamadır?', 'Ponzo yanılsaması', ['Müller-Lyer yanılsaması', 'Zöllner yanılsaması', 'Hering yanılsaması'], 'Ponzo yanılsamasında yaklaşan çizgiler demiryolu gibi derinlik ipucu verir; uzakta sanılan çubuk, retinadaki görüntüsü aynı olduğu için daha büyük yorumlanır.'),
  ('Bir köşesi diğerinden çok daha uzakta olduğu hâlde önden bakıldığında sıradan dikdörtgen bir oda gibi görünen ve içindeki insanları dev ya da cüce gösteren düzenek hangisidir?', 'Ames odası', ['Necker küpü', 'Penrose üçgeni', 'Kanizsa üçgeni'], 'Ames odasında beyin odanın dikdörtgen olduğunu varsayar; bu yüzden uzak köşedeki kişi küçük, yakın köşedeki kişi büyük algılanır ve büyüklük değişmezliği bozulur.'),
  ('Üç "Pac-Man" biçiminin ağzı içe bakacak şekilde yerleştirilmesiyle, çizilmemiş olduğu hâlde parlak beyaz bir üçgen görülmesi algının hangi özelliğini gösterir?', 'Yanıltıcı (öznel) kenar oluşturma', ['Duyusal uyum', 'Renk ve parlaklık değişmezliği', 'Retinal farklılık'], 'Kanizsa üçgeninde görme sistemi eksik kenarları tamamlayarak fiziksel olarak var olmayan kenarlar ve parlaklık farkı üretir.'),
  ('Bir tel kafes küpün çizimine bakıldığında hangi yüzün önde olduğunun kendiliğinden ve tekrar tekrar değişmesi hangi şekille ilişkilidir?', 'Necker küpü', ['Ames odası', 'Hermann ızgarası', 'Ebbinghaus daireleri'], 'Necker küpü derinlik bakımından iki eşit olası yoruma izin verir; beyin bu yorumlar arasında kendiliğinden geçiş yapar.'),
  ('Aynı büyüklükteki iki daireden büyük dairelerle çevrili olanın küçük, küçük dairelerle çevrili olanın büyük görünmesine ne ad verilir?', 'Ebbinghaus (Titchener) yanılsaması', ['Ponzo yanılsaması', 'Hermann ızgarası (yanal ketlenme) yanılsaması', 'Mach bantları'], 'Ebbinghaus yanılsamasında hedefin büyüklüğü çevredeki öğelerle karşılaştırılarak değerlendirilir; büyüklük algısının bağlama göreli olduğunu gösterir.'),
  ('Bir şelaleye bir süre baktıktan sonra yanındaki kayalara bakan kişinin kayaları yukarı doğru hareket ediyor gibi görmesi hangi olgudur?', 'Hareket ardıl etkisi', ['Göreli hareket ipucu', 'Fi olayı', 'Kendiliğinden hareket etkisi'], 'Aşağı yönlü harekete duyarlı nöronlar uzun süre uyarıldıktan sonra yorulur; karşıt yöndeki nöronların göreli üstünlüğü durağan sahnede ters yönde hareket algısı doğurur.'),
  ('Her köşesi ayrı ayrı mantıklı görünen ama bütün olarak üç boyutlu uzayda var olamayacak bir üçgen çizimi hangi adla bilinir?', 'Penrose üçgeni (olanaksız üçgen)', ['Kanizsa üçgeni (öznel kontur üçgeni)', 'Sierpinski üçgeni (kesirli üçgen)', 'Pascal üçgeni (sayı üçgeni)'], 'Penrose üçgeni, yerel derinlik ipuçlarının birbiriyle tutarsız birleştirilmesiyle oluşan olanaksız bir şekildir; görme sisteminin parçaları yerel olarak yorumladığını gösterir.'),
  ('Kişinin gizlenmiş gerçek eli ile önündeki lastik el aynı anda fırçayla okşandığında, bir süre sonra lastik eli kendi eli gibi hissetmesi hangi olguyu gösterir?', 'Beden sahipliği algısının görme ve dokunmanın bütünleşmesiyle oluştuğunu', ['Dokunma duyusunun görmeden tamamen bağımsız çalıştığını ve etkilenmediğini', 'Lastik elin gerçek eldeki almaçları uyardığını', 'Kişinin hipnoz altında olduğunu'], 'Botvinick ve Cohen\'in 1998 lastik el yanılsaması, eşzamanlı görsel ve dokunsal uyarımın beynin beden haritasını değiştirebildiğini gösterir.'),
  ('Ağırlıkları eşit olan küçük ve büyük iki kutudan küçük olanın kaldırıldığında daha ağır hissedilmesine ne ad verilir?', 'Büyüklük-ağırlık yanılsaması', ['Weber yanılsaması', 'Müller-Lyer yanılsaması', 'Kinestetik uyum'], 'Charpentier\'nin tanımladığı bu yanılsamada büyük nesnenin daha ağır olacağı beklentisiyle kas kuvveti ayarlanır; beklenti karşılanmayınca küçük nesne daha ağır algılanır.'),
  ('Açık ve koyu kareler arasındaki harç çizgileri tamamen paralel olduğu hâlde, kareler yarımşar kaydırıldığında çizgilerin eğik görünmesi hangi yanılsamadır?', 'Kafe duvarı yanılsaması', ['Necker yanılsaması', 'Ames yanılsaması', 'Ay yanılsaması'], 'İlk kez Bristol\'deki bir kafenin duvarında fark edilen bu yanılsama, karşıtlık sınırlarının yerel olarak yanlış yönelim sinyalleri üretmesinden kaynaklanır.'),
  ('Fechner yasasına göre algılanan duyum şiddeti ile fiziksel uyarıcı şiddeti arasındaki ilişki nasıldır?', 'Duyum, uyarıcı şiddetinin logaritmasıyla orantılı artar', ['Duyum, uyarıcı şiddetiyle doğru orantılı ve her aralıkta aynı hızla artar', 'Duyum, uyarıcı şiddetinin karesiyle orantılı olarak artar', 'Duyum, uyarıcı şiddeti arttıkça azalır'], 'Fechner, Weber\'in bulgusundan yola çıkarak eşit duyum artışları için uyarıcının sabit oranda artması gerektiğini ve bunun logaritmik bir ilişki doğurduğunu ileri sürdü.'),
  ('Bir eşik ölçümünde deneyci sesi duyulmayacak kadar zayıftan başlatıp adım adım artırıyor ve katılımcının "duydum" dediği noktayı kaydediyor; ardından duyulur bir düzeyden başlayıp azaltıyor. Bu hangi psikofizik yöntemdir?', 'Sınırlar yöntemi', ['Sabit uyarıcılar yöntemi', 'Büyüklük kestirimi', 'Ayarlama yöntemi'], 'Sınırlar yönteminde uyarıcı artan ve azalan dizilerle sunulur; yanıtın değiştiği noktaların ortalaması eşik olarak alınır.'),
  ('Bir duyu için Weber kesrinin çok küçük olması ne anlama gelir?', 'O duyuda çok küçük göreli değişikliklerin bile fark edilebildiğini', ['O duyunun uyarıcılara karşı hiç uyum göstermediğini', 'O duyunun mutlak eşiğinin çok yüksek olduğunu', 'O duyuda farkın sezilmesi için uyarıcının iki katına çıkması gerektiğini'], 'Weber kesri, fark edilen en küçük değişimin başlangıç şiddetine oranıdır; oran küçükse küçük göreli farklar bile algılanır, yani ayırt etme duyarlılığı yüksektir.'),
  ('Gustav Fechner duyumu dolaylı yoldan ölçmek için bir ölçek kurmuştur. Fechner bu ölçekte duyumun eşit birimleri olarak neyi kabul etmiştir?', 'Fark edilebilir en küçük fark', ['Saniyedeki sinir uyarısı sayısı', 'Desibel ölçeği', 'Retinadaki koni sayısı'], 'Fechner, fark edilebilir en küçük farkları duyumun eşit birimleri olarak kabul edip bunları toplayarak duyum ölçeğini kurdu.'),
  ('Bir radyoloğun gerçekte tümör bulunmayan bir filmde "tümör var" demesi sinyal saptama kuramında hangi sonuçla adlandırılır?', 'Yanlış alarm', ['İsabet', 'Kaçırma', 'Doğru ret'], 'Sinyal yokken "var" yanıtı yanlış alarmdır; sinyal varken "var" isabet, sinyal varken "yok" kaçırma, sinyal yokken "yok" doğru rettir.'),
  ('Bir güvenlik görevlisi, tehlikeli bir nesneyi kaçırmanın bedeli çok ağır olduğu için şüphelendiği her çantayı açtırmaya başlıyor. Sinyal saptama kuramına göre bu durumda ne beklenir?', 'İsabetler artar, ancak yanlış alarmlar da artar', ['İsabetler artar, yanlış alarmlar ise sıfıra iner', 'Hem isabetler hem yanlış alarmlar azalır', 'Görevlinin duyarlılığı (d′) kendiliğinden artar'], 'Karar ölçütünün gevşetilmesi daha çok "var" yanıtına yol açar; bu hem isabetleri hem de yanlış alarmları artırır, ama ayırt etme duyarlılığını değiştirmez.'),
  ('Bir dinleme deneyinde iki katılımcının isabet oranları aynıdır, ancak A\'nın yanlış alarm oranı B\'ninkinden çok daha yüksektir. Bu bilgiye göre hangisi söylenebilir?', 'B\'nin sinyali gürültüden ayırt etme duyarlılığı daha yüksektir', ['İki katılımcının duyarlılığı kesinlikle eşittir, aralarında hiçbir fark yoktur', 'A\'nın sinyali ayırt etme duyarlılığı daha yüksektir', 'A daha temkinli bir karar ölçütü kullanmaktadır'], 'Aynı isabet oranına daha az yanlış alarmla ulaşmak daha iyi ayırt etme demektir; A ise sinyal yokken de sık "var" dediği için daha düşük duyarlılık ve gevşek ölçüt gösterir.'),
  ('Sinyal saptama kuramını psikofiziğe kazandıran 1966 tarihli "Signal Detection Theory and Psychophysics" adlı kitabın yazarları kimlerdir?', 'David Green ve John Swets', ['Gustav Fechner ve Ernst Weber', 'Richard Atkinson ve Richard Shiffrin', 'Daniel Kahneman ve Amos Tversky'], 'Green ve Swets, radar mühendisliğinden gelen sinyal saptama düşüncesini algı araştırmalarına uygulayarak klasik eşik kavramını yeniden tanımladılar.'),
  ('Gunnar Johansson\'ın, karanlıkta yürüyen bir kişinin eklemlerine yalnızca birkaç ışık noktası takarak yaptığı gösterimlerde izleyiciler ne algılamıştır?', 'Noktalar hareket edince yürüyen bir insanı hemen', ['Noktaların yalnızca rastgele yanıp sönen ışıklar olduğunu', 'Hareketin hiç algılanamadığını ve noktaların durgun göründüğünü', 'Noktaların bir harf dizisi oluşturduğunu'], 'Durağanken anlamsız görünen nokta kümeleri hareket edince kolayca insan figürü olarak algılanır; bu biyolojik hareket algısının gücünü gösterir.'),
  ('Bulutlu bir gecede hızla akan bulutların arkasındaki Ay\'ın bulutlara ters yönde hareket ediyormuş gibi görünmesi hangi olguya örnektir?', 'Uyarılmış (göreli) hareket', ['Kendiliğinden hareket etkisi', 'Hareket ardıl etkisi', 'Fi olayı'], 'Görme sistemi geniş çerçeveyi durağan kabul etme eğilimindedir; çerçeve (bulutlar) hareket edince, içindeki küçük nesne (Ay) hareket ediyormuş gibi algılanır.'),
  ('Alçak frekanslı bir sesin sağdan mı soldan mı geldiğini belirlerken beynin en çok kullandığı ipucu hangisidir?', 'Sesin iki kulağa ulaşma zamanları arasındaki fark', ['Sesin iki kulakta oluşturduğu şiddet (yüksellik) farkı', 'Sesin kulak kepçesindeki yankısının rengi', 'Sesin frekansının zamanla değişmesi'], 'Alçak frekanslı seslerin dalga boyu baştan büyük olduğu için şiddet farkı küçüktür; bu seslerde yön, iki kulak arasındaki varış zamanı farkından çıkarılır.'),
  ('Ekranda "ga" diyen birinin dudak hareketleri gösterilirken eşzamanlı olarak "ba" sesi dinletildiğinde birçok kişinin "da" duyması hangi etkidir?', 'McGurk etkisi', ['Stroop etkisi', 'Zeigarnik etkisi', 'Kokteyl partisi etkisi'], 'McGurk ve MacDonald\'ın 1976\'da tanımladığı etki, konuşma algısında görsel ve işitsel bilginin otomatik olarak birleştirildiğini gösterir.'),
  ('Bir cümlede bir sesbirim çıkarılıp yerine öksürük sesi konduğunda dinleyicilerin eksik sesi duyduklarını sanmaları ve öksürüğün yerini belirleyememeleri hangi olgudur?', 'Sesbirimsel tamamlama etkisi', ['Kategorik algı', 'Ekoik bellek', 'Bölünmüş dikkat etkisi'], 'Richard Warren\'ın 1970\'te gösterdiği bu etki, dinleyicinin bağlamı kullanarak eksik konuşma seslerini algısal olarak tamamladığını gösterir.'),
  ('Bilmediğimiz bir yabancı dili dinlerken konuşmanın aralıksız bir ses akışı gibi gelmesi, oysa kendi dilimizde sözcükleri ayrı ayrı duymamız konuşma algısındaki hangi sorunu gösterir?', 'Bölütleme (sözcük sınırı) sorunu', ['Ses yerelleştirme sorunu', 'Duyusal eşik sorunu', 'Koklea hasarına bağlı işitme kaybı sorunu'], 'Fiziksel konuşma sinyalinde sözcükler arasında çoğu zaman sessizlik yoktur; sınırlar dil bilgisi ve sözcük bilgisi kullanılarak dinleyici tarafından çıkarılır.'),
  ('Pergelin iki ucunun ayrı ayrı hissedilebildiği en küçük aralık parmak ucunda çok küçük, sırtta ise çok büyüktür. Bu farkın temel nedeni nedir?', 'Parmak ucunda almaç yoğunluğunun ve beyindeki temsilin daha büyük olması', ['Sırttaki derinin daha ince olması', 'Parmak ucunun sıcaklık ve basınç değişimlerine karşı daha duyarsız olması', 'Sırttaki sinirlerin daha hızlı iletim yapması'], 'İki nokta eşiği, almaç yoğunluğuna ve somatosensoriyel kortekste ayrılan alanın büyüklüğüne bağlıdır; parmak uçları bu açıdan en zengin bölgelerdendir.'),
  ('Kolu kesilmiş birinin artık var olmayan kolunda ağrı ya da kaşıntı hissetmesine ne ad verilir?', 'Hayalet uzuv duyumu', ['Kinestetik uyum', 'Halüsinasyon', 'Sinestezi'], 'Hayalet uzuv deneyimi, beden haritasının beyinde var olmayı sürdürdüğünü ve duyumun almaçlar değil, beyin tarafından oluşturulduğunu gösterir.'),
  ('V. S. Ramachandran\'ın hayalet kol ağrısını hafifletmek için geliştirdiği, sağlam kolun yansımasının kayıp kolun yerinde görülmesini sağlayan düzenek hangisidir?', 'Ayna kutusu', ['Skinner kutusu', 'Ames odası', 'Bulmaca kutusu'], 'Ayna kutusunda hasta sağlam kolunu hareket ettirdiğinde yansımayı kayıp kolu gibi görür; bu görsel geri bildirim bazı hastalarda ağrıyı ve kasılma hissini azaltır.'),
  ('Bir kişinin rakamları ya da harfleri sürekli olarak belirli renklerde görmesi, örneğin 5\'i her zaman kırmızı algılaması hangi olgudur?', 'Sinestezi', ['Pareidoli', 'Halüsinasyon', 'Ardıl imge'], 'Sinestezide bir duyu ya da kavram, otomatik ve tutarlı biçimde başka bir duyusal deneyimi tetikler; grafem-renk sinestezisi en yaygın türlerdendir.'),
  ('Vantrilok gösterisinde sesin, kuklanın kıpırdayan ağzından geliyormuş gibi algılanması neyi gösterir?', 'Ses kaynağının yeri belirlenirken görme bilgisinin işitmeye baskın gelebildiğini', ['İşitmenin her zaman görmeden daha güvenilir olduğunu', 'Kuklanın gerçekten ses çıkardığını ve dinleyicinin bunu her zaman doğru duyduğunu', 'Ses yerelleştirmenin yalnızca tek kulakla yapıldığını'], 'Uzamsal konumda görme işitmeden daha keskin olduğu için beyin iki bilgiyi birleştirirken görsel konuma ağırlık verir; buna vantrilok etkisi denir.'),
  ('Saniye ibresi olan bir saate göz attığınızda ilk saniyenin sonrakilerden daha uzun sürüyormuş gibi gelmesine ne ad verilir?', 'Kronostaz (durmuş saat yanılsaması)', ['Vierordt yasası (süre ortalamaya çekilir)', 'Kapa etkisi', 'Teleskop etkisi'], 'Göz sıçramasından sonra beyin, sıçrama sırasındaki boşluğu yeni görüntüyle geriye doğru doldurur; bu nedenle ilk görülen saniye daha uzun algılanır.'),
  ('İnsanların uzak geçmişteki olayları gerçekte olduğundan daha yakın bir tarihte olmuş gibi tarihleme eğilimine ne ad verilir?', 'İleriye teleskop etkisi', ['Anımsama tümseği', 'Çocukluk amnezisi', 'Geriye ket vurma'], 'Teleskop etkisinde uzak olaylar zaman ekseninde öne çekilir; anket çalışmalarında olayların sıklığı ve zamanı sorulurken önemli bir hata kaynağıdır.'),
  ('Arkadaşınız size bir şey söylediğinde "Ne dedin?" diye sorup daha o tekrar etmeden söylediğini hatırlamanız hangi bellek deposunun işleviyle açıklanır?', 'İşitsel duyusal bellek', ['Görsel duyusal bellek (ikonik bellek) deposu', 'İşlemsel (beceri) bellek', 'Anlamsal bellek'], 'Ekoik bellek, işitilen bilginin birkaç saniye boyunca ham biçimde tutulmasını sağlar; dikkat sonradan yöneltildiğinde bu iz hâlâ okunabilir.'),
  ('Ekoik belleğin ikonik belleğe göre farkı hangi seçenekte doğru verilmiştir?', 'Bilgiyi daha uzun, yaklaşık birkaç saniye tutması', ['Bilgiyi yalnızca milisaniyelerce tutması', 'Bilgiyi anlamına göre kodlayıp sınırsız saklaması', 'Yalnızca dokunma duyusundan gelen bilgiyi kısa süre tutabilmesi'], 'İkonik iz saniyenin bir kesrinde silinirken, Darwin, Turvey ve Crowder\'ın "üç kulaklı adam" deneyi gibi çalışmalar ekoik izin birkaç saniye (yaklaşık 2–4 sn) sürdüğünü göstermiştir.'),
  ('Bir sözcük listesi sesli okunduğunda son öğelerin hatırlanmasının, aynı liste yazılı gösterildiğine göre daha yüksek olmasına ne ad verilir?', 'Kip (modalite) etkisi', ['Resim üstünlüğü etkisi', 'Üretme etkisi', 'Aralıklama etkisi'], 'Sesli sunumda son öğeler ekoik bellekten ek destek aldığı için yakınlık etkisi görsel sunuma göre daha güçlüdür.'),
  ('Glanzer ve Cunitz\'in 1966 deneyinde liste sunulduktan sonra katılımcılara 30 saniye geri sayma yaptırıldığında dizi konum eğrisinde ne değişmiştir?', 'Listenin sonundaki üstünlük kaybolmuş, baştaki üstünlük korunmuştur', ['Listenin başındaki üstünlük kaybolmuş, sondaki korunmuştur', 'Hem baştaki hem sondaki üstünlük aynı oranda ve belirgin biçimde artmıştır', 'Eğride hiçbir değişiklik olmamıştır'], 'Gecikme kısa süreli bellekteki son öğeleri silerek yakınlık etkisini ortadan kaldırmış; uzun süreli belleğe aktarılmış ilk öğeler etkilenmemiştir. Bu, iki depolu modeli destekler.'),
  ('Rundus\'un katılımcılardan listeyi sesli tekrar etmelerini istediği çalışmasında listenin başındaki sözcüklerin daha iyi hatırlanması neyle ilişkilendirilmiştir?', 'Bu sözcüklerin daha fazla kez tekrar edilmiş olmasıyla', ['Bu sözcüklerin daha kısa olmasıyla', 'Bu sözcüklerin daha yüksek sesle okunmasıyla', 'Bu sözcüklerin tümünün somut ve imgelenebilir olmasıyla'], 'İlk sözcükler tekrar için daha çok fırsat bulur; bu fazladan tekrar onları uzun süreli belleğe aktararak ilklik etkisini doğurur.'),
  ('Waugh ve Norman\'ın 1965 "yoklama rakamı" deneyinde rakamların sunulma hızı değiştirildiğinde unutmayı belirleyen asıl etkenin ne olduğu bulunmuştur?', 'Aradan geçen süreden çok, araya giren öğe sayısı', ['Rakamların büyüklüğü ve tek ya da çift olması', 'Rakamların sesli okunması', 'Katılımcının yaşı'], 'Hızlı ve yavaş sunumda araya giren öğe sayısı aynıyken unutma benzer çıktı; bu, kısa süreli bellekte bozulmadan çok ket vurmanın etkili olduğunu destekler.'),
  ('Okunduğu sürede uzun sözcüklerden oluşan listelerin kısa sözcüklerden oluşan listelere göre daha az hatırlanmasına ne ad verilir?', 'Sözcük uzunluğu etkisi', ['Sözcük üstünlüğü etkisi', 'Sözcük sıklığı etkisi', 'Dizi konum etkisi'], 'Baddeley ve arkadaşlarının gösterdiği bu etki, sesletim döngüsünün yaklaşık iki saniyede söylenebilen kadar malzemeyi tutabildiğini, uzun sözcüklerin bu süreyi daha çabuk doldurduğunu gösterir.'),
  ('Conrad\'ın 1964 çalışmasında harf dizileri görsel olarak sunulduğu hâlde hatırlama hatalarında B yerine V, P yerine T gibi karıştırmalar görülmüştür. Bu bulgu neyi gösterir?', 'Kısa süreli bellekte bilginin büyük ölçüde sesle kodlandığını', ['Harflerin görsel biçimlerinin daha iyi hatırlandığını', 'Katılımcıların işitme sorunu olduğunu', 'Kısa süreli belleğin yalnızca görsel kod kullandığını ve sesi hiç işlemediğini'], 'Görsel sunulan harflerin bile benzer seslerle karıştırılması, kısa süreli bellekte harflerin içten seslendirilerek akustik kodla tutulduğunu gösterir.'),
  ('Baddeley ve Hitch modelinde nesnelerin biçimi ve uzamdaki yerleri gibi bilgileri geçici olarak tutup işleyen bileşene ne ad verilir?', 'Görsel-uzamsal karalama defteri', ['Sesbilgisel depo', 'Epizodik tampon', 'Duyusal kayıt'], 'Görsel-uzamsal karalama defteri, zihinde bir odanın düzenini canlandırma ya da bir yolun haritasını tutma gibi görevlerde kullanılır.'),
  ('Baddeley\'in 2000 yılında çalışma belleği modeline eklediği, farklı kaynaklardan gelen bilgiyi uzun süreli bellekle birleştirerek bütünleşik bölümler hâlinde tutan bileşen hangisidir?', 'Epizodik tampon', ['Merkezi yürütücü', 'Fonolojik depo', 'Görsel önbellek'], 'Epizodik tampon, alt sistemleri ve uzun süreli belleği bağlayan sınırlı kapasiteli bir arabirimdir; örneğin anlamlı cümlelerin hatırlanmasının sözcük sınırını aşmasını açıklar.'),
  ('Nelson Cowan\'ın kısa süreli belleğin gerçek kapasitesine ilişkin 2001 yılındaki değerlendirmesine göre, tekrar ve öbekleme engellendiğinde bu kapasite ortalama kaç birimdir?', 'Yaklaşık 4 birim', ['Yaklaşık 12 birim', 'Yaklaşık 20 birim', 'Yaklaşık 1 birim'], 'Cowan, alıştırma ve öbekleme gibi stratejiler devre dışı kaldığında kapasitenin 7 değil, yaklaşık 3–5 (4 ± 1) birim olduğunu öne sürdü.'),
  ('Sternberg\'in bellek tarama görevinde listede 2 rakam varken yanıt süresi 470 ms ise, tarama başına 38 ms artış varsayımıyla listede 5 rakam olduğunda yanıt süresinin kaç ms olması beklenir?', '584 ms', ['546 ms', '508 ms', '660 ms'], 'Üç ek rakam 3 × 38 = 114 ms ekler; 470 + 114 = 584 ms olur.'),
  ('Chase ve Simon\'ın 1973 çalışmasında satranç ustaları gerçek oyunlardan alınmış konumları birkaç saniyelik bakıştan sonra acemilerden çok daha iyi yeniden kurmuştur. Taşlar rastgele dizildiğinde ise ne bulunmuştur?', 'Ustaların üstünlüğü büyük ölçüde ortadan kalkmıştır', ['Ustalar rastgele konumlarda da aynı üstünlüğü korumuştur', 'Acemiler rastgele konumlarda ustalardan çok daha başarılı olmuştur', 'Hiçbir grup tek bir taşı bile doğru yerleştirememiştir'], 'Ustaların üstünlüğü genel bir bellek gücünden değil, anlamlı taş düzenlerini öbekler hâlinde tanımalarından kaynaklanır; anlamsız dizilimlerde bu bilgi işe yaramaz.'),
  ('Satranç ustalarının konum belleğine ilişkin ilk sistemli çalışmaları yapan ve bulgularını "Thought and Choice in Chess" adlı eserde toplayan Hollandalı psikolog kimdir?', 'Adriaan de Groot', ['Hermann Ebbinghaus', 'Frederic Bartlett', 'Endel Tulving'], 'De Groot, ustaların acemilerden daha fazla hamle hesaplamadığını, asıl farkın konumları hızla ve anlamlı biçimde algılamalarında olduğunu gösterdi.'),
  ('K. Anders Ericsson\'a göre bir alanda üst düzey uzmanlığa ulaşmada en belirleyici etken hangisidir?', 'Zayıf yönlere odaklanan, geri bildirimli, bilinçli alıştırma', ['Yalnızca doğuştan gelen yetenek', 'O alanla ilgili kitapları bir kez okumak', 'Kısa süreli ama çok sayıda farklı etkinliği yüzeysel olarak denemek'], 'Ericsson\'ın "bilinçli alıştırma" kavramı, sıradan tekrarın değil, performansı zorlayan, hedefli ve geri bildirime dayalı uzun yıllar süren çalışmanın uzmanlık getirdiğini vurgular.'),
  ('Uzun süreli bellekte anısal (epizodik) bellek ile anlamsal bellek ayrımını 1972\'de ortaya atan psikolog kimdir?', 'Endel Tulving', ['George Miller', 'Alan Baddeley', 'Elizabeth Loftus'], 'Tulving, kişisel olarak yaşanmış ve zamanı-yeri belli olaylara ilişkin bellek ile genel bilgi belleğini ayırarak bellek sistemleri tartışmasını başlattı.'),
  ('Larry Squire\'ın bellek sınıflamasına göre aşağıdakilerden hangisi bildirimsel olmayan (örtük) belleğe girer?', 'Klasik koşullanmayla öğrenilmiş bir tepki', ['Geçen yaz yapılan bir tatilin ayrıntılı anısı', 'Bir ülkenin başkentini bilmek', 'Bir arkadaşın doğum gününün tarihi'], 'Bildirimsel olmayan bellek işlemsel becerileri, hazırlamayı ve klasik koşullanmayı kapsar; bunlar bilinçli olarak anlatılmadan davranışta ortaya çıkar.'),
  ('Bir kişinin bir bilgiyi hatırlarken öğrendiği anı yeniden yaşıyormuş gibi ayrıntılarıyla anımsaması ile sadece "tanıdık geldiğini" hissetmesi arasındaki ayrımı inceleyen yönteme ne ad verilir?', 'Hatırlıyorum/biliyorum yöntemi', ['Kısmi rapor yöntemi', 'Tasarruf yöntemi', 'Bölünmüş dizi yöntemi'], 'Tulving\'in geliştirdiği bu yöntemde "hatırlıyorum" yanıtı ayrıntılı anımsamayı, "biliyorum" yanıtı ise bağlam bilgisi olmadan tanıdıklık hissini yansıtır.'),
  ('Anlamsal demans hastalarında en belirgin bozulan bellek türü hangisidir ve buna hangi bölgedeki doku kaybı eşlik eder?', 'Sözcük ve nesne anlamlarına dair bilgi; ön şakak lobu', ['Yeni olayları kaydetme ve sonradan hatırlama; hipokampus', 'Motor beceriler; beyincik', 'Kısa süreli rakam aralığı; ön lob'], 'Anlamsal demansta hastalar "zürafa"nın ne olduğunu unutabilir ama dün yaşadıklarını hatırlayabilir; tablo, anlamsal belleğin ön şakak loblarıyla ilişkisini gösterir.'),
  ('Kişinin kendi yaşamına ilişkin anıların ve bilgilerin bütünü, örneğin ilk iş gününü ve hangi okullarda okuduğunu hatırlaması hangi bellek türüyle anılır?', 'Otobiyografik bellek', ['İşlemsel bellek', 'Duyusal bellek', 'Çalışma belleği'], 'Otobiyografik bellek, kişisel olayların anısal kayıtlarını ve kişi hakkındaki anlamsal bilgileri birleştirerek benlik duygusunun temelini oluşturur.'),
  ('Yaşlı yetişkinlerden yaşamlarındaki anıları hatırlamaları istendiğinde, ergenlik ve genç yetişkinlik yıllarına (yaklaşık 10–30 yaş) ait anıların orantısız biçimde çok sayıda olmasına ne ad verilir?', 'Anımsama tümseği', ['Yakınlık etkisi', 'Çocukluk amnezisi', 'Teleskop etkisi'], 'Anımsama tümseği, kimlik oluşumunun yoğun olduğu ve pek çok "ilk"in yaşandığı bu dönemin anılarının daha iyi kodlandığı ve sık hatırlandığı şeklinde açıklanır.'),
  ('Yetişkinlerin genellikle 3–4 yaşından önceki yaşantılarını hemen hiç hatırlayamamasına ne ad verilir?', 'Çocukluk (bebeklik) amnezisi', ['Geriye dönük amnezi', 'Kaynak amnezisi', 'Anımsama tümseği'], 'Çocukluk amnezisi, dil ve benlik kavramının gelişimi ile hipokampusun olgunlaşması gibi etkenlerle açıklanır; bu dönemdeki deneyimler kalıcı anısal kayıtlara dönüşmez.'),
  ('Akşam eve dönerken markete uğrayıp ekmek almayı unutmamak gibi, gelecekte bir şeyi yapmayı hatırlamaya ne ad verilir?', 'İleriye dönük (prospektif) bellek', ['Geriye dönük (retrospektif) bellek', 'İşlemsel bellek', 'Örtük bellek'], 'İleriye dönük bellek, niyetlerin doğru zamanda ya da doğru ipucu ortaya çıktığında hatırlanmasıdır; geçmiş bilgiyi hatırlamaktan farklı süreçler içerir.'),
  ('"Saat beşte ilacımı içeceğim" niyeti ile "Ayşe\'yi görünce ona kitabını vereceğim" niyeti arasındaki fark ileriye dönük bellekte hangi ayrımla açıklanır?', 'Zamana dayalı ve olaya dayalı görevler', ['Anısal ve anlamsal görevler', 'Açık ve örtük görevler', 'Tanıma ve serbest hatırlama görevleri'], 'Olaya dayalı görevlerde dış bir ipucu niyeti tetikler; zamana dayalı görevlerde ise kişi zamanı kendisi izlemek zorunda olduğundan bu görevler genellikle daha zordur.'),
  ('Ribot yasasına göre beyin hasarına bağlı geriye dönük bellek yitiminde hangi anılar daha iyi korunur?', 'Hasardan çok önceki, eski anılar', ['Hasardan hemen önceki, en yeni anılar', 'Yalnızca çocukluktaki rüyalar', 'Yalnızca son bir saat içinde öğrenilenler'], 'Théodule Ribot\'nun gözlemine göre eski anılar zamanla daha sağlam pekiştiği için geriye dönük bellek yitiminden daha az etkilenir; kayıp en çok yakın geçmişte yoğunlaşır.'),
  ('1985\'te geçirdiği beyin iltihabı (herpes ensefaliti) sonucu yalnızca birkaç saniyelik bir bilinç penceresinde yaşamaya başlayan, ancak piyano çalma ve koro yönetme becerilerini koruyan İngiliz müzisyen kimdir?', 'Clive Wearing', ['Henry Molaison', 'Phineas Gage', 'Kent Cochrane'], 'Clive Wearing\'in durumu ağır anısal bellek kaybına karşın işlemsel becerilerin ve karısına duyduğu duygusal bağlılığın korunabildiğini çarpıcı biçimde gösterir.'),
  ('Yeni öğrenilen bilginin başlangıçta kırılgan olup zamanla, özellikle hipokampus ile beyin kabuğu arasındaki etkileşimle kalıcı ve dirençli hâle gelmesine ne ad verilir?', 'Bellek pekiştirmesi (konsolidasyon)', ['Bellek taraması (Sternberg süreci)', 'Duyusal kayıt', 'Örtük öğrenme'], 'Pekiştirme kuramına göre yeni izler önce hipokampusa bağımlıdır; zamanla beyin kabuğunda bağımsızlaşır ve bu süreç tamamlanmadan bozulmaya açıktır.'),
  ('Yeni bir yerde ilk kez bulunduğu hâlde "burayı daha önce yaşamışım" duygusunun kısa ve güçlü biçimde yaşanmasına ne ad verilir?', 'Déjà vu', ['Jamais vu', 'Konfabulasyon', 'Kriptomnezi'], 'Déjà vu, gerçek bir anı olmadan ortaya çıkan yoğun bir tanıdıklık hissidir; tanıdıklık sinyalinin anımsamadan bağımsız olarak etkinleşmesiyle açıklanmaya çalışılır.'),
  ('Rogers, Kuiper ve Kirker\'in 1977 çalışmasında "Bu sıfat sizi tanımlıyor mu?" sorusuyla işlenen sözcüklerin, anlamsal sorularla işlenenlerden bile daha iyi hatırlanmasına ne ad verilir?', 'Kendine gönderme (öz-referans) etkisi', ['Yanlış bilgi etkisi', 'Kip (sunum biçimi) etkisi', 'Sınama (geri getirme alıştırması) etkisi'], 'Benlik, son derece zengin ve örgütlü bir bilgi yapısı olduğu için bilgiyi kendimizle ilişkilendirmek onu ayrıntılı ve kolay geri getirilebilir biçimde kodlar.'),
  ('Slamecka ve Graf\'ın 1978 deneyinde "SICAK – S_ _ _ K" gibi ipuçlarından sözcüğü kendisi tamamlayan katılımcıların, hazır okuyanlardan daha iyi hatırlamasına ne ad verilir?', 'Üretme etkisi', ['Hazırlama etkisi', 'Kip etkisi', 'Son ek etkisi'], 'Bilgiyi pasif okumak yerine zihinsel çabayla üretmek daha derin ve ayırt edici bir iz oluşturur.'),
  ('Bir sözcük listesinde siyah yazılmış sözcükler arasında tek bir kırmızı sözcük bulunduğunda bu sözcüğün daha iyi hatırlanmasına ne ad verilir?', 'Von Restorff (yalıtım) etkisi', ['Fırlama etkisi', 'İlklik (listenin başı) etkisi', 'Navon etkisi'], 'Hedwig von Restorff\'un 1933\'te tanımladığı yalıtım etkisine göre çevresinden belirgin biçimde farklı olan öğe daha ayırt edici kodlandığı için daha iyi hatırlanır.'),
  ('Aynı kavramların sözcük olarak değil resim olarak sunulduğunda daha iyi hatırlanmasına ne ad verilir?', 'Resim üstünlüğü etkisi', ['Sözcük üstünlüğü etkisi', 'Bütünün önceliği etkisi', 'Yüz ters çevirme etkisi'], 'Resimler hem görsel hem sözel olarak kodlanabildiği için genellikle sözcüklerden daha iyi hatırlanır; bu etki ikili kodlama kuramıyla da uyumludur.'),
  ('Allan Paivio\'nun ikili kodlama kuramına göre "fil" gibi somut sözcüklerin "adalet" gibi soyut sözcüklerden daha iyi hatırlanmasının nedeni nedir?', 'Somut sözcüklerin hem sözel hem de imgesel kodla saklanabilmesi', ['Somut sözcüklerin her zaman daha kısa olması', 'Soyut sözcüklerin hiç anlam taşımaması', 'Somut sözcüklerin yalnızca işitsel kodla saklanması, soyut olanların ise hiçbir kodla saklanamaması'], 'Paivio\'ya göre bilgi sözel ve imgesel iki ayrı sistemde temsil edilebilir; iki kodla saklanan bilgiye ulaşmak için iki yol bulunduğundan hatırlama kolaylaşır.'),
  ('"Bardağı kaldır", "kapıyı aç" gibi kısa eylem ifadelerini yalnızca dinleyenlere göre bu eylemleri kendisi yapanların ifadeleri daha iyi hatırlamasına ne ad verilir?', 'Uygulama (canlandırma) etkisi', ['Kip etkisi', 'Gölgeleme etkisi', 'Kronostaz (durmuş saat) etkisi'], 'Eylemi bizzat gerçekleştirmek motor, duyusal ve anlamsal bilgileri birlikte kodlayarak zengin bir iz bırakır; bu nedenle "yaparak hatırlama" daha başarılıdır.'),
  ('Bir listedeki bazı sözcükleri sesli, bazılarını sessiz okuyan kişilerin sesli okudukları sözcükleri daha iyi hatırlamasına ne ad verilir?', 'Üretim (sesli okuma) etkisi', ['Son ek etkisi', 'Sözcük uzunluğu (sesletim) etkisi', 'Dikkat kırpması'], 'Sesli okunan öğeler, konuşma ve işitme izleri sayesinde sessiz okunanlardan daha ayırt edici olur; bu ayırt edicilik hatırlamayı kolaylaştırır.'),
  ('Craik ve Watkins\'in 1973 çalışmasında sözcükleri yalnızca içinden tekrarlayarak akılda tutan katılımcılarda tekrar süresinin uzatılmasının uzun süreli hatırlamaya etkisi ne olmuştur?', 'Uzun süreli hatırlamayı neredeyse hiç artırmamıştır', ['Uzun süreli hatırlamayı tekrar süresiyle orantılı olarak artırmıştır', 'Hatırlamayı tamamen ortadan kaldırmıştır', 'Yalnızca uzun sözcüklerde hatırlamayı artırmıştır'], 'Bu bulgu, bilgiyi anlam düzeyinde işlemeden yalnızca yinelemenin kalıcı öğrenme sağlamadığını, işlemenin niteliğinin süreden önemli olduğunu gösterir.'),
  ('Endel Tulving ve Donald Thomson\'ın 1973\'te formüle ettiği "kodlama özgüllüğü" ilkesi neyi söyler?', 'İpucunun ancak kodlama sırasında izle birlikte işlenmişse etkili olacağını', ['Bütün bilgilerin, hangi ipucu verilirse verilsin, eşit kolaylıkla hatırlanabildiğini', 'Bilginin yalnızca öğrenildiği odada hatırlanabileceğini', 'Kodlamanın her zaman görsel olarak yapılması gerektiğini'], 'İlkeye göre hatırlama, geri getirme anındaki ipuçlarının kodlama anında izle birlikte saklanan bilgilerle örtüşmesine bağlıdır; güçlü bir ilişkili sözcük bile kodlanmamışsa ipucu olarak işe yaramayabilir.'),
  ('Alkollü iken bir şey saklayan kişinin ayıkken bulamayıp yeniden alkol aldığında hatırlaması hangi bellek olgusuna örnektir?', 'Duruma bağlı bellek', ['Bağlama bağlı unutma kuramı', 'Ruh hâline uygun bellek', 'Geriye dönük bellek yitimi'], 'Duruma bağlı bellekte kişinin kodlama sırasındaki iç fizyolojik durumu bir geri getirme ipucu işlevi görür; aynı durum yeniden oluştuğunda hatırlama kolaylaşır.'),
  ('Gordon Bower\'ın çalışmalarında üzgün bir ruh hâlindeki kişilerin olumsuz anıları, mutlu olanların ise olumlu anıları daha kolay hatırlaması hangi kavramla adlandırılır?', 'Ruh hâline uygun bellek', ['Duruma bağlı öğrenme', 'Kaynak izleme', 'Kodlama başarısızlığı'], 'Ruh hâline uygun bellekte, mevcut duygu durumu ona uygun içerikteki anıların erişilebilirliğini artırır; bu, depresyondaki olumsuz düşünce döngülerini açıklamada kullanılır.'),
  ('Rusça "zvonok" (zil) sözcüğünü öğrenen birinin onu Türkçede sesçe benzeyen bir sözcükle ilişkilendirip ikisini birleştiren canlı bir zihinsel imge oluşturması hangi anımsatıcı tekniktir?', 'Anahtar sözcük yöntemi', ['Yer (loci) yöntemi', 'Akrostiş (baş harf) tekniği', 'Öbekleme'], 'Atkinson ve Raugh\'un etkinliğini gösterdiği anahtar sözcük yöntemi, yabancı sözcüğü ses benzerliği taşıyan tanıdık bir sözcüğe, o sözcüğü de imge aracılığıyla anlama bağlar.'),
  ('"Bir-bisküvi, iki-kiraz, üç-üzüm" gibi önceden ezberlenmiş sayı-imge çiftlerine hatırlanacak öğeleri sırayla bağlayan anımsatıcı yönteme ne ad verilir?', 'Askı sözcük yöntemi', ['Yer yöntemi', 'Akrostiş tekniği', 'Sürdürme tekrarı'], 'Askı sözcük yönteminde iyi bilinen bir sayı-sözcük listesi "çengel" işlevi görür; yeni öğeler bu çengellere imgelerle asılarak sırasıyla hatırlanır.'),
  ('Robert Bjork\'un "istendik güçlükler" kavramına göre aşağıdaki çalışma yöntemlerinden hangisi kısa vadede zor gelse de uzun vadeli öğrenmeyi artırır?', 'Kendini sınama ve konular arasında karışık çalışma', ['Aynı bölümü art arda tekrar tekrar okumak', 'Önemli cümlelerin altını renkli kalemle çizmek', 'Ders notlarını kelimesi kelimesine ve temiz biçimde yeniden yazmak'], 'Geri getirme çabası, aralık ve karıştırma gibi güçlükler öğrenme sırasında performansı düşürse de daha kalıcı ve aktarılabilir öğrenme sağlar.'),
  ('Kornell ve Bjork\'un 2008 çalışmasında farklı ressamların tablolarını karışık sırayla inceleyenler, her ressamın tablolarını blok hâlinde inceleyenlere göre yeni tabloların ressamını daha iyi tanımıştır. Katılımcıların çoğu ise hangi yöntemin daha iyi olduğunu düşünmüştür?', 'Blok hâlinde çalışmanın', ['Karışık çalışmanın', 'Hiçbir yöntemin fark yaratmadığını', 'Yalnızca ünlü ressamlarda karışık çalışmanın'], 'Karıştırmalı çalışma kategoriler arasındaki farkları fark etmeyi kolaylaştırır; ancak blok çalışma daha akıcı hissettirdiği için öğrenenler onun daha etkili olduğu yanılgısına düşer.'),
  ('Bir öğrencinin aynı bölümü üç kez okuduktan sonra konuyu öğrendiğini düşünmesi, ama sınavda hatırlayamaması üst biliş açısından en iyi hangi kavramla açıklanır?', 'Akıcılık yanılsaması', ['Kendine gönderme etkisi', 'Üretme etkisi', 'Kip etkisi'], 'Tekrar okuma metni tanıdık ve akıcı kılar; bu kolaylık hissi gerçek öğrenme sanılır, oysa bilgiyi ipucusuz geri getirme becerisi gelişmemiştir.'),
  ('Ebbinghaus\'un "tasarruf yöntemi"nde bir listeyi ilk öğrenmek 20 deneme, bir hafta sonra yeniden öğrenmek 8 deneme sürmüştür. Tasarruf oranı yüzde kaçtır?', '%60', ['%40', '%28', '%72'], 'Tasarruf oranı (ilk deneme − yeniden öğrenme denemesi) / ilk deneme × 100 ile bulunur: (20 − 8) / 20 × 100 = %60.'),
  ('Ebbinghaus\'un bellek deneylerinde "ZOF", "DAX" gibi anlamsız heceler kullanmasının temel amacı neydi?', 'Önceki bilgi ve çağrışımların öğrenmeyi etkilemesini en aza indirmek', ['Katılımcıların ilgisini artırıp deneyi eğlenceli kılmak', 'Hecelerin anlamlı sözcüklerden daha kolay ve daha kalıcı öğrenildiğini göstermek', 'Yalnızca görsel belleği ölçmek'], 'Anlamlı sözcükler kişiden kişiye değişen çağrışımlar taşır; anlamsız heceler malzemeyi görece eşit ve yeni kılarak öğrenme ile unutmayı daha saf biçimde ölçmeyi sağlar.'),
  ('Ebbinghaus\'un kendi üzerinde yaptığı deneyleri 1885\'te yayımladığı ve belleğin deneysel incelenmesini başlatan eserinin adı hangisidir?', 'Bellek Üzerine (Über das Gedächtnis)', ['Psikolojinin İlkeleri (Principles of Psychology)', 'Bilişsel Psikoloji', 'Rüyaların Yorumu'], 'Ebbinghaus bu kitabında öğrenme ve unutmayı nicel olarak ölçerek üst düzey zihinsel süreçlerin de deneysel yöntemle incelenebileceğini gösterdi.'),
  ('Bir deneyde katılımcılara bazı sözcüklerden sonra "unut", bazılarından sonra "hatırla" yönergesi verilir; sonraki testte "unut" denen sözcüklerin daha az hatırlandığı görülür. Bu olguya ne ad verilir?', 'Yönlendirilmiş unutma', ['Bozulma yoluyla unutma', 'Bastırma', 'Kaynak amnezisi'], 'Yönlendirilmiş unutma, kişinin istemli olarak belirli bilgileri tekrar etmeyi bırakması ve geri getirmeyi ketlemesiyle belleği bir ölçüde denetleyebildiğini gösterir.'),
  ('Bir sınavda "Bu sorunun cevabını şu an hatırlayamıyorum ama şıklar verilse bilirim" diye düşünen öğrencinin bu öngörüsü hangi kavramla adlandırılır?', 'Bilme hissi', ['Dilinin ucunda olma hâli', 'Déjà vu', 'Akıcılık yanılsaması'], 'Bilme hissi, kişinin şu an geri getiremediği bir bilgiyi tanıma testinde bulabileceğine dair üst bilişsel yargısıdır ve çoğu zaman şans üstü isabetlidir.'),
  ('Katılımcılara bir sözcük listesi verilip hiçbir ipucu olmadan istedikleri sırayla hatırlamaları istenirse buna ne ad verilir?', 'Serbest hatırlama', ['Sıralı hatırlama', 'İpuçlu hatırlama', 'Tanıma'], 'Serbest hatırlamada sıra serbesttir; sıralı hatırlamada öğeler sunuluş sırasıyla, ipuçlu hatırlamada bir ipucu yardımıyla verilir.'),
  ('Bousfield\'ın 1953 çalışmasında hayvan, isim, meslek ve sebze kategorilerinden karışık sırayla sunulan sözcükler hatırlanırken katılımcılar sözcükleri hangi biçimde hatırlamıştır?', 'Aynı kategoriden sözcükleri kümeler hâlinde', ['Tam olarak sunuluş sırasıyla', 'Alfabetik sırayla', 'Rastgele, hiçbir anlamlı düzen ya da örüntü göstermeden'], 'Kategorik kümelenme, uzun süreli belleğin bilgiyi anlamsal olarak örgütlediğini ve geri getirme sırasında bu örgütlenmenin kullanıldığını gösterir.'),
  ('Belleğin bir kayıt değil, yeniden yapılandırma süreci olduğunu savunan ve 1932\'de "Hatırlama" (Remembering) adlı eseri yayımlayan İngiliz psikolog kimdir?', 'Frederic Bartlett', ['Hermann Ebbinghaus', 'Donald Broadbent', 'Edward Titchener'], 'Bartlett, insanların öyküleri hatırlarken eksikleri kendi kültürel beklentileriyle doldurduğunu göstererek şema kavramını bellek araştırmalarına kazandırdı.'),
  ('Bartlett\'in "Hayaletlerin Savaşı" adlı Kuzey Amerika yerli öyküsünü İngiliz katılımcılara tekrar tekrar anlattırdığı çalışmada öykünün nasıl değiştiği gözlenmiştir?', 'Kısalıp katılımcıların kendi kültürüne uygun hâle geldiği', ['Uzadığı ve yeni doğaüstü öğelerle, ek karakterlerle zenginleştiği', 'Hiç değişmeden aynen korunduğu', 'Yalnızca karakter adlarının unutulduğu'], 'Tuhaf ayrıntılar atılmış, yabancı öğeler tanıdık olanlarla değiştirilmiş (örneğin kano yerine kayık) ve öykü daha mantıklı hâle getirilmiştir; bu, şemaların hatırlamayı biçimlendirdiğini gösterir.'),
  ('Bartlett\'in bir öyküyü birinci kişinin ikinciye, ikincinin üçüncüye aktardığı zincirleme hatırlama yöntemine ne ad verilir?', 'Dizisel yeniden üretim', ['Tekrarlı yeniden üretim', 'Kısmi rapor', 'Tasarruf yöntemi'], 'Dizisel yeniden üretim, bir bilginin kişiden kişiye aktarılırken nasıl sistematik biçimde değiştiğini, söylentilere benzer bir süreçle göstermektedir.'),
  ('Katılımcılara "yatak, dinlenme, uyanık, yorgun, rüya, horlama, yastık" gibi sözcükler okunduktan sonra birçoğunun listede hiç geçmeyen "uyku" sözcüğünü güvenle hatırlaması hangi deney paradigmasının bulgusudur?', 'DRM (Deese-Roediger-McDermott) paradigması', ['Brown-Peterson paradigması', 'Posner ipucu paradigması', 'Sperling kısmi rapor (harf matrisi) paradigması'], 'DRM listelerinde bütün sözcükler sunulmayan ortak bir "tuzak" sözcükle ilişkilidir; yayılan etkinleşme bu sözcüğü öyle güçlendirir ki çoğu kişi onu gerçekten duyduğundan emin olur.'),
  ('Loftus ve Pickrell\'in 1995 "alışveriş merkezinde kaybolma" çalışmasında katılımcılara aile üyelerinden alınmış gerçek anılarla birlikte uydurma bir çocukluk olayı anlatılmıştır. Sonuçta ne bulunmuştur?', 'Katılımcıların yaklaşık dörtte birinin uydurma olayı hatırladığını bildirmesi', ['Hiçbir katılımcının uydurma olayı kabul etmemesi', 'Bütün katılımcıların uydurma olayı gerçek anılardan ayıramaması ve tüm olayları eşit ayrıntıyla anlatması', 'Katılımcıların gerçek anıları da reddetmesi'], 'Bu çalışma, yaşanmamış bütün bir olayın bile telkinle "anı" olarak benimsenebileceğini göstererek terapide geri kazanılmış anılar tartışmasında önem kazandı.'),
  ('Çocukluğunda yaşamadığı bir olayı birkaç kez ayrıntılı olarak hayal etmesi istenen kişilerin sonradan o olayın gerçekten yaşandığına daha çok inanmasına ne ad verilir?', 'Hayal etme şişmesi', ['Akıcılık yanılsaması', 'Ruh hâline uygun bellek', 'Ters çevirme etkisi'], 'Garry ve arkadaşlarının gösterdiği bu etki, imgelenen olayların tanıdıklık kazanarak gerçek anılarla karıştırılabildiğini gösterir.'),
  ('Bir bilgiyi doğru hatırladığı hâlde onu bir gazeteden mi yoksa arkadaşından mı duyduğunu karıştıran kişinin hatası Marcia Johnson\'ın kuramında hangi adla anılır?', 'Kaynak izleme hatası', ['Kodlama başarısızlığı', 'İleriye ket vurma', 'Sürdürme tekrarı'], 'Kaynak izleme çerçevesine göre anıların kökeni doğrudan etiketli değildir; kişi bunu anının özelliklerinden çıkarır ve bu çıkarım yanılabilir.'),
  ('Bir şarkı bestecisinin yıllar önce duyduğu bir ezgiyi kendi özgün buluşu sanarak bestelemesi hangi bellek hatasına örnektir?', 'Kriptomnezi', ['Déjà vu', 'Konfabulasyon', 'Flaş bellek'], 'Kriptomnezide bilginin içeriği hatırlanır ama kaynağı unutulur; kişi bu yüzden başkasına ait bir fikri ya da ezgiyi kendi üretimi sanır.'),
  ('Loftus ve Palmer\'ın 1974 araba kazası çalışmasının ikinci aşamasında, kazayı "birbirine bindirdi" sözcüğüyle sorgulanan katılımcılara bir hafta sonra ne sorulmuş ve ne bulunmuştur?', 'Kırık cam görüp görmedikleri; bu grup olmayan kırık camı daha sık bildirmiştir', ['Arabaların rengi ve markası; bu grup renkleri ve markaları daha doğru hatırlamıştır', 'Sürücülerin yaşı; bu grup daha genç tahmin etmiştir', 'Kazanın saati; bu grup saati daha geç tahmin etmiştir'], 'Sorudaki güçlü fiil yalnızca hız tahminini değil, olayın sonraki temsilini de değiştirmiş ve filmde olmayan ayrıntıların hatırlanmasına yol açmıştır.'),
  ('Silahlı bir soygunun tanıklarının silahı ayrıntılı tarif edip soyguncunun yüzünü hatırlayamaması hangi olguyla açıklanır?', 'Silah odağı etkisi', ['Kendine gönderme etkisi', 'Pareidoli', 'Kategorik algı'], 'Tehdit oluşturan silah dikkati kendine çeker; dikkatin daralması nedeniyle failin yüzü gibi diğer ayrıntılar daha zayıf kodlanır.'),
  ('Görgü tanıklarının kendi etnik gruplarından olmayan kişilerin yüzlerini kendi gruplarından olanlara göre daha az doğru tanımasına ne ad verilir?', 'Irklar arası (öteki ırk) etkisi', ['Yüz ters çevirme etkisi', 'Kendine gönderme etkisi', 'Prozopagnozi'], 'Bu etki, yüz tanıma uzmanlığının en çok karşılaşılan yüz türlerine göre gelişmesiyle açıklanır; tanık ifadelerinde önemli bir hata kaynağıdır.'),
  ('Fisher ve Geiselman\'ın geliştirdiği "bilişsel görüşme" tekniğinin öğelerinden biri aşağıdakilerden hangisidir?', 'Tanığın olay anındaki bağlamı ve duygularını zihninde yeniden canlandırması', ['Tanığa yönlendirici ve evet-hayır biçimindeki kapalı soruların hızla art arda sorulması', 'Tanığın yalnızca bir kez ve çok kısa konuşturulması', 'Tanığa diğer tanıkların ifadelerinin okunması'], 'Bilişsel görüşme bağlamı yeniden kurma, her ayrıntıyı bildirme, olayı farklı sıralarla ve farklı bakış açılarından anlatma gibi bellek ilkelerine dayalı adımlar içerir.'),
  ('Aleksandr Luria\'nın "Bir Belleğin Zihni" (The Mind of a Mnemonist) kitabında incelediği, güçlü sinestezisi sayesinde neredeyse hiçbir şeyi unutamayan Rus bellek uzmanı kimdir?', 'Solomon Şereşevski', ['Henry Molaison', 'Lev Vygotski', 'Kim Peek'], 'Luria, Şereşevski\'nin listeleri yıllar sonra bile hatırlayabildiğini, ancak soyut düşünmede ve önemsiz ayrıntıları unutmada zorlandığını anlattı.'),
  ('Jill Price gibi, yıllar öncesindeki neredeyse her günün olaylarını tarih vererek hatırlayabilen kişilerdeki duruma ne ad verilir?', 'Hipertimezi', ['Eidetik (fotoğrafik) imgeleme yeteneği', 'Konfabulasyon', 'Kriptomnezi'], 'Parker, Cahill ve McGaugh\'un 2006\'da tanımladığı hipertimezide olağanüstü güç kişisel anılarla sınırlıdır; bu kişiler ezber görevlerinde genellikle sıradan performans gösterir.'),
  ('Aniden başlayan, birkaç saat süren, kişinin yeni bilgi kaydedemeyip aynı soruları tekrar tekrar sorduğu, ardından kendiliğinden geçen bellek bozukluğuna ne ad verilir?', 'Geçici global amnezi', ['Çocukluk amnezisi', 'Korsakoff sendromu', 'Anlamsal demans'], 'Geçici global amnezide kişi kimliğini bilir ve becerilerini korur; ataktan sonra bellek normale döner, yalnızca atak süresi hatırlanmaz.'),
  ('Alzheimer hastalığının erken evrelerinde en tipik olarak hangi bellek sorunu görülür?', 'Yakın zamandaki olayları öğrenip hatırlamada güçlük', ['Çocukluk anılarının ilk olarak tamamen silinmesi', 'Bisiklet sürme gibi becerilerin ilk olarak kaybolması', 'Renkleri ayırt edememe'], 'Hastalık sıklıkla hipokampus ve çevresinden başladığı için yeni anısal bilgilerin kaydı erkenden bozulur; eski anılar ve beceriler daha uzun süre korunur.'),
  ('Kavramların klasik (tanımsal) görüşüne göre bir nesnenin bir kategoriye ait sayılması neye bağlıdır?', 'Gerekli ve yeterli özelliklerin tamamını taşımasına', ['Kategorinin en tipik örneğine ne kadar benzediğine', 'Kişinin o nesneyle ilk karşılaştığı bağlama ve duygulara', 'Nesnenin adının kaç heceden oluştuğuna'], 'Klasik görüşte kategori üyeliği ya hep ya hiçtir; bütün tanımlayıcı özellikleri taşıyan her nesne eşit derecede üyedir. Tipiklik bulguları bu görüşü zorlamıştır.'),
  ('Wittgenstein\'ın "oyun" kavramına ilişkin örneğinde, bütün oyunlarda ortak tek bir özellik bulunmadığı hâlde üyelerin birbirine örtüşen benzerliklerle bağlanmasına ne ad verilir?', 'Aile benzerliği', ['Bilişsel ekonomi', 'Kategorik algı', 'İşlevsel saplantı'], 'Wittgenstein\'a göre bir kategorinin üyeleri, bir ailenin bireyleri gibi farklı özelliklerin örtüşmesiyle birbirine benzer; Rosch bu düşünceyi deneysel olarak destekledi.'),
  ('"Serçe bir kuştur" cümlesinin doğruluğuna "Penguen bir kuştur" cümlesinden daha hızlı karar verilmesi hangi bulguya örnektir?', 'Tipiklik etkisi', ['Sözcük üstünlüğü etkisi', 'Kip etkisi', 'Bilinçsiz aktarım'], 'Kategorinin prototipine daha çok benzeyen üyeler daha hızlı doğrulanır, daha önce sayılır ve daha önce öğrenilir; bu, kategori üyeliğinin dereceli olduğunu gösterir.'),
  ('Eleanor Rosch\'a göre "mobilya – sandalye – mutfak sandalyesi" hiyerarşisinde insanların nesneleri adlandırırken en çok kullandığı ve çocukların ilk öğrendiği düzey hangisidir?', 'Temel düzey (sandalye)', ['Üst düzey (mobilya)', 'Alt düzey (mutfak sandalyesi)', 'Bütün düzeyler eşit sıklıkta'], 'Temel düzey kategoriler, üyelerin birbirine en çok benzediği ve diğer kategorilerden en iyi ayrıldığı bilgi açısından en verimli düzeydir.'),
  ('Lawrence Barsalou\'nun incelediği "yanan bir evden kurtarılacak şeyler" gibi, belirli bir amaç için anlık oluşturulan kategorilere ne ad verilir?', 'Geçici (ad hoc) kategoriler', ['Temel düzey kategoriler', 'Doğal türler', 'Kalıtsal kategoriler'], 'Bu kategorilerin üyeleri (çocuklar, fotoğraf albümleri, belgeler) birbirine benzemez; ama amaca uygunluğa göre dereceli bir tipiklik yapısı gösterirler.'),
  ('Collins ve Quillian\'ın 1969 hiyerarşik ağ modeline göre "Kanarya deriyle kaplıdır" cümlesinin doğrulanması neden "Kanarya sarıdır" cümlesinden daha uzun sürer?', 'Bu özellik üst düzeydeki "hayvan" düğümünde saklandığı için ağda daha uzun yol gerektiğinden', ['"Deri" sözcüğünün gündelik dilde "sarı" sözcüğünden çok daha az sıklıkla kullanılmasından', 'Sarı rengin daha kolay imgelenmesinden', 'Kanaryaların derisinin olmamasından'], 'Modelde özellikler en genel uygulanabildikleri düzeyde bir kez saklanır (bilişsel ekonomi); doğrulama süresi, katedilen düzey sayısıyla artar.'),
  ('Meyer ve Schvaneveldt\'in 1971 sözcük karar görevinde "DOKTOR" sözcüğünden sonra gelen "HEMŞİRE" sözcüğünün, "EKMEK" sözcüğünden sonra gelene göre daha hızlı tanınmasına ne ad verilir?', 'Anlamsal hazırlama', ['Geriye ket vurma', 'Çerçeveleme etkisi', 'Kategorik algı'], 'İlişkili bir sözcük, anlamsal ağda bağlantılı kavramları önceden etkinleştirerek onların tanınmasını hızlandırır.'),
  ('Ekranda beliren harf dizisinin gerçek bir sözcük olup olmadığına mümkün olduğunca hızlı karar verilmesini isteyen ve zihinsel sözlüğü incelemede kullanılan görev hangisidir?', 'Sözcük karar görevi', ['Kısmi rapor görevi', 'Gölgeleme (sesli tekrarlama) görevi', 'Dikotik dinleme görevi'], 'Sözcük karar görevinde tepki süreleri, sözcük sıklığı ve hazırlama gibi etkenlerin zihinsel sözlüğe erişimi nasıl etkilediğini ölçmeye yarar.'),
  ('Gündelik dilde sık kullanılan sözcüklerin seyrek kullanılanlardan daha hızlı tanınıp okunmasına ne ad verilir?', 'Sözcük sıklığı etkisi', ['Sözcük uzunluğu etkisi', 'Sözcük üstünlüğü etkisi', 'Yalıtım etkisi'], 'Sık karşılaşılan sözcüklerin zihinsel sözlükteki temsilleri daha erişilebilir hâldedir; bu nedenle göz izleme ve sözcük karar görevlerinde daha kısa sürelerle işlenirler.'),
  ('Shepard ve Metzler\'in 1971 deneyinde iki üç boyutlu şeklin aynı olup olmadığına karar verme süresi, şekiller arasındaki dönüş açısı arttıkça nasıl değişmiştir?', 'Açıyla doğrusal olarak artmıştır', ['Açıdan bağımsız olarak sabit kalmıştır', 'Açı büyüdükçe azalmıştır', 'Yalnızca 180 derecede artmıştır'], 'Tepki süresinin dönüş açısıyla düzenli artması, katılımcıların şekilleri zihinlerinde gerçek bir nesneyi döndürür gibi döndürdüğünü düşündürür.'),
  ('Kosslyn ve arkadaşlarının 1978 çalışmasında katılımcılar ezberledikleri bir ada haritasında zihinsel olarak bir noktadan diğerine "gittiklerinde", tarama süresi neye bağlı bulunmuştur?', 'Noktalar arasındaki uzaklığa', ['Noktaların adlarının uzunluğuna', 'Haritanın rengine', 'Katılımcının adayı sevip sevmediğine'], 'Tarama süresinin uzaklıkla doğrusal artması, zihinsel imgelerin uzamsal özellikleri koruyan, resim benzeri temsiller olduğu görüşünü destekledi.'),
  ('Gözlerini kapattığında zihninde hiçbir görsel imge canlandıramadığını bildiren kişilerin durumu, Adam Zeman\'ın 2015\'te yaygınlaştırdığı hangi terimle adlandırılır?', 'Afantazi', ['Afazi', 'Agnozi', 'Amuzi'], 'Afantazi, istemli görsel imgelemenin yokluğudur; bu kişiler gündelik yaşamlarını çoğu zaman sözel ya da uzamsal bilgi kullanarak sorunsuz sürdürür.'),
  ('Stevens ve Coupe\'nin 1978 çalışmasında birçok Amerikalı, Nevada\'daki Reno\'nun Kaliforniya\'daki San Diego\'nun doğusunda olduğunu düşünmüştür; oysa Reno daha batıdadır. Bu hata neden kaynaklanır?', 'Şehirlerin, bağlı oldukları eyaletin konumuna göre kodlanmasından', ['Haritaların yanlış basılmış olmasından', 'Katılımcıların iki şehri hiç duymamış olmasından', 'Pusula yönlerinin her bölgede farklı adlandırılmasından ve haritaların ters basılmasından'], 'Zihinsel haritalarda konumlar çoğu zaman üst birimlere göre saklanır; Nevada Kaliforniya\'nın doğusunda olduğu için içindeki her şehir de doğuda varsayılır.'),
  ('"Bu yazı tatilini daha anlamlı geçirmek" ile "Bu denklemde x\'i bulmak" problemleri arasındaki temel fark nasıl adlandırılır?', 'Birincisi kötü tanımlanmış, ikincisi iyi tanımlanmış bir problemdir', ['Birincisi algoritmik, ikincisi sezgisel bir problemdir', 'İkisi de iyi tanımlanmış problemlerdir', 'Birincisi kapalı uçlu, ikincisi açık uçlu ve belirsiz hedefli bir problemdir'], 'İyi tanımlanmış problemlerde başlangıç durumu, hedef ve izin verilen işlemler açıktır; kötü tanımlanmış problemlerde ise hedef ve çözüm yolları belirsizdir.'),
  ('Newell ve Simon\'ın yaklaşımında başlangıç durumu, hedef durumu, ara durumlar ve bunlar arasında geçişi sağlayan işlemlerin tümüne ne ad verilir?', 'Problem uzayı', ['Bilişsel harita', 'Zihinsel set', 'Çalışma alanı'], 'Problem çözme, problem uzayında başlangıç durumundan hedef duruma götüren bir işlem dizisinin aranması olarak tanımlanır.'),
  ('Bir öğrencinin bir proje ödevini "kaynak bulma, taslak yazma, düzeltme" gibi alt hedeflere bölüp her adımda mevcut durum ile hedef arasındaki farkı azaltacak işlemi seçmesi hangi stratejidir?', 'Araç-amaç çözümlemesi', ['Deneme-yanılma', 'Rastgele arama', 'Algoritmayla tümüyle tarama'], 'Newell ve Simon\'ın Genel Problem Çözücü programının temel stratejisi olan araç-amaç çözümlemesi, farkları alt hedeflerle sistemli biçimde azaltmaya dayanır.'),
  ('Sisli bir dağda zirveye ulaşmaya çalışan birinin her adımda yalnızca en dik yükselen yönü seçmesi gibi, hedefe doğrudan yaklaştıran adımı seçme stratejisine ne ad verilir?', 'Tepe tırmanma', ['Geriye doğru çalışma', 'Araç-amaç çözümlemesi', 'Analojik aktarım'], 'Tepe tırmanmada her adım hedefe biraz daha yaklaştırmalıdır; bu strateji, hedefe ulaşmak için geçici olarak geri gitmeyi gerektiren problemlerde kişiyi çıkmaza sokar.'),
  ('Labirent bulmacalarını çıkıştan başlayarak girişe doğru çözmek ya da bir geometri ispatına kanıtlanması istenen sonuçtan başlamak hangi stratejiye örnektir?', 'Geriye doğru çalışma', ['Tepe tırmanma', 'Deneme-yanılma', 'Öbekleme'], 'Hedef durumun açık, başlangıçtan çıkan yolların ise çok olduğu problemlerde sondan başa doğru ilerlemek arama alanını önemli ölçüde daraltır.'),
  ('Ericsson ve Simon\'ın geliştirdiği, katılımcılardan problem çözerken aklından geçenleri yüksek sesle söylemelerinin istenip kaydedildiği yönteme ne ad verilir?', 'Sesli düşünme (protokol analizi)', ['Gölgeleme (sesli tekrar yöntemi)', 'İçebakış (yapısalcı yöntem)', 'Serbest çağrışım (psikanalitik yöntem)'], 'Sesli düşünme protokolleri, problem çözme sırasında hangi stratejilerin ve ara durumların kullanıldığını adım adım izlemeyi sağlar.'),
  ('Dokuz noktayı kalemi kaldırmadan dört düz çizgiyle birleştirme bulmacasının çoğu kişiye zor gelmesinin nedeni nedir?', 'Noktaların oluşturduğu karenin dışına çıkılmayacağının varsayılması', ['Bulmacanın matematiksel olarak çözümsüz olması', 'Kişilerin dokuz noktayı aynı anda görememesi', 'Kalemle çizilen çizgilerin eğri olması gerektiği ve bunun fark edilememesi'], 'Çözüm, çizgilerin noktalardan oluşan karenin dışına taşmasını gerektirir; kişiler kimsenin koymadığı bu kısıtlamayı problem temsiline kendileri ekler.'),
  ('Norman Maier\'in 1931 "iki ip" probleminde, birbirine uzak asılı iki ipi aynı anda tutmanın yolunu arayan katılımcıların çözüme ulaşmasını kolaylaştıran ipucu neydi?', 'Deneycinin "kazara" iplerden birini sallandırması', ['Deneycinin çözümü yazılı olarak verip katılımcıya okutması', 'Odanın ışıklarının kapatılması', 'Katılımcılara daha uzun ipler verilmesi'], 'İpin sallanması, pense gibi bir ağırlık bağlanıp ipin sarkaç gibi salınabileceği fikrini uyandırmış; birçok katılımcı ipucunu fark ettiğini bildirmeden çözüme ulaşmıştır.'),
  ('Uzun süre çözemediği bir probleme bir süre ara verip başka işlerle uğraşan bir kişinin sonra çözümü kolayca bulmasına ne ad verilir?', 'Kuluçka etkisi', ['İşlevsel saplantı', 'Zihinsel set', 'Geriye ket vurma'], 'Kuluçka döneminde yanlış yaklaşımlar unutulabilir, yorgunluk geçer ya da bilinç dışı işlem sürer; bu da probleme yeni bir gözle dönmeyi kolaylaştırır.'),
  ('Sarnoff Mednick\'in Uzak Çağrışımlar Testi\'nde katılımcılardan ne yapmaları istenir?', 'Verilen üç sözcüğün her biriyle ilişkili tek bir sözcük bulmaları', ['Bir nesnenin olabildiğince çok sayıda ve özgün kullanım alanını sıralamaları', 'Bir resimdeki eksik ayrıntıyı bulmaları', 'Verilen bir öyküyü kendi sözleriyle özetlemeleri'], 'Örneğin İngilizce "cottage, Swiss, cake" sözcükleri için "cheese" (peynir) yanıtı aranır; Mednick yaratıcılığı uzak çağrışımları birleştirebilme yeteneği olarak tanımlamıştır.'),
  ('Karl Duncker\'in "ışın problemi"nde, sağlıklı dokuya zarar vermeden bir tümörü yok etmenin yolu sorulur. Problemin standart çözümü hangisidir?', 'Farklı yönlerden gelen zayıf ışınların tümörde birleştirilmesi', ['Tek ve çok güçlü bir ışının doğrudan tümöre gönderilmesi', 'Tümörün ışın kullanılmadan ilaçla küçültülmesi', 'Işının sağlıklı dokuyu soğutarak geçirilmesi'], 'Tek başına zararsız olan ışınlar yalnızca tümörde kesişerek yeterli şiddete ulaşır; bu, analojik problem çözme araştırmalarının en ünlü problemidir.'),
  ('Analojik problem çözmede iki problemin "derin yapısal" benzerliği ile "yüzeysel" benzerliği arasındaki ayrım için hangisi doğrudur?', 'Analojiler çoğu kez yüzey benzerliğiyle hatırlanır, çözüm aktarımı ise yapıya bağlıdır', ['Yüzeysel benzerlik, çözümün aktarılmasında yapısal benzerlikten her zaman daha belirleyicidir', 'İki tür benzerlik her zaman birlikte bulunur ve ayrılamaz', 'Yapısal benzerlik yalnızca matematik problemlerinde ve çocuklarda vardır'], 'Kaynak ile hedef aynı karakterleri ya da nesneleri içerdiğinde hatırlama kolaylaşır; ancak doğru çözüm, ilişkiler ve ilkeler düzeyindeki yapısal örtüşmeden gelir.'),
  ('"Hiçbir besleyici şey ucuz değildir. Bazı vitamin hapları ucuzdur. O hâlde bazı vitamin hapları besleyici değildir." Bu geçerli çıkarım inanılmaz bulunduğu için çoğu kişi tarafından geçersiz sayılmaktadır. Bu olguya ne ad verilir?', 'İnanç yanlılığı', ['Atmosfer etkisi', 'Çerçeveleme etkisi', 'Kumarbaz yanılgısı'], 'Evans ve arkadaşlarının gösterdiği inanç yanlılığında kişiler bir çıkarımın geçerliliğini mantıksal yapısına göre değil, sonucun inandırıcılığına göre değerlendirir.'),
  ('Philip Johnson-Laird\'in zihinsel modeller kuramına göre insanlar tümdengelimsel çıkarımları nasıl yapar?', 'Öncüllere uyan olası durumların zihinsel modellerini kurup sonucu sınayarak', ['Yalnızca biçimsel mantık kurallarını otomatik olarak uygulayarak', 'Sonucu, deneyimlerimizdeki benzer örneklerin sıklığına ve akla gelme kolaylığına göre tahmin ederek', 'Öncülleri hiç okumadan sonucun inandırıcılığına bakarak'], 'Kurama göre güçlük, akılda tutulması gereken model sayısıyla artar; birden fazla model gerektiren kıyaslarda hata oranı belirgin biçimde yükselir.'),
  ('Bir sorunun hızlı, otomatik ve sezgisel düşünme ile yavaş, çaba gerektiren ve kurallı düşünme arasındaki farkı vurgulayan, "Sistem 1 – Sistem 2" adlandırmasıyla bilinen yaklaşım hangisidir?', 'İkili süreç kuramı', ['Bilgi işleme düzeyleri kuramı', 'Özellik bütünleştirme kuramı', 'Bağlantıcı ağ kuramı'], 'İkili süreç kuramları, yargı ve akıl yürütmedeki pek çok yanlılığı hızlı Sistem 1\'in yanıtlarının yavaş Sistem 2 tarafından denetlenmemesiyle açıklar.'),
  ('Yazı-tura atışında art arda beş kez tura geldikten sonra bir kişinin "Artık yazı gelme olasılığı çok yükseldi" demesi hangi yanılgıya örnektir?', 'Kumarbaz yanılgısı', ['Sıcak el inancı', 'Birleşim yanılgısı', 'Doğrulama yanlılığı'], 'Bağımsız olaylarda geçmiş sonuçlar sonraki atışın olasılığını değiştirmez; kumarbaz yanılgısı, kısa dizilerin de uzun dönem ortalamasını yansıtması gerektiği beklentisinden doğar.'),
  ('Loren ve Jean Chapman\'ın çalışmasında klinisyenlerin, aslında ilişki bulunmayan "büyük gözler çizme" ile "kuşkuculuk" arasında güçlü bir bağ "görmeleri" hangi yanılgıya örnektir?', 'Yanıltıcı ilişki (korelasyon)', ['Ortalamaya dönüş', 'Geri dönüş ketlenmesi (dikkat etkisi)', 'Birleşim yanılgısı'], 'Yanıltıcı ilişkide önceden beklenen ilişkiye uyan durumlar daha çok fark edilip hatırlanır; böylece veride olmayan bir ilişki algılanır.'),
  ('Tversky ve Kahneman\'ın 1974 deneyinde katılımcılar önce 10 ya da 65\'te duracak biçimde ayarlanmış bir çarkın çevrildiğini görmüş, ardından Birleşmiş Milletler\'deki Afrika ülkelerinin oranını tahmin etmiştir. Sonuç ne olmuştur?', '65 görenlerin tahminleri 10 görenlerinkinden belirgin biçimde yüksektir', ['Çarkın gösterdiği sayı tahminleri hiç etkilememiş, iki grup aynı oranı vermiştir', 'Çarkta 10 görenler daha yüksek tahminde bulunmuştur', 'Katılımcıların tamamı doğru oranı bilmiştir'], 'Açıkça rastgele ve ilgisiz bir sayı bile tahminleri kendine doğru çekmiştir (ortancalar 25 ve 45); bu, çapalama ve yetersiz ayarlama sezgiselinin çarpıcı bir gösterimidir.'),
  ('Çoğu insan "kesin 3.000 lira kazanmak" ile "%80 olasılıkla 4.000 lira kazanmak" arasında kesin kazancı seçer; ancak "kesin 3.000 lira kaybetmek" ile "%80 olasılıkla 4.000 lira kaybetmek" arasında kumarı seçer. Bu tersine dönüşe ne ad verilir?', 'Yansıma etkisi', ['Sahiplik etkisi', 'Çapalama etkisi', 'Tuzak etkisi'], 'Beklenti kuramında kazanç bölgesindeki riskten kaçınma, kayıp bölgesinde risk arayışına dönüşür; Kahneman ve Tversky buna yansıma etkisi adını verdi.'),
  ('Bir seçim sonucu açıklandıktan sonra insanların "Ben zaten bu sonucu bekliyordum" deyip önceden verdikleri tahminleri olduğundan daha isabetli hatırlamalarına ne ad verilir?', 'Sonradan görme yanlılığı', ['Planlama yanılgısı', 'Kumarbaz yanılgısı', 'Yansıma etkisi'], 'Baruch Fischhoff\'un incelediği bu yanlılıkta sonucun bilinmesi, olayın önceden ne kadar öngörülebilir olduğuna ilişkin yargıları ve kişinin kendi tahminlerini hatırlayışını çarpıtır.'),
  ('Bir öğrencinin bitirme tezini üç ayda bitireceğini düşünmesi, benzer tezlerin genellikle sekiz ay sürdüğünü bilmesine karşın bu tahmini yapması hangi yanılgıdır?', 'Planlama yanılgısı', ['Batık maliyet yanılgısı', 'Yanıltıcı ilişki', 'Kaynak izleme hatası'], 'Planlama yanılgısında kişi kendi görevine ilişkin iyimser senaryolara odaklanır ve benzer görevlerin geçmiş sürelerini (dış bakış açısını) göz ardı eder.'),
  ('Kahneman ve arkadaşlarının "soğuk su" deneyinde katılımcılar bir elini 60 saniye 14 °C suda tutmuş, diğer denemede 60 saniyeye ek olarak 30 saniye biraz daha ılık suda tutmuştur. Tekrar etmek için hangisini seçmişlerdir?', 'Çoğunluk daha uzun (90 saniyelik) denemeyi', ['Çoğunluk kısa (60 saniyelik) denemeyi', 'Katılımcılar iki deneme arasında kararsız kalıp yazı-tura atmıştır', 'Katılımcılar üçüncü, daha soğuk bir denemeyi istemiştir'], 'Daha uzun deneme daha fazla toplam rahatsızlık içerdiği hâlde daha iyi bir sonla bittiği için daha olumlu hatırlanmış; bu, hatırlanan benlik ile deneyimleyen benlik arasındaki ayrımı gösterir.'),
  ('Paul Slovic\'in "duygu sezgiseli"ne göre insanlar nükleer enerji gibi bir teknolojinin risk ve yararlarını değerlendirirken ne yapma eğilimindedir?', 'Teknolojiye duydukları genel duyguyu risk ve yarar yargılarına yansıtmak', ['Risk ve yararı istatistiklere dayanarak birbirinden bağımsız hesaplamak', 'Riskleri her zaman gerçekte olduğundan daha düşük tahmin etmek', 'Yalnızca uzman görüşlerine dayanmak ve kendi duygularını değerlendirmeye hiç karıştırmamak'], 'Bir şeyi sevenler onun riskini düşük, yararını yüksek; sevmeyenler ise tersini görme eğilimindedir; duygu, karmaşık bir değerlendirmenin kestirmesi olarak kullanılır.'),
  ('Bir dükkânda 400 liralık A televizyonu ile 600 liralık daha kaliteli B televizyonu varken, satıcı 650 liraya B\'den her yönden daha kötü bir C modeli ekleyince B\'nin satışlarının artması hangi etkiye örnektir?', 'Tuzak etkisi', ['Sahiplik etkisi', 'Yansıma etkisi', 'Tepe-son etkisi'], 'Açıkça daha kötü bir seçenek, ona benzeyen ve ondan üstün olan seçeneği karşılaştırmada daha çekici kılar; Huber, Payne ve Puto bu etkiyi 1982\'de tanımladı.'),
  ('Iyengar ve Lepper\'ın 2000 reçel deneyinde 24 çeşit reçelin sergilendiği tezgâh daha çok ilgi çekmiş, ancak satın alma oranı 6 çeşitlik tezgâhta çok daha yüksek çıkmıştır. Bu bulgu nasıl adlandırılır?', 'Seçenek fazlalığı etkisi', ['Tuzak etkisi', 'Çapalama etkisi', 'Sonradan görme yanlılığı'], 'Seçenek sayısı çok arttığında karşılaştırma yükü ve pişmanlık kaygısı artar; bu da karar vermeyi erteleme ya da hiç seçim yapmama eğilimine yol açabilir.'),
  ('Dunning ve Kruger\'in 1999 çalışmasında mantık ve dil bilgisi testlerinde en düşük puanı alan katılımcıların kendi performanslarına ilişkin tahminleri için ne bulunmuştur?', 'Kendilerini ortalamanın üstünde görerek en çok abartanların onlar olduğu', ['Kendi düşük performanslarını tam olarak bildikleri', 'Performanslarını gerçekte olduğundan daha düşük tahmin ettikleri ve testi tekrar etmek istedikleri', 'Teste katılmayı reddettikleri'], 'Bir alandaki beceri eksikliği, kişinin kendi hatalarını fark etmesini sağlayan üst bilişsel beceriyi de zayıflatır; bu nedenle en düşük performans gösterenler en büyük abartıyı yapar.'),
  ('Gilbert ve Wilson\'ın araştırmalarına göre insanlar, bir sınavı kaybetme ya da sevdikleri bir takımın kazanması gibi olayların duygularını ne kadar güçlü ve uzun süre etkileyeceğini genellikle nasıl tahmin eder?', 'Olduğundan daha güçlü ve uzun süreli', ['Olduğundan daha zayıf ve kısa süreli', 'Tam olarak doğru', 'Yalnızca olumlu olaylarda doğru, olumsuz olaylarda hep eksik'], 'Duygusal öngörüde insanlar uyum yeteneklerini ve dikkatlerinin başka olaylara kayacağını göz ardı eder; bu yüzden duygusal tepkilerinin şiddetini ve süresini abartır.'),
  ('"The horse raced past the barn fell" (Ahırın önünden koşturulan at düştü) gibi, okuyucuyu önce yanlış bir sözdizimsel yoruma götürüp sonra yeniden çözümlemeye zorlayan cümlelere ne ad verilir?', 'Bahçe yolu cümleleri', ['Telgraf cümleler', 'Holofrastik cümleler', 'Devrik (ters kurulu) cümleler'], 'Bahçe yolu cümlelerinde okuyucu en olası yapıyı hemen seçer; cümlenin sonunda bu yorumun yanlış olduğu anlaşılınca geri dönüp yeniden çözümleme yapmak gerekir.'),
  ('Okuma sırasında gözlerin metin üzerinde akıcı biçimde kaymadığı, kısa duraklamalar ile hızlı sıçramalar arasında gidip geldiği bilinir. Bu duraklamalara ve sıçramalara ne ad verilir?', 'Sabitlemeler ve sakkadlar', ['Yakınsamalar ve uyumlar', 'Ardıl imgeler ve geriye doğru maskeler', 'Kırpmalar ve titremeler'], 'Okuma sırasında bilgi büyük ölçüde yaklaşık 200–250 milisaniyelik sabitlemelerde alınır; sakkad denen hızlı göz sıçramaları sırasında görsel girdi büyük ölçüde baskılanır.'),
  ('Kutas ve Hillyard\'ın 1980 çalışmasında "Kahvesine şeker ve çorap koydu" gibi anlamca uyumsuz bir sözcükle biten cümlelerde, beyin dalgalarında yaklaşık 400 milisaniyede ortaya çıkan olumsuz dalgaya ne ad verilir?', 'N400', ['P300', 'Alfa dalgası', 'Hazırlık potansiyeli'], 'N400, sözcüğün bağlama anlamca uyma derecesine duyarlıdır; beklenmedik ya da anlamsız sözcüklerde genliği artar.'),
  ('Noam Chomsky\'nin 1957\'de örnek verdiği "Colorless green ideas sleep furiously" (Renksiz yeşil fikirler öfkeyle uyur) cümlesi neyi göstermek için kullanılmıştır?', 'Anlamsız bir cümlenin dil bilgisi bakımından doğru olabileceğini', ['Renk sözcüklerinin her dilde farklı algılandığını', 'Çocukların ilk sözcüklerinin sıfatlardan oluştuğunu', 'Uyku sırasında dil işlemenin durduğunu ve rüyalarda sözdiziminin bozulduğunu'], 'Örnek, sözdiziminin anlamdan bağımsız kurallarla değerlendirilebileceğini, dil bilgisel doğruluğun anlamlılıktan ayrı olduğunu vurgular.'),
  ('Konuşması akıcı, anlaması görece iyi olan ama duyduğu sözcük ve cümleleri tekrar etmekte büyük güçlük çeken bir hastadaki afazi türü hangisidir ve hangi yapının hasarıyla ilişkilendirilir?', 'İletim afazisi; kavisli demet', ['Broca afazisi; alt ön kıvrım', 'Wernicke afazisi; üst şakak kıvrımı', 'Global afazi; bütün dil alanları'], 'İletim afazisinde Wernicke ile Broca alanlarını bağlayan lif demeti etkilendiği için, anlama ve konuşma görece korunurken tekrarlama özellikle bozulur.'),
  ('Bir hastanın nesneleri tanıyıp ne işe yaradığını anlatabildiği hâlde adlarını bulmakta güçlük çekmesi, örneğin makas için "kâğıt kesmeye yarayan şey" demesi hangi bozukluktur?', 'Anomi', ['Agnozi', 'Apraksi', 'Aleksi'], 'Anomi sözcük bulma güçlüğüdür; kavram bilgisi sağlam olmakla birlikte sözcüğün ses biçimine erişim bozulmuştur.'),
  ('Paul Grice\'ın işbirliği ilkesine göre, "Toplantı nasıldı?" sorusuna "Kurabiyeler güzeldi" diye yanıt veren kişi muhtemelen ne ima etmektedir?', 'Toplantının kendisinin pek iyi geçmediğini', ['Kurabiyelerin toplantının en önemli gündemi olduğunu', 'Soruyu hiç duymadığını', 'Toplantıya katılmadığını ve kurabiyeleri evde yediğini'], 'Konuşmacı ilgililik ilkesini görünüşte çiğnediği için dinleyici ek bir anlam çıkarır; bu "konuşma imaları", söylenenin ötesinde anlatılanı açıklar.'),
  ('Grice\'ın konuşma ilkelerinden "nicelik" ilkesi konuşmacıdan ne bekler?', 'Gerektiği kadar, ne eksik ne fazla bilgi vermesini', ['Yalnızca doğru olduğuna inandığı şeyleri söylemesini', 'Konuyla ilgili konuşmasını', 'Açık ve düzenli konuşup belirsizlikten kaçınmasını'], 'Grice\'ın dört ilkesi nicelik (yeterli bilgi), nitelik (doğruluk), ilişki (ilgililik) ve tarzdır (açıklık); diğer seçenekler sırasıyla nitelik, ilişki ve tarz ilkelerine karşılık gelir.'),
  ('Dilsel görelilik tartışmasında "güçlü" görüş ile "zayıf" görüş arasındaki fark nedir?', 'Güçlü görüş dilin düşünceyi belirlediğini, zayıf görüş ise yalnızca etkilediğini savunur', ['Güçlü görüş dilin düşünceyi hiç etkilemediğini, zayıf görüş belirlediğini savunur', 'İki görüş de dilin yalnızca ses yapısıyla ilgilenir', 'Güçlü görüş yalnızca hayvan iletişimi, zayıf görüş ise yalnızca insan dili için ileri sürülmüştür'], 'Dilsel belirlenimcilik denen güçlü görüş büyük ölçüde terk edilmiştir; dilin dikkat, bellek ve sınıflamayı belirli ölçüde etkilediğini söyleyen zayıf görüş ise deneysel destek bulmuştur.'),
  ('Berlin ve Kay\'in 1969\'da birçok dilin renk terimlerini inceledikleri çalışmanın temel bulgusu hangisidir?', 'Temel renk terimlerinin diller arasında evrensel bir sırayla eklendiği', ['Her dilin renk terimlerinin tamamen keyfî, rastgele ve yalnızca kültüre özgü olduğu', 'Bütün dillerde tam olarak on bir temel renk terimi bulunduğu', 'Renk terimi az olan dillerin konuşurlarının renk körü olduğu'], 'Yalnızca iki renk terimi olan diller açık-koyu ayrımı yapar, üçüncü terim her zaman kırmızıdır; bu düzenlilik renk sınıflamasında evrensel algısal temellere işaret eder.'),
  ('Bir dilde belli bir kavram için çok sayıda ayrıntılı sözcük bulunmasının, o dili konuşanların o alandaki ayrımları daha kolay fark etmesiyle ilişkilendirilmesi hangi tartışmanın konusudur?', 'Dilsel görelilik tartışmasının', ['Bilinç akışı tartışmasının', 'Psikolojik refrakter dönem tartışmasının', 'Bellek taraması tartışmasının'], 'Bu tür örnekler, dilin dikkat ve kategorilere etkisinin gösterilmesinde kullanılır; ancak sözcük sayısı farklarının algıyı mı yoksa yalnızca uzmanlık ve ilgiyi mi yansıttığı tartışmalıdır.'),
  ('Ekranda kısa süre gösterilen noktaların sayısını belirleme görevinde, 1–4 noktanın sayma gerektirmeden neredeyse anında ve hatasız bilinmesine, daha fazlası için ise sürenin belirgin biçimde uzamasına ne ad verilir?', 'Bir bakışta sayılama', ['Öbekleme', 'Bellek taraması', 'Kategorik algı'], 'Küçük kümelerin sayısı hızlı ve doğru biçimde, adeta "görülerek" belirlenir; bu sınırın ötesinde tek tek sayma ya da kestirim gerekir.'),
  ('Pylyshyn ve Storm\'un "çoklu nesne izleme" görevinde katılımcılar özdeş ve rastgele hareket eden noktalardan birkaçını gözle izlemeye çalışmıştır. Kişilerin genellikle kaç hedefi başarıyla izleyebildiği bulunmuştur?', 'Yaklaşık 4–5 hedef', ['Yaklaşık 15–20 hedef', 'Yalnızca 1 hedef', 'Sınırsız sayıda hedef'], 'Bulgu, dikkatin aynı anda sınırlı sayıda nesneye "işaretçi" bağlayabildiğini ve bunları konumları değişse de takip edebildiğini düşündürür.'),
  ('Karşısındaki kişinin bir yöne baktığını gören birinin dikkatinin, istemese bile hemen o yöne kayması hangi araştırma bulgusudur?', 'Bakışla dikkat yönlendirme', ['Geri dönüş ketlenmesi', 'Dikkat kırpması', 'Bütünün önceliği'], 'Friesen ve Kingstone gibi araştırmacılar, ekrandaki bir yüzün bakış yönünün, öngörücü olmadığı bilinse bile dikkati otomatik olarak o tarafa kaydırdığını göstermiştir.'),
  ('Ekranın iki yanında biri tehdit içeren, biri nötr iki sözcük kısa süre gösterilip ardından birinin yerinde bir nokta beliren ve kaygılı kişilerin tehdit sözcüğünün yerindeki noktaya daha hızlı tepki verdiği görev hangisidir?', 'Nokta sondası görevi', ['Londra Kulesi görevi', 'Kısmi rapor görevi', 'Bölünmüş dizi görevi'], 'Nokta sondası görevi, dikkatin hangi uyarıcıya yöneldiğini tepki süresiyle ölçer; kaygılı bireylerde tehdide yönelik dikkat yanlılığı sıkça bulunmuştur.'),
  ('Örümcek fobisi olan bir kişinin, "ağ", "örümcek" gibi sözcüklerin yazıldığı mürekkep rengini söylerken nötr sözcüklere göre yavaşlaması hangi görevin bulgusudur?', 'Duygusal Stroop görevi', ['Wisconsin kart eşleme görevi', 'Wason seçme görevi', 'Londra Kulesi görevi'], 'Duygusal Stroop\'ta sözcüğün anlamı renkle çatışmaz; yavaşlama, kişisel olarak önemli ya da tehdit içeren içeriğin dikkati kendine çekmesinden kaynaklanır.'),
  ('Görme alanında aniden beliren yeni bir nesnenin, kişi başka bir şeye odaklanmışken bile dikkati otomatik olarak çekmesine ne ad verilir?', 'Dikkat yakalanması', ['Dikkat kırpması', 'Yineleme körlüğü', 'Bilişsel yük'], 'Ani başlangıçlar ve hareket gibi bazı uyarıcı özellikleri, kişinin amaçlarından bağımsız olarak dikkati kendine çekebilir; Yantis ve Jonides bu etkiyi incelemiştir.'),
  ('Michael Posner\'ın dikkat ağları modeline göre dikkat hangi üç ayrı ağdan oluşur?', 'Uyarılma, yönelme ve yürütücü denetim', ['Algı, bellek ve dil', 'Duyum, eşik ve uyum', 'Kodlama, depolama ve sonradan geri getirme'], 'Posner\'a göre uyarılma ağı hazır olma durumunu, yönelme ağı dikkatin bir konuma kaydırılmasını, yürütücü ağ ise çatışmaların çözümünü sağlar; Dikkat Ağı Testi bu üç bileşeni ayrı ayrı ölçer.'),
  ('Bir öğrencinin ders kitabını okurken gözlerinin satırlarda ilerlediği hâlde aklının başka yerde olduğunu fark etmesi hangi olguya örnektir ve beyinde hangi ağın etkinliğiyle ilişkilendirilir?', 'Zihin gezinmesi; varsayılan mod ağı', ['Dikkat kırpması; birincil görme korteksi', 'Duyusal uyum; beyincik', 'Değişim körlüğü; motor korteks'], 'Dış göreve odaklanılmadığı ve içsel düşüncelere dalındığı anlarda medial ön ve arka beyin bölgelerinden oluşan varsayılan mod ağının etkinliği artar.'),
  ('Bir kişi görsel olarak zorlu bir görevle meşgulken çalan ve normalde rahatça duyulacak bir sesi fark etmemesine ne ad verilir?', 'Dikkatsizlik sağırlığı', ['Kokteyl partisi etkisi', 'Kategorik algı', 'Ses yerelleştirme hatası'], 'Dikkatsizlik sağırlığı, dikkatsizlik körlüğünün işitsel karşılığıdır; yüksek algısal yük, beklenmedik işitsel uyarıcıların bilince ulaşmasını engelleyebilir.'),
  ('Bir konuşmada konuşmacı değiştiği hâlde dinleyicinin bunu fark etmemesi gibi işitsel sahnedeki belirgin değişikliklerin gözden kaçmasına ne ad verilir?', 'Değişim sağırlığı', ['Dikkat kırpması', 'Ekoik bellek etkisi', 'Sesbirimsel tamamlama'], 'Değişim sağırlığı, görsel değişim körlüğünün işitsel karşılığıdır; dinleyici anlam üzerine odaklandığında sesin kimin olduğu gibi özellikler ayrıntılı izlenmeyebilir.'),
  ('Durmakta olan bir trende otururken yandaki tren hareket etmeye başladığında, kişinin kendi treninin hareket ettiğini sanmasına ne ad verilir?', 'Öz hareket yanılsaması', ['Hareket ardıl etkisi', 'Kendiliğinden (otokinetik) hareket etkisi', 'Phi olgusu'], 'Görme alanının büyük bölümünü kaplayan hareket, beyin tarafından kendi hareketimiz olarak yorumlanabilir; bu durum görmenin denge ve hareket algısındaki gücünü gösterir.'),
  ('Dönen bir berber direğindeki eğik çizgilerin, aslında yatay dönmesine rağmen yukarı doğru akıyormuş gibi görünmesi hangi sorunla açıklanır?', 'Açıklık (aperture) sorunu', ['Bağlama sorunu', 'Bölütleme sorunu', 'Ters çevirme (yüz ters çevirme) sorunu'], 'Dar bir açıklıktan görülen çizginin gerçek hareket yönü belirsizdir; görme sistemi hareketi çizgilerin uçlarının ve çerçevenin uzun kenarının yönüne göre yorumlar.'),
  ('Bir noktaya gözlerinizi kıpırdatmadan uzun süre baktığınızda çevredeki soluk bir lekenin yavaş yavaş kaybolmasına ne ad verilir?', 'Troxler solması', ['Mach bantları', 'Hermann ızgarası', 'Kör görme'], 'Sabit kalan uyarıcılara karşı nöronlar uyum gösterir; küçük göz hareketleri bunu genellikle önlese de çevredeki bulanık uyarıcılar sabit bakışta silikleşir.'),
  ('Her iki göze çok farklı görüntüler gösterildiğinde, kişinin ikisini birleşik görmek yerine birkaç saniyede bir birinden ötekine geçerek yalnızca birini algılamasına ne ad verilir?', 'Binoküler rekabet', ['Retinal farklılık', 'Yakınsama', 'Stereoskopik birleşme'], 'Uyarıcı sabit kaldığı hâlde bilinçli algının dönüşümlü değişmesi, binoküler rekabeti bilincin sinirsel karşılıklarını araştırmada değerli bir araç yapar.'),
  ('İki rakamdan hangisinin büyük olduğuna karar verirken 2 ile 9 karşılaştırmasının, 7 ile 8 karşılaştırmasından daha hızlı yapılmasına ne ad verilir?', 'Sayısal uzaklık etkisi', ['Sözcük sıklığı (kullanım) etkisi', 'Dizi konum etkisi', 'Kip etkisi'], 'Moyer ve Landauer\'in 1967\'de gösterdiği uzaklık etkisi, sayıların zihinde birbirine yakın değerlerin örtüştüğü analog bir büyüklük temsiliyle tutulduğunu düşündürür.'),
  ('Normal zekâya ve eğitim olanağına sahip olduğu hâlde sayı kavramı, basit aritmetik işlemler ve sayısal büyüklükleri karşılaştırmada kalıcı güçlük çeken bir çocuktaki özgül öğrenme güçlüğü hangisidir?', 'Diskalkuli', ['Disleksi', 'Disgrafi', 'Dispraksi'], 'Diskalkuli matematiksel öğrenme güçlüğüdür; disleksi okuma, disgrafi yazma, dispraksi ise motor planlama güçlüğünü anlatır.'),
  ('"Fincan, tabağın solunda" gibi konumu gözlemcinin kendi bedenine göre tanımlamak ile "Fincan, masanın kuzey kenarında" gibi çevredeki sabit noktalara göre tanımlamak arasındaki ayrım nasıl adlandırılır?', 'Benmerkezli ve dışmerkezli çerçeveler', ['Bildirimsel ve işlemsel bellek sistemleri', 'Açık ve örtük dikkat', 'Mutlak ve fark eşiği'], 'Benmerkezli çerçeve gözlemci hareket edince değişir; dışmerkezli çerçeve ise gözlemciden bağımsızdır ve bilişsel haritaların temelini oluşturur.'),
  ('Karanlıkta yürüyen birinin attığı adımları ve dönüşleri sürekli toplayarak başladığı noktanın yönünü ve uzaklığını kestirebilmesine ne ad verilir?', 'Yol bütünleştirme', ['Optik akış', 'Hareket paralaksı', 'Bilişsel çelişki'], 'Yol bütünleştirme, görsel işaretler olmadan kendi hareket bilgisini biriktirerek konum güncellemedir; çöl karıncaları gibi birçok hayvan da bu yöntemi kullanır.'),
  ('Sıçanların hipokampusunda, hayvan ortamın belirli bir yerinde bulunduğunda etkinleşen "yer hücreleri"ni keşfederek 2014 Nobel Tıp Ödülü\'nü Moser çiftiyle paylaşan bilim insanı kimdir?', 'John O\'Keefe', ['Eric Kandel', 'Roger Sperry', 'Torsten Wiesel'], 'O\'Keefe\'nin yer hücreleri ile May-Britt ve Edvard Moser\'in entorinal korteksteki ızgara hücreleri, beynin uzamsal konum sistemini oluşturan temel bileşenler olarak ödüllendirildi.'),
  ('May-Britt ve Edvard Moser\'in entorinal kortekste bulduğu ve hayvan ortamda dolaşırken düzenli altıgen bir örüntünün köşelerinde etkinleşen hücrelere ne ad verilir?', 'Izgara hücreleri', ['Yer hücreleri', 'Ayna nöronları', 'Karmaşık hücreler'], 'Izgara hücreleri bir koordinat sistemi gibi çalışarak mesafe ve konum bilgisini sağlar; yer hücreleriyle birlikte "beynin GPS\'i" olarak anılır.'),
  ('Eleanor Maguire\'ın 2000 çalışmasında, Londra taksi şoförlerinin hipokampuslarının arka bölümünün kontrol grubuna göre daha büyük olduğu ve bu farkın meslekte geçirilen süreyle arttığı bulunmuştur. Bu bulgu neyi düşündürür?', 'Yoğun uzamsal bilgi kullanımının beyinde yapısal değişiklik yaratabildiğini', ['Hipokampus büyüklüğünün yalnızca kalıtımla belirlendiğini ve deneyimden etkilenmediğini', 'Taksi şoförlerinin bellek sorunları yaşadığını', 'Araba kullanmanın görme korteksini küçülttüğünü'], 'Farkın mesleki deneyim süresiyle artması, yalnızca doğuştan farklılıkla değil, kullanıma bağlı nöroplastisiteyle açıklanmasını destekler.'),
  ('Hick-Hyman yasasına göre seçim tepki süresi, olası seçenek sayısıyla nasıl ilişkilidir?', 'Seçenek sayısının logaritmasıyla artar', ['Seçenek sayısıyla doğru orantılı olarak artar', 'Seçenek sayısının karesiyle artar', 'Seçenek sayısından bağımsızdır'], 'Seçenek sayısı ikiye katlandıkça tepki süresine yaklaşık sabit bir miktar eklenir; bu, kararın bilgi miktarına (bit) göre ölçeklendiğini gösterir.'),
  ('Fitts yasasına göre bir fare imlecinin bir düğmeye ulaşma süresi hangi etkenlere bağlıdır?', 'Uzaklık arttıkça ve hedef küçüldükçe süre uzar', ['Yalnızca hedefin rengine bağlıdır', 'Hedef büyüdükçe süre uzar', 'Uzaklık ve büyüklükten bağımsız olarak, her hedef için sabit kalır'], 'Fitts yasası, hareket süresini uzaklığın hedef genişliğine oranının logaritmasına bağlar; arayüz tasarımında sık kullanılan düğmelerin büyük ve yakın konmasının gerekçesidir.'),
  ('Bir görevde daha hızlı yanıt vermeye çalışıldıkça hata oranının artması, daha dikkatli olunca ise yanıtların yavaşlaması hangi kavramla adlandırılır?', 'Hız-doğruluk ödünleşimi', ['Psikolojik refrakter dönem', 'Sinyal saptama duyarlılığı', 'Yerkes-Dodson yasası'], 'Kişiler hız ile doğruluk arasında bir denge noktası seçer; bu nedenle tepki süreleri yorumlanırken hata oranlarına da bakılmalıdır.'),
  ('Newell ve Rosenbloom\'un tanımladığı "alıştırmanın üs yasası"na göre bir beceride alıştırma arttıkça tepki süresi nasıl değişir?', 'Başta hızla, sonra giderek daha yavaş azalır', ['Her denemede aynı miktarda azalır', 'Bir süre sabit kalıp sonra birden sıfıra iner', 'Alıştırmayla birlikte giderek artar'], 'Performans gelişimi negatif hızlanan bir eğri izler; ilk denemelerdeki büyük kazanımlar zamanla küçülür ama tamamen durmaz.'),
  ('Dört gözlü bir ocakta düğmelerin yan yana dizildiği ve hangi düğmenin hangi gözü yaktığının kolayca anlaşılamadığı bir tasarımda sık hata yapılmasının nedeni hangi ilkeye aykırılıktır?', 'Uyarıcı-tepki uyumu', ['Sinyal saptama ölçütü', 'Kodlama özgüllüğü', 'Fitts yasası'], 'Denetimlerin uzamsal düzeni denetlenen öğelerin düzenine benzemediğinde zihinsel çeviri gerekir; Donald Norman bu tür kötü eşlemeleri gündelik tasarım hatalarının başında sayar.'),
  ('Masa üzerindeki dokuz küpe deneycinin dokunduğu sırayla dokunmayı gerektiren ve görsel-uzamsal kısa süreli belleği ölçen test hangisidir?', 'Corsi blok testi', ['Stroop testi', 'Wisconsin kart eşleme testi', 'Rakam dizisi testi'], 'Corsi blok testi, sözel rakam dizisi testinin görsel-uzamsal karşılığıdır; dokunulan blok dizisi uzatılarak kişinin hatırlayabildiği en uzun dizi bulunur.'),
  ('Kâğıt üzerindeki sayıları sırayla birleştiren A bölümü ile sayı ve harfleri dönüşümlü birleştiren (1-A-2-B...) B bölümünden oluşan, özellikle zihinsel esnekliği ölçen test hangisidir?', 'İz sürme testi', ['Corsi blok testi', 'Londra Kulesi testi', 'Benton yüz tanıma testi'], 'B bölümünün A bölümünden ne kadar uzun sürdüğü, iki dizi arasında geçiş yapma yeteneğini, yani bilişsel esnekliği yansıtır.'),
  ('Cahill ve McGaugh\'un çalışmalarında duygusal bir öykünün daha iyi hatırlanması, adrenalin sistemini baskılayan propranolol verilen katılımcılarda ortadan kalkmıştır. Bu bulgu duygusal anıların güçlenmesinde hangi yapının rolünü vurgular?', 'Amigdala ve stres hormonlarının pekiştirmeye etkisi', ['Beyinciğin denge ve eşgüdüm işlevlerinin katkısı', 'Görme korteksinin renkleri ayrıştırma işlevi', 'Omuriliğin refleks yayı ve kas gerimi'], 'Duygusal uyarılma amigdalanın hipokampustaki pekiştirmeyi güçlendirmesine yol açar; beta-adrenerjik sistemin engellenmesi bu avantajı ortadan kaldırır.'),
  ('Olumlu ruh hâlindeki kişilerin bir resimde bütünsel örüntülere, olumsuz ruh hâlindekilerin ise ayrıntılara daha çok dikkat etme eğilimi en iyi hangi genel sonucu destekler?', 'Duygu durumunun bilgi işleme biçimini etkileyebildiğini', ['Duyguların bilişle hiçbir ilişkisi olmadığını', 'Ruh hâlinin yalnızca bellek kapasitesini değiştirdiğini', 'Olumsuz duyguların her zaman algıyı tamamen engellediğini'], 'Duygu ile biliş birbirinden bağımsız sistemler değildir; ruh hâli dikkat kapsamını, işleme derinliğini ve strateji seçimini etkileyebilir.'),
  ('Sol tarafı felçli bir hastanın kolunu kıpırdatamadığı hâlde "Kolum gayet iyi, sadece şu an kaldırmak istemiyorum" demesi gibi, kendi bozukluğunun farkında olmama durumuna ne ad verilir?', 'Anozognozi', ['Afazi', 'Ataksi', 'Agrafi'], 'Anozognozi, özellikle sağ yarım küre hasarından sonra görülen ve hastanın felç ya da ihmal gibi açık bir sorunu inkâr etmesi ya da fark etmemesiyle belirgin bir durumdur.'),
  ('Birincil görme korteksinin iki yanlı hasarı sonucu kör olduğu hâlde körlüğünü inkâr eden ve gördüğünü sandığı şeyleri betimleyen hastadaki tablo hangisidir?', 'Anton sendromu', ['Bálint sendromu', 'Capgras sendromu', 'Korsakoff sendromu'], 'Anton sendromunda hasta kortikal körlüğünün farkında değildir ve görsel deneyimlerini uydurur; bu, farkındalığın duyusal işlemeden ayrışabildiğini gösterir.'),
  ('Nasırlı cisim hasarı ya da bölünmüş beyin ameliyatı sonrası bir elin kişinin isteğinden bağımsız hareket etmesi, örneğin bir elin düğmeleri iliklerken öbürünün açması hangi sendromdur?', 'Yabancı el sendromu', ['Hayalet uzuv sendromu', 'Kullanma davranışı', 'Bálint sendromu'], 'Yabancı el sendromunda kişi elinin amaçlı görünen hareketlerini kendisinin başlatmadığını hisseder; bu durum eylem denetimi ile sahiplik duygusunun beyindeki temellerini tartışmaya açar.'),
  ('1957\'de James Vicary\'nin bir sinemada filme "Patlamış mısır ye" ve "Coca-Cola iç" mesajlarını fark edilmeyecek kadar kısa sürelerle yerleştirip satışların arttığını iddia ettiği çalışma için hangisi doğrudur?', 'Vicary sonradan verilerin uydurma olduğunu kabul etmiş ve iddia hiçbir zaman doğrulanamamıştır', ['Çalışma pek çok kez tekrarlanmış ve satışların kesin olarak arttığı kanıtlanmıştır', 'Çalışma yalnızca hayvanlar üzerinde yapılmıştır', 'Mesajlar aslında çok büyük harflerle ve uzun süre gösterilmiştir'], 'Vicary\'nin iddiası eşik altı reklamcılık korkusunu yaymış, ancak kendisi 1962\'de çalışmanın yeterli veriye dayanmadığını kabul etmiştir; kontrollü deneyler böyle güçlü bir etki bulmamıştır.'),
  ('Sinir iletim hızını 1850\'de ilk kez ölçerek zihinsel süreçlerin zaman aldığını gösteren ve algıyı "bilinç dışı çıkarım" olarak tanımlayan Alman bilim insanı kimdir?', 'Hermann von Helmholtz', ['Wilhelm Wundt', 'Gustav Fechner', 'Ernst Weber'], 'Helmholtz, kurbağa sinirinde iletim hızının saniyede yalnızca onlarca metre olduğunu gösterdi; ayrıca algının, duyusal veriden öğrenilmiş bilgiyle otomatik çıkarım yapılarak oluştuğunu savundu.'),
  ('William James 1890\'da yayımladığı "Psikolojinin İlkeleri"nde belleği "birincil" ve "ikincil" bellek olarak ikiye ayırmıştır. Bu ayrım günümüzdeki hangi ayrımın öncüsü sayılır?', 'Kısa süreli ve uzun süreli bellek', ['Örtük ve açık bellek', 'Anısal ve anlamsal bellek', 'Duyusal ve işlemsel bellek'], 'James\'e göre birincil bellek şu an bilinçte tutulan bilgiyi, ikincil bellek ise bilinçten çıktıktan sonra yeniden çağrılması gereken bilgiyi kapsar; bu, iki depolu modellerin habercisidir.'),
  ('Wilder Penfield\'ın epilepsi ameliyatları sırasında hastaların şakak loblarını elektrikle uyardığında bazı hastaların bildirdiği deneyim hangisidir?', 'Canlı müzik, ses ya da sahne parçaları yaşamak', ['Uyarılan bölgede hiçbir şey hissetmemek', 'Uyarıldıkları anda bütün yaşamlarını kusursuz hatırlamak', 'Görme duyusunu kalıcı olarak yitirmek'], 'Penfield\'ın bulguları belleğin beyinde yerelleşmiş olabileceği fikrini güçlendirmiş, ancak bu deneyimlerin gerçek anılar mı yoksa yeniden kurgulanmış parçalar mı olduğu tartışılmıştır.'),
  ('Paul Broca\'nın 1861\'de konuşma yetisini kaybettiği için "Tan" lakabıyla bilinen hastasının ölümünden sonra yaptığı inceleme hangi sonuca katkı sağlamıştır?', 'Konuşma üretiminin sol ön lobdaki belirli bir bölgeye bağlı olduğu', ['Konuşmanın beynin her iki yarım küresine eşit dağıldığı', 'Dilin yalnızca beyincik tarafından denetlendiği', 'Konuşma kaybının hiçbir zaman beyin hasarından kaynaklanmadığı'], 'Hastanın sol alt ön kıvrımında bulunan hasar, işlevlerin beyinde yerelleştiği görüşüne güçlü bir kanıt oldu ve bu bölge Broca alanı olarak anıldı.'),
  ('Tversky ve Kahneman\'a göre bir olayın olasılığını, örneklerin zihne ne kadar kolay gelişine bakarak yargılama eğilimine ne ad verilir?', 'Ulaşılabilirlik sezgisi', ['Temsil edilebilirlik sezgisi', 'Çapalama ve ayarlama', 'Doğrulama yanlılığı'], 'Köpekbalığı saldırılarının haberlerde çok yer tutması, bu olayın gerçekte olduğundan sık sanılmasına yol açar; çünkü kolay akla gelen örnekler olasılığı şişirir.'),
  ('Bir kişiyi tanımlayan özelliklerin bir meslek kalıp yargısına benzerliğine bakıp temel oranları göz ardı etme, hangi sezgiyle ilgilidir?', 'Temsil edilebilirlik', ['Ulaşılabilirlik', 'Duygu sezgisi', 'Tanıma sezgisi'], 'Temsil edilebilirlik sezgisinde olasılık, örneğin bir kalıp yargıya ne kadar benzediğine göre belirlenir ve temel oran bilgisi ihmal edilir.'),
  ('Bir şehirde taksilerin %85\'i yeşil, %15\'i mavidir. Tanık, kazaya karışan taksiyi mavi görmüş ve %80 güvenilirdir. Temel oran dikkate alınmazsa en sık yapılan yanılgı nedir?', 'Kazaya karışan taksinin mavi olma olasılığını %80 sanmak', ['Olasılığı tanığın güvenilmezliği nedeniyle sıfıra yakın saymak', 'Yeşil taksinin kesinlikle karışmış olduğuna inanmak', 'Tanığı hiç güvenilmez kabul edip ifadesini yok saymak'], 'Bayes hesabına göre mavi olma olasılığı yaklaşık %41\'dir; insanlar tanığın doğruluk oranına odaklanıp %15\'lik temel oranı yok sayar.'),
  ('Basketbolda art arda basket atan oyuncunun bir sonraki atışı da sokacağına inanılmasına, ancak verilerde bunun desteklenmemesine ne ad verilir?', 'Sıcak el yanılgısı', ['Kumarbaz yanılgısı', 'Hale etkisi', 'Çerçeveleme etkisi'], 'Gilovich, Vallone ve Tversky\'nin 1985 incelemesi, ardışık atışların bağımsızlığını gösterip "sıcak el" inancını rastgelelik algısına bağladı.'),
  ('Gigerenzer\'in "hızlı ve tutumlu sezgiseller" yaklaşımında, tanıdığı seçeneği tanımadığına tercih eden basit kural hangisidir?', 'Tanıma sezgisi', ['Çapalama', 'Yeterlilik ölçütü', 'Çıkarma kuralı'], 'Örneğin hangi şehrin daha kalabalık olduğu sorulduğunda, yalnız birini tanıyan kişi onu seçer ve çoğu kez doğru bulur.'),
  ('Gigerenzer\'e göre olasılık bilgisi "yüzde" yerine "doğal sıklık" biçiminde verildiğinde ne beklenir?', 'Bayes tipi akıl yürütme belirgin biçimde iyileşir', ['Temel oran ihmali artar', 'Sezgiler büsbütün devre dışı kalır', 'Hiçbir değişiklik gözlenmez'], '"1000 kişiden 10\'u hasta" gibi sıklık biçimi, bilgiyi zihinsel işlemeye uygun kılar ve hekimlerin bile hatalarını azaltır.'),
  ('Bir hastalığın görülme sıklığı 1000\'de 10, testin duyarlılığı %90 ve yanlış pozitif oranı %9\'dur. Pozitif çıkan bir kişinin gerçekten hasta olma olasılığına en yakın değer hangisidir?', 'Yaklaşık %9', ['Yaklaşık %90', 'Yaklaşık %50', 'Yaklaşık %99'], '1000 kişiden 10 hasta, 9\'u pozitif çıkar; 990 sağlıklıdan yaklaşık 89\'u pozitif çıkar. Doğru pozitif oranı 9/98, yani yaklaşık %9\'dur.'),
  ('Norman ve Shallice\'in denetleyici dikkat sistemi modelinde, alışılmış davranışları yöneten düşük düzeyli düzenek hangi adla anılır?', 'Çekişme zamanlama', ['Merkezi yürütücü ve onun dikkat kaynaklarını paylaştırması', 'Fonolojik döngü ve içten prova düzeneği', 'Kısa süreli depo ve süre sınırlı tutma işlevi'], 'Rutin eylem şemalarının çakışmasını çözen çekişme zamanlama, yeni ya da tehlikeli durumlarda denetleyici dikkat sistemi tarafından geçersiz kılınabilir.'),
  ('Çay yapmak isterken kişinin fincana şeker yerine kahve koyması gibi hatalar, eylem hatası sınıflamasında hangisine girer?', 'Eylem kayması (slip)', ['Kural temelli yanlış (mistake)', 'Bilgi eksikliği', 'Amnezi'], 'Kayma, niyetin doğru ancak uygulamanın yanlış olduğu hatadır; dikkat kontrolü zayıfladığında alışkanlık eylemleri araya girer.'),
  ('Bir sürücü işe giderken market uğraması gerektiğini unutup her gün kullandığı yola sapıyor. Bu durum hangi bilişsel kontrol başarısızlığıdır?', 'Alışkanlık yakalaması', ['Kısa süreli bellek yitimi', 'Sözel akıcılık bozukluğu', 'Hemianopi'], 'Otomatik rutin, niyet bellekte yeterince güçlü tutulmadığında denetimi ele geçirir; Norman\'ın "yakalama hatası" budur.'),
  ('Simon etkisi gözlenen bir görevde, sağda belirebilen bir uyarıcıya sağ tuşla yanıt vermek, uyarıcı sol tarafta belirdiğinde sağ tuşla yanıt vermekten neden daha hızlıdır?', 'Uyarıcının konumunun, görevle ilgisiz olsa da yanıtı etkilemesi', ['Sağ elin sol elden her durumda daha güçlü olması', 'Uyarıcının renginin dikkati tümüyle dağıtması', 'Katılımcının görevi yanlış anlaması ve rastgele yanıt vermesi'], 'Simon etkisi, uzamsal uyumun bile uyarıcının konumu görevle ilgisiz olduğunda yanıtı hızlandırmasını, uyumsuzluğun ise yavaşlatmasını anlatır.'),
  ('Katılımcıdan kart dizilerini renk, şekil ya da sayı kuralına göre sınıflaması istenip kuralın haber verilmeden değiştirildiği test hangisidir?', 'Wisconsin Kart Sınıflama Testi', ['Beck Depresyon Envanteri ve benzeri öz bildirim ölçekleri', 'Raven İlerleyici Matrisler Testi', 'Rorschach mürekkep lekesi testi ve yorumlama yöntemleri'], 'Test, bilişsel esnekliği ve kural değişimine uyumu ölçer; önyüz (frontal) hasarında sıkça aynı kuralda ısrar görülür.'),
  ('Rey-Osterrieth Karmaşık Figür Testi\'ndeki asıl değerlendirme hangi yetileri kapsar?', 'Görsel-uzamsal kopyalama ve görsel belleği', ['Yalnızca sözel akıcılığı ve sözcük üretimini', 'Duygusal tepkiselliği ve kaygı düzeyini', 'Müzikal yeteneği ve ritim algısını'], 'Katılımcı karmaşık bir figürü önce kopyalar, sonra bellekten çizer; hem planlama hem görsel bellek puanlanır.'),
  ('Tower of London ve Hanoi Kuleleri gibi disk ya da bilye taşıma görevleri en çok hangi yetiyi sınar?', 'Planlama ve ileriyi düşünme', ['Renk ayırt etme', 'Ses yüksekliği ayırt etme', 'Tat algısı'], 'Bu görevler hedefe ulaşmak için ara hedefler kurmayı ve hamleleri önceden tasarlamayı gerektirir; önyüz hasarında bozulabilir.'),
  ('Corsi blok dokunma testi, çalışma belleğinin hangi bileşenini ölçmede kullanılır?', 'Görsel-uzamsal çizim defteri', ['Fonolojik döngü', 'Merkezi yürütücü', 'Bölümsel arabellek'], 'Katılımcı, deneycinin dokunduğu blokların sırasını yineler; görsel-uzamsal alan sözel deney çeşitlerinden farklı olarak bu yolla sınanır.'),
  ('Paralel çizgilerin kısa çapraz çizgilerle kesildiğinde birbirine eğik görünmesine yol açan yanılsama hangisidir?', 'Zöllner yanılsaması', ['Ebbinghaus yanılsaması', 'Ames odası', 'Delboeuf yanılsaması'], 'Zöllner\'in 1860 dolayında bulduğu yanılsama, çapraz çizgilerin yön algısını yanlı biçimde etkilediğini gösterir.'),
  ('Bir tren yolunun uzakta birleşen çizgileri arasındaki iki eşit çubuktan üstteki çubuğun daha uzun görünmesi hangi yanılsama ve hangi açıklamayla bilinir?', 'Ponzo yanılsaması; doğrusal perspektif ipuçları', ['Müller-Lyer yanılsaması; sarkaç hareketi etkisi', 'Zöllner yanılsaması; renk değişmezliği ilkesi', 'Phi olgusu; görünür hareket algısı'], 'Birleşen çizgiler derinlik ipucudur; uzağa ait sanılan çubuk, retinadaki boyutu eşit olsa da daha büyük algılanır.'),
  ('Boş bir alanda hiç çizilmemiş bir üçgenin kenarlarını görme yanılsaması hangi adı taşır?', 'Kanizsa üçgeni', ['Penrose üçgeni', 'Necker küpü', 'Rubin vazosu'], 'Kanizsa\'nın öznel konturları, görsel sistemin eksik bilgiyi tamamlayarak kapalı bir şekil algıladığını gösterir.'),
  ('Çizgi film izleyicisi, birbirini izleyen durağan karelerin akıcı bir hareket gibi algılanmasının nedeni olarak neyi ileri sürebilir?', 'Görünür hareket olgusunu', ['Duyusal uyum yanılsamasını', 'Sinestezi', 'Kör görmeyi'], 'Ardışık, birbirine yakın uyarıcıların beyin tarafından hareket olarak yorumlanması, sinemanın psikolojik temelidir.'),
  ('Bir çocuk karanlık odada yalnız tek bir sabit ışık noktasına bakarken ışığın kendiliğinden oynadığını görüyor. Bu olgu nedir?', 'Otokinetik etki', ['Phi olgusu', 'Hareket art-etkisi', 'Ay yanılsaması'], 'Referanssız ortamda küçük göz hareketleri ışığın hareket ediyormuş izlenimi verir; çerçeve eksikliği yanılsamayı güçlendirir.'),
  ('Fechner\'in yasası, duyum şiddeti ile uyarıcı şiddeti arasındaki ilişkiyi hangi biçimde ifade eder?', 'Duyum, uyarıcı şiddetinin logaritmasıyla orantılıdır', ['Duyum, uyarıcı şiddetiyle doğru orantılıdır', 'Duyum, uyarıcının karesiyle orantılıdır', 'Duyum uyarıcıdan bağımsızdır'], 'Weber\'in orantı yasasından türetilen Fechner yasası, uyarıcı katlanarak artarken duyumun doğrusal arttığını söyler.'),
  ('Psikofizikte "sınır yöntemi" ile eşik ölçerken uyarıcı şiddeti nasıl değiştirilir?', 'Aşağı ya da yukarı adım adım değiştirilir; katılımcı fark edince bildirir', ['Uyarıcı rastgele sırayla yalnız bir kez sunulur', 'Uyarıcı sabit tutulur ve yalnızca katılımcının tepkisi değiştirilir', 'Yalnızca çok güçlü uyarıcılar kullanılır ve eşik ölçülmez'], 'Azalan ve artan serilerin ortalaması mutlak eşiğin tahminini verir; beklenti ve alışma hataları yöntemin zayıf yönleridir.'),
  ('Fark edilebilen en küçük fark (JND) kavramının psikofizikteki anlamı hangisidir?', 'İki uyarıcı arasında yarı denemede ayırt edilen en küçük şiddet farkı', ['Uyarıcının fark edilebildiği en kısa süre', 'Uyarıcının tavan şiddetine ulaştığı nokta', 'Duyumun tümüyle kaybolduğu en düşük şiddet'], 'JND, Weber\'in çalışmasından beri fark eşiğinin ölçüsüdür ve uyarıcı şiddetiyle orantılı olarak artar.'),
  ('Duyusal uyum (adaptasyon) örneği hangisidir?', 'Kötü kokulu odaya girdikten bir süre sonra kokunun hissedilmemesi', ['Parlak ışığa bakınca gözün bir süre kamaşması', 'Soğuk suyun ilk anda ağrı yapması', 'Işığın prizmada renklere ayrılması'], 'Sürekli aynı uyarıcıya maruz kalındığında duyu alıcılarının tepkisi azalır; bu, değişimleri öne çıkaran bir tasarruf düzeneğidir.'),
  ('İki kulağa ulaşan sesler arasındaki çok kısa zaman farkı, sesin hangi özelliğinin algılanmasında kullanılır?', 'Yönü', ['Perdesi', 'Tınısı', 'Yüksekliği'], 'Kulaklar arası zaman farkı, özellikle düşük frekanslı seslerde konumu belirlemede en önemli ipuçlarından biridir.'),
  ('Yüksek frekanslı seslerin yerelleştirilmesinde baş etkisiyle oluşan hangi fark daha çok kullanılır?', 'Kulaklar arası şiddet farkı', ['Kulaklar arası renk farkı', 'Yankı gecikmesi', 'Perde yüksekliği'], 'Baş, yüksek frekanslı sesi gölgeler; uzak kulakta ses daha zayıf kalır ve bu şiddet farkı konum ipucudur.'),
  ('Ses dalgasının frekansı yükseldikçe algılanan hangi nitelik yükselir?', 'Perde', ['Şiddet', 'Tını', 'Yankı'], 'Frekans fiziksel boyuttur; algıdaki karşılığı perdedir. Şiddet genlikle, tını ise dalga biçimiyle ilgilidir.'),
  ('Aynı notayı çalan kemanla flütün farklı duyulmasının nedeni nedir?', 'Harmonik yapıdan doğan tını farkı', ['Temel frekans farkı ile perde farkının bulunması', 'Genlik farkı yüzünden sesin şiddetinin değişmesi', 'Ses hızının çalgılar arasında farklı olması'], 'Tını, temel frekansın yanı sıra eşlik eden harmoniklerin dağılımıyla belirlenir ve çalgıların kimliğini sağlar.'),
  ('Serbest hatırlama deneylerinde listenin başındaki sözcüklerin iyi hatırlanmasına ne ad verilir?', 'Önce gelme (birincillik) etkisi', ['Yeni gelme (sonralık) etkisi', 'Von Restorff etkisi', 'Test etkisi'], 'Başlardaki sözcükler daha çok prova edilip uzun süreli belleğe aktarıldığı için iyi hatırlanır.'),
  ('Serbest hatırlamada listenin sonundaki sözcüklerin iyi hatırlanmasına yol açan düzenek hangisidir?', 'Kısa süreli bellekteki içeriğin hâlâ erişilebilir olması', ['Duygusal yüklü sözcüklerin seçilmesi', 'Derin anlamsal işlemenin uygulanması', 'Anlamlı gruplara ayırarak kodlama yapılması'], 'Sondaki sözcükler hâlâ kısa süreli bellekte olduğundan hemen sonrasında ilk sırada hatırlanır; araya dikkat dağıtıcı görev girerse etki kaybolur.'),
  ('Von Restorff etkisi (yalıtım etkisi) nedir?', 'Diğerlerinden belirgin farklı öğenin daha iyi hatırlanması', ['Listenin son öğesinin daha iyi hatırlanması', 'Listenin ilk öğesinin unutulması', 'Bütün öğelerin eşit düzeyde hatırlanması'], 'Hedef öğenin farklılığı dikkat çeker, ayırt edilebilirlik kodlamayı güçlendirir; örnek, siyah sözcükler arasındaki kırmızı sözcüktür.'),
  ('Bir öğretmen, ders sonunda öğrencilerin ilk ve son anlatılan kavramları daha iyi hatırladığını fark ediyor. Ortada kalan kavramlar için ne yapması önerilir?', 'Önemli kavramları başa ve sona koymak ya da ortayı etkinlikle güçlendirmek', ['Dersi baştan sona kesintisiz tek bir anlatım olarak sürdürmek', 'Kavram sayısını artırıp tekrar yapmaktan kaçınmak', 'Sonuç bölümünü hiç açıklamadan dersi bitirmek'], 'Sıra konum eğrisi öğrencinin başlangıç ve son bölümlerde daha iyi öğrendiğini gösterir; ortadaki içerik etkinlik ve tekrarla desteklenmelidir.'),
  ('Hece üçlülerinin zamanla unutulmasında, sonraki çalışmalarda öne çıkan açıklama hangisidir?', 'Önceki deneme heceleriyle girişim', ['Ses yüksekliğinin zamanla artmasına bağlı yorgunluk', 'Işık şiddetinin deneme boyunca değişmesi', 'Katılımcıların uykusuz olması ve dikkatlerinin dağılması'], 'Keppel ve Underwood, ilk denemelerde unutmanın az olduğunu, sonraki denemelerde önceki hecelerin girişim yaptığını gösterdi.'),
  ('Sternberg\'in 1966 bellek taraması görevinde ayrılabilen en önemli bulgu hangisiydi?', 'Tepki süresi bellek kümesi büyüdükçe doğrusal biçimde artar', ['Tepki süresi kümenin büyüklüğünden bağımsızdır', 'Tepki süresi küme büyüdükçe azalır', 'Küme tümüyle taranmadan yanıt hep rastgele verilir'], 'Her ek öğe tepki süresine yaklaşık 38 ms ekledi; bu, ardışık ve sınırlayıcı olmayan bir tarama düşüncesini destekledi.'),
  ('Çalışma belleğinde sözel bilgiyi tutan fonolojik döngü içerisinde, bilgiyi geçici olarak depolayan bileşen hangi adla anılır?', 'Fonolojik depo', ['Çizim defteri', 'Bölümsel arabellek', 'Duyusal kayıt'], 'Fonolojik depo, kendi kendine tekrarla (artikülasyon süreci) kısa süre canlı tutulan işitsel iz içerir.'),
  ('Sesli olarak sunulan ve görsel sunulan harflerin benzer sesli oluşunun, fonolojik benzerlik etkisi nedeniyle hatırlamayı güçleştirmesi hangi bellek bileşeninin göstergesidir?', 'Fonolojik döngü', ['Görsel çizim defteri', 'Duyusal bellek', 'Anlamsal bellek'], 'B, D, G, T gibi benzer sesli harflerin dizisi, benzer sesli oldukları için sıralı hatırlamada karışma yarattığından fonolojik kodlamaya işaret eder.'),
  ('Daneman ve Carpenter\'ın 1980 okuma aralığı testi çalışma belleğinde neyi ölçer?', 'Aynı anda işleme ve depolama kapasitesini', ['Uzun süreli bellek yitimini ve unutma hızını', 'Duyusal belleğin tutma süresini ve ikonik izin ömrünü', 'Renk ayrımı yeteneğini ve görsel keskinliği'], 'Katılımcı cümle okurken her cümlenin son sözcüğünü aklında tutar; hatırlanan sözcük sayısı okuma anlama ile ilişkilidir.'),
  ('Kişinin "Kahve nasıl demlenir?" bilgisini söz ile ifade edebilmesi hangi bellek türündendir?', 'Bildirimsel (açık) bellek', ['Koşullanma belleği', 'Duyusal bellek', 'Beceri belleği'], 'Neyi bildiğini sözle ifade edebilme bildirimsel belleğin ayırıcı özelliğidir; bu bellek anısal ve anlamsal olarak ikiye ayrılır.'),
  ('Sürücü kursunda öğrenilen vites değiştirme becerisi hangi bellek türünde saklanır?', 'Yöntemsel (işlemsel) bellek', ['Anısal bellek', 'Anlamsal bellek', 'Duyusal bellek'], 'Beceriler ve alışkanlıklar, bilinçli anımsama gerektirmeyen işlemsel bellek sistemlerinde, büyük oranda beyincik ve bazal gangliyonlarla ilişkilidir.'),
  ('Bir hasta, yüz fotoğraflarını daha önce görmediğini söylerken "tanıdık" bulduğu yüzleri daha hızlı işleyebiliyor. Bu bulgu hangi kavramın örneğidir?', 'Örtük bellek', ['Açık bellek', 'Duyusal bellek', 'Çalışma belleği'], 'Kişi önceki karşılaşmayı bilinçli hatırlamasa da önceki deneyim işlemeyi kolaylaştırır; örtük belleğin belirtisidir.'),
  ('Parça tamamlama görevinde "k_l_m" kısmını önceden gördüğü "kalem" sözcüğüyle tamamlayan kişinin örtük belleği hangi bellek göstergesidir?', 'Tekrarlı hazırlama', ['Hale etkisi', 'Çapalama', 'Kaynak izleme'], 'Daha önce görülen sözcük, kişi hatırlamasa bile tamamlama olasılığını artırır; hazırlama örtük bellek göstergesidir.'),
  ('Craik ve Lockhart\'ın 1972 işleme düzeyleri çerçevesine göre bilginin ne kadar kalıcı hatırlanacağını en çok ne belirler?', 'İşlemenin derinliği', ['Bilginin sunulduğu saat', 'Uyaran rengi', 'Katılımcının yaşı'], 'Anlamsal (derin) işleme, biçimsel ya da sesli (yüzeysel) işlemeye göre daha güçlü ve kalıcı bellek izi bırakır.'),
  ('Bilginin kişinin kendisiyle ilişkilendirilerek kodlanmasının bellekte yarattığı yarara ne ad verilir?', 'Öz-referans etkisi', ['Von Restorff etkisi', 'Ketlenme etkisi', 'Gecikmeli yanıt etkisi'], 'Rogers ve arkadaşlarının 1977 çalışmasında "Bu sözcük seni tanımlıyor mu?" sorusu en iyi hatırlamayı sağladı.'),
  ('Godden ve Baddeley\'in 1975 deneyinde, dalgıçların sözcükleri öğrendikleri ortamla aynı ortamda hatırlaması neden daha iyiydi?', 'Bağlam ipuçlarının geri getirmeyi kolaylaştırması', ['Su altında odaklanmanın daha kolay olması', 'Sudaki sözcüklerin daha kısa olması', 'Karada dikkatin dağılması'], 'Öğrenme ve hatırlama ortamı eşleştiğinde bağlam, bellek izine bağlanan ipucu işlevi görür; ortamlar farklıysa performans düşer.'),
  ('Eich ve Metcalfe\'ın çalışmalarında sunulan ruh hâline bağlı bellek bulgusu neyi gösterir?', 'Öğrenme ve hatırlamadaki ruh hâlinin örtüşmesinin yarar sağlaması', ['Mutlu olmanın belleği tümüyle bozması', 'Üzüntünün her koşulda hatırlamayı artırması', 'Ruh hâlinin belleğe hiçbir etkisi olmaması'], 'Aynı duygusal durumda öğrenip hatırlamak, durumun ipucu olarak çalışması nedeniyle performansı artırır.'),
  ('Ruh hâli uyumlu bellek ile ruh hâline bağlı bellek arasındaki fark nedir?', 'Uyumlu bellekte içerik ruh hâline uyar; bağlı bellekte iki hâl eşleşir', ['İkisi aynı olgunun farklı adlarıdır', 'Bağlı bellek yalnız hayvanlarda, uyumlu bellek yalnız insanda görülür', 'Uyumlu bellek yalnızca uyku sırasında ortaya çıkar'], 'Bower\'ın çalışmaları, mutlu kişilerin olumlu içeriği, üzgün kişilerin olumsuz içeriği daha kolay hatırladığını gösterdi.'),
  ('Jenkins ve Dallenbach\'ın 1924 deneyinde uykuda geçen sürede unutmanın daha az olması neyi gösterir?', 'Unutmanın bir kısmının yeni girdilerin girişimine bağlı olduğunu', ['Bellek izinin yalnızca zamanla bozulduğunu', 'Uykunun öğrenilen bilgileri tümden sildiğini', 'Uyanıkken yeni bilginin hiç öğrenilemediğini'], 'Uyku koşulunda yeni girişim azaldığından unutma azaldı; bu, yalnız zamanla bozulma açıklamasına karşı kanıt sayılır.'),
  ('Yeni öğrenilen bilginin önceki bilgiyi hatırlamayı bozmasına ne ad verilir?', 'Geriye dönük girişim (retroaktif engelleme)', ['İleriye dönük girişim (proaktif engelleme)', 'Kaynak yanılgısı (yanlış atıf)', 'Hazırlama etkisi (tekrarlı hazırlama)'], 'Yeni bilgi eski bilginin geri getirilmesini engelleyebilir; örneğin yeni telefon numarası eskisini hatırlamayı zorlaştırır.'),
  ('"Dil ucunda olma" yaşantısı hangi bellek sorununun örneğidir?', 'Bilgiye ulaşmada geçici başarısızlık', ['Kaynağı yanlış belirleme ve yanlış atıf sorunu', 'Yalnız yaşa bağlı geri dönüşsüz bellek kaybı', 'Gerçekte yaşanmayan olayı hatırlama sorunu'], 'Kişi sözcüğün ilk harfini ya da hece sayısını bilebilir ama tam sözcüğü çıkaramaz; bu, bilginin var olup erişilemediğini gösterir.'),
  ('Anderson ve Green\'in "düşünme/düşünmeme" görevinde katılımcılar çiftlerin ikinci sözcüğünü bilinçli olarak düşünmemeyi denedikçe neye ulaşırlar?', 'Bastırılan öğelerin daha az hatırlanmasına', ['Tamamen bilinçsiz biçimde unutulmalarına', 'Bastırılan öğelerin daha çok hatırlanmasına', 'Hiçbir bellek değişikliğine uğramamalarına'], 'Bastırma, geri getirme düzeyini düşürür; bu bulgu istemli unutmanın bilişsel bir temeli olabileceğini gösterir.'),
  ('Tanıklık araştırmalarında kendi ırkından olmayan yüzleri tanımanın daha güç olmasına ne ad verilir?', 'Çapraz ırk etkisi', ['Hale etkisi', 'Silah odağı', 'Çerçeveleme etkisi'], 'Kişiler kendi ırklarından yüzleri daha doğru tanırlar; bu, uzmanlık ve ayırt edici özelliklere odaklanma farkıyla açıklanır.'),
  ('Wells\'in tanıklık araştırmalarında "tahminci değişken" (estimator variable) ile "sistem değişkeni" arasındaki fark nedir?', 'Tahminciler sistemin denetleyemediği, sistem değişkenleri denetleyebildiği etkenlerdir', ['Tahminciler ölçülemeyen, sistem değişkenleri ölçülebilen etkenlerdir', 'Sistem değişkenleri yalnızca çocuk tanıklara ilişkindir', 'İkisi de aynı etkenleri anlatan eş anlamlı terimlerdir'], 'Olay aydınlığı ve tanığın yaşı tahmincidir; sıralama yönergesi ve sunum biçimi sistem değişkenidir.'),
  ('Kimlik sıralamalarında kişilerin birer birer gösterilmesi, aynı anda gösterilmesine göre hangi yararı sağlar?', 'Görece yargıyı azaltıp yanlış tanımayı düşürme eğilimi', ['Doğru tanımayı her koşulda belirgin biçimde artırma', 'Tanığın gereksizleşmesi ve ifadenin hiç alınmaması', 'Failin her seferinde mutlaka bulunması'], 'Sıralı sunumda tanık her kişiyi mutlak ölçütle yargılar; bu, görece yargıdan doğan yanlış tanımaları azaltabilir.'),
  ('Bir tanık, soruşturmacıdan fotoğraf gösterimi sonrası "doğru kişiyi seçtiniz" geri bildirimini alıyor. Sonradan tanığın tanıma güveni neden artabilir?', 'Onay geri bildirimi etkisi', ['Tepki yanlılığı', 'Çapraz ırk etkisi', 'Sondaki öğe etkisi'], 'Wells ve Bradfield\'ın 1998 çalışması, geri bildirimin tanığın güvenini, doğruluk artmadan şişirdiğini gösterdi.'),
  ('Bir tanığın olay anındaki aşırı stresi hatırlama doğruluğunu nasıl etkileyebilir?', 'Merkez ayrıntıları koruyup çevresel ayrıntıları daraltabilir', ['Bütün ayrıntıların ayrıntısını kesin biçimde artırır', 'Yalnızca renklerin hatırlanmasını bozar, öbürlerini etkilemez', 'Hatırlamayı hiçbir biçimde etkilemez'], 'Yüksek uyarılma dikkati tehditle ilgili merkez ayrıntılara yöneltir; bu daralma silah odağı gibi etkiler doğurabilir.'),
  ('Bir kişinin olay sonrası "Zaten böyle olacağını biliyordum" demesi hangi bilişsel yanlılıkla ilişkilidir?', 'Geriye bakış yanlılığı', ['İleriye dönük girişim', 'Kaynak izleme', 'Silah odağı'], 'Sonucu öğrendikten sonra olayın önceden öngörülebilir olduğuna dair inanç artar; Fischhoff bu olguyu 1975\'te "her şey belliydi" etkisi olarak sundu.'),
  ('Bartlett\'in "Hayaletlerin Savaşı" çalışmasında hikâyenin yinelemelerde değişmesi, belleğin hangi niteliğini gösterir?', 'Belleğin şemalara göre yeniden yapılandırılması', ['Belleğin fotoğraf gibi eksiksiz olması', 'Anıların hiçbir zaman değişmeyen kayıtlar olması', 'Belleğin yalnızca sözlerle depolanması'], 'Katılımcılar yabancı unsurları kendi kültürel şemalarına uygun biçimde kısaltıp yorumladı.'),
  ('Bir öğrenci, daha önce okuduğu bir hikâyedeki ayrıntıyı unutup yerine mantıklı gelen yeni bir ayrıntı anlatıyor. Bu durum hangi bellek sürecini örnekler?', 'Yeniden yapılandırma', ['Hazırlama', 'Duyusal bellek', 'Dikkat kırpması'], 'Anımsama, kayıtlı izin tekrarı değil, mevcut bilgi ve şemalarla yeniden kurulmasıdır.'),
  ('Schacter\'ın "belleğin yedi günahı" sınıflamasında "kalıcılık" hatası neyi ifade eder?', 'İstenmeyen anıların zihne ısrarla gelmesi', ['Kaynağın karıştırılması ve yanlış kaynağa yüklenmesi', 'Zamanla bilginin hiç bilinmeden silinmesi', 'Önerilere kolayca açık olma durumu'], 'Travmatik anılar gibi istenmeyen içeriğin tekrar tekrar zihne dolması, bellekte kalıcılık hatasının örneğidir.'),
  ('Yeni anılar edinemeyen ancak eski anılarını koruyan hastada hangi yitim vardır?', 'Anterograd amnezi', ['Retrograd amnezi', 'Prosopagnozi', 'Disleksi'], 'Anterograd amnezide hastalıktan sonra yeni olaylar kalıcı belleğe aktarılamaz; hipokampus hasarı tipik nedendir.'),
  ('Anımsama sırasında yeni anıların oluşamadığı anterograd amnezili bir hastada hangi bellek hâlâ işlev görebilir?', 'İşlemsel (beceri) bellek', ['Anısal bellek', 'Çalışma belleğinin bütün işlevleri', 'Duygusal bellek de dâhil bütün bildirimsel bellek'], 'Beceri öğrenmeleri hipokampustan bağımsız bellek sistemlerine dayandığı için korunabilir.'),
  ('Luchins\'in su kavanozları problemlerinde, katılımcıların önceden başarılı olmuş karmaşık bir formülü, daha basit bir çözüm mümkün olduğunda bile sürdürmesi neyi gösterir?', 'Zihinsel kurulum (Einstellung) etkisi', ['Ayrışık düşünme ve çok sayıda fikir üretme', 'Kuluçka etkisi ve bilinçdışı işleme', 'İçgörü ve ani kavrayış deneyimi'], 'Önceki çözüm yönteminin otomatikleşmesi, yeni ve daha verimli yolların fark edilmesini engeller.'),
  ('Bir problemi ana hedefin alt hedeflerine bölüp sırayla çözme, hangi stratejinin özelliğidir?', 'Alt hedefe ayırma', ['Tepe tırmanma', 'Deneme-yanılma', 'Görsel arama'], 'Karmaşık problemler daha yönetilebilir parçalara ayrıldığında çalışma belleği yükü azalır.'),
  ('Köhler\'in şempanze deneylerinde hayvanın bir kutuyu muz altına çekmesi ya da iki sopayı birleştirmesi hangi öğrenme biçimine örnektir?', 'İçgörüyle öğrenme', ['Klasik koşullanma', 'Gözlemle öğrenme', 'Alışma'], 'Köhler\'e göre şempanzeler sorunu yoklama süreci sonunda ani bir kavrayışla çözmüştür.'),
  ('Wallas\'a göre yaratıcı sürecin dört aşaması hangi sırayla gerçekleşir?', 'Hazırlık, kuluçka, aydınlanma, doğrulama', ['Kuluçka, hazırlık, doğrulama, aydınlanma', 'Doğrulama, hazırlık, kuluçka, aydınlanma', 'Aydınlanma, hazırlık, kuluçka, doğrulama'], 'Wallas\'ın 1926 modeli, bilinçli çalışmadan sonra bilinçdışı kuluçkayı ve ani fikir belirmesini ardından da sınamayı öngörür.'),
  ('Torrance Yaratıcı Düşünme Testleri\'nin ölçtüğü temel boyutlardan hangisi akıcılığı tanımlar?', 'Üretilen yanıt sayısı', ['Yanıtların nadirliği', 'Yanıtların ayrıntı düzeyi', 'Yanıtların doğruluğu'], 'Torrance akıcılık, esneklik, özgünlük ve ayrıntılandırmayı ölçer; akıcılık kısa sürede üretilen fikir sayısıdır.'),
  ('Duygu durumuyla ilgili bulgulara göre hafif olumlu bir ruh hâli yaratıcı problem çözmeyi nasıl etkileyebilir?', 'Esnekliği artırıp uzak çağrışımları kolaylaştırabilir', ['Bütün koşullarda yaratıcılığı düşürür', 'Yalnızca ezber gücünü artırıp esnekliği azaltır', 'Yaratıcı çözümlerle hiçbir ilişkisi yoktur'], 'Isen ve arkadaşlarının çalışmaları, olumlu duyguların kavramlar arası geniş çağrışımı kolaylaştırdığını gösterdi.'),
  ('Bir kişi, konser bileti için çok para verdiğinden hasta olduğu hâlde gitmeyi seçiyor. Bu davranış hangi bilişsel yanlılıktan kaynaklanır?', 'Batık maliyet yanılgısı', ['Hale etkisi', 'Dikkat körlüğü', 'Önce gelme etkisi'], 'Geri alınamaz geçmiş harcama, gelecekteki kararı etkilememesi gerekirken seçimi yönlendirir.'),
  ('Zaman indirimi araştırmalarında "hiperbolik indirgeme" neyi anlatır?', 'Yakın ödülün uzaktakine göre orantısız tercih edilmesi', ['Uzak ödülün her koşulda yakın ödüle tercih edilmesi', 'Para değerinin zaman içinde hiç değişmemesi', 'Ödüllere karşı tümüyle ilgisizlik'], 'Bugün 100 TL\'yi yarın 110 TL\'ye tercih eden kişi, bir yıl sonra 100 TL ile bir yıl ve bir gün sonra 110 TL arasında sonrakini seçebilir.'),
  ('Ultimatum oyununda önerenin adaletsiz bir pay teklif etmesi hâlinde yanıtlayıcıların genellikle ne yaptığı gözlenir?', 'Küçük bile olsa kazancı reddedip teklifi geri çevirmek', ['Her zaman ve istisnasız teklifi kabul etmek', 'Rastgele bir seçim yapmak', 'Karşı bir teklif ile oyunu uzatmak'], 'Bulgu, insanların yalnız parasal çıkarı değil adalet algısını da gözettiğini ve tam akılcı model varsayımlarına uymadığını gösterir.'),
  ('Kişinin parayı kaynağına göre (maaş, ikramiye gibi) ayrı hesaplara bölüp farklı harcamasına ne ad verilir?', 'Zihinsel muhasebe', ['Çapalama', 'Tanıma sezgisi', 'Geriye bakış yanlılığı'], 'Thaler\'in zihinsel muhasebesi, parayı birbirinin yerine geçmeyen kategorilerde değerlendirme eğilimidir.'),
  ('Yarbus\'un 1967\'de aynı resme bakan kişilerin göz hareketlerini farklı yönergelerle kaydetmesi hangi sonucu verdi?', 'Bakış izleri görevin amacına göre belirgin biçimde değişti', ['Bakış izleri her yönergede aynı kaldı', 'Gözler yalnız parlak bölgelere gitti', 'Gözler resmin merkezinden hiç ayrılmadı'], 'Yönergeye bağlı olarak bakılan bölgeler farklılaştı; bu, dikkatin yalnızca uyarıcıdan değil hedeflerden de yönlendirildiğini gösterir.'),
  ('Reber\'in yapay dilbilgisi deneylerinde katılımcılar kuralları söyleyemediği hâlde yeni dizilerin dilbilgisine uygunluğunu şansın üzerinde ayırt eder. Bu bulgu neyi gösterir?', 'Örtük öğrenmenin bilinçli kural bilgisi olmadan gerçekleşebildiğini', ['Açık öğrenmenin her koşulda zorunlu olduğunu', 'Kuralların doğuştan bilindiğini ve öğrenmenin gereksiz olduğunu', 'Bellek izlerinin birkaç saniyede silindiğini'], 'Katılımcılar örüntüyü görmeden edinir; sezgisel bilgi bilinçli bir kural ifadesi olmadan davranışı yönlendirebilir.'),
  ('Zipf yasasına göre bir dilde sözcüklerin kullanım sıklığı ile sıklık sıralaması arasında nasıl bir ilişki vardır?', 'En sık sözcük ikincinin yaklaşık iki katı sıklıktadır; sıklık sıraya ters orantılıdır', ['Sıklık, sözcüğün harf sayısıyla doğru orantılıdır', 'Bütün sözcükler hemen hemen eşit sıklıkta kullanılır', 'Sıklık, sıralama numarası büyüdükçe doğru orantılı olarak artar'], 'Birkaç sözcük çok sık, çok sayıda sözcük ise seyrek kullanılır; bu, sözcük tanıma araştırmalarında sıklık etkisinin arka planıdır.'),
  ('Sözcük sıklığı etkisi okuma araştırmalarında hangi bulguyla kendini gösterir?', 'Sık sözcüklere bakış süresinin seyrek sözcüklere göre kısa olması', ['Seyrek sözcüklerin sık olanlardan çok daha çabuk tanınması', 'Sözcük uzunluğunun hiçbir etkisinin olmaması', 'Sık sözcüklerin hiç fark edilmemesi'], 'Sık karşılaşılan sözcüklerin sözlüksel girdileri daha kolay etkinleşir; göz izleme çalışmalarında kısa fiksasyonlar gözlenir.'),
  ('Yazılı sözcüklerin sesletimini kurallara göre çözen, sözcük listesine başvurmayan okuma yoluna ne ad verilir?', 'Sesbilgisel (dolaylı) yol', ['Sözlüksel (doğrudan) yol', 'Anlamsal yol', 'Görsel yol'], 'Çift yollu modelde düzensiz sözcükler sözlüksel yolla, yeni ya da uydurma sözcükler sesbilgisel yolla okunur.'),
  ('Bir öğrenci "blip" gibi anlamsız ama okunabilen bir hece dizisini sorunsuz seslendirirken, "colonel" gibi bir sözcükte takılıyor. Bu durumda hangi okuma yolunun zayıf olması beklenir?', 'Sözlüksel yol', ['Sesbilgisel yol', 'Görsel-uzamsal çizim defteri', 'Duyusal bellek'], 'Anlamsız dizi sesbilgisel yolla çözülür; düzensiz sözcüğün doğru okunması ise sözlüksel yola bağlıdır.'),
  ('Cattell\'in sözcük üstünlük etkisi ve Reicher\'in 1969 deneyi hangi sonucu verdi?', 'Harfler tek başına sunulduğundan çok sözcük içindeyken daha doğru tanındı', ['Harf tanıma sözcük bağlamından etkilenmedi, sonuçlar aynıydı', 'Anlamsız harf dizilerinde en iyi tanıma görüldü', 'Anlamsız dizilerde en iyi sonuç alındı'], 'Sözcük bağlamı harf tanımayı kolaylaştırır; bu, yukarıdan aşağıya işlemenin kanıtı sayılır.'),
  ('Ned Block\'un ayrımına göre kişinin deneyimi bildirebilmesi ve davranışı yönlendirmesi için kullanabildiği bilince ne ad verilir?', 'Erişim bilinci', ['Fenomenal bilinç', 'Üst bilinç', 'Bilinçdışı'], 'Erişim bilinci bilgiyi akıl yürütme, konuşma ve eylem denetimi için kullanılabilir kılar; fenomenal bilinç ise "nasıl hissettirdiği"dir.'),
  ('Schachter ve Singer\'ın iki etmenli duygu kuramına göre duygunun oluşması için gerekenler nelerdir?', 'Fizyolojik uyarılma ve bu uyarılmaya bilişsel bir etiket verilmesi', ['Yalnız fizyolojik uyarılmanın bulunması ve etiket gerekmemesi', 'Yalnız yüz ifadesinin geri bildirimi', 'Yalnızca beyin görüntüleme bulguları'], 'Uyarılma belirsizse kişi bağlama bakarak duygu etiketi seçer; deneyde adrenalin alan kişilerin duyguları ortama göre değişti.'),
  ('Amigdalanın duygusal olarak yüklü olaylar için bellek pekiştirmeye etkisini en iyi hangi bulgu gösterir?', 'Amigdala hasarlı hastalarda duygusal olayların hatırlama avantajının kaybolması', ['Amigdalanın yalnız görme bilgisini işlediğinin görülmesi', 'Amigdala hasarında belleğin tümüyle yitirilmesi', 'Amigdalanın yalnız dil bilgisini işlediğinin görülmesi'], 'Duygusal olaylar normalde nötrlerden iyi hatırlanır; amigdala hasarında bu fark azalır.'),
  ('Salthouse\'un işlem hızı kuramına göre yaşla birlikte birçok bilişsel görevde ortak görülen gerilemenin temel nedeni nedir?', 'Bilişsel işlem hızının yavaşlaması', ['Kristalize bilginin kaybı', 'Duyusal belleğin tümüyle silinmesi', 'Sözcük dağarcığının daralması'], 'Yaşla birlikte basit işlemlerin yavaşlaması, bir görevin ardışık aşamalarını yetiştirmeyi zorlaştırarak genel performansı düşürür.'),
  ('Yaşlılarda, önceden bilinen bilgiyi (sözcük dağarcığı) kullanan görevlerdeki performansın genellikle korunmasına ne ad verilir?', 'Kristalize bilişsel yeti', ['Akışkan bilişsel yeti', 'Çalışma belleği', 'İşlem hızı'], 'Cattell\'in ayrımına göre kristalize yeti birikmiş bilgiyi, akışkan yeti ise yeni problemlerle başa çıkmayı yansıtır.'),
  ('Yaşlılarda ileriye dönük (prospektif) bellek görevleri, zaman temelli ipuçlarında olay temelli ipuçlarından neden daha zor olur?', 'Zaman temelli görevler öz başlatma ve izleme gerektirdiği için', ['Olay temelli görevlerin çok karmaşık olması nedeniyle', 'İpuçlarının yalnızca işitsel biçimde verilmesi nedeniyle', 'Yaşlıların zaman algısını tümüyle yitirmesi nedeniyle'], 'Olay temelli ipuçları ortamdan gelir ve hatırlatıcıdır; zaman temelli görevlerde ise kişi saati kendi izlemelidir.'),
  ('Kategori üyeliğini, kategorinin kayıtlı üyelerine benzerlikle belirleyen kuram hangisidir?', 'Örnek kuramı', ['Klasik özellik kuramı', 'Betik kuramı', 'Algılayıcı kuramı'], 'Örnek kuramında yeni bir nesne, belleğe kayıtlı tek tek örneklerle karşılaştırılarak sınıflandırılır; ortalama bir prototip tutulmaz.'),
  ('"Kamp ateşinden kaçırılması gereken eşyalar" gibi hedefe bağlı oluşan kategorilere ne ad verilir?', 'Ad hoc kategoriler', ['Taksonomik kategoriler', 'Doğal türler', 'Mantıksal kümeler'], 'Barsalou, bu kategorilerin duruma göre kurulup bellekten çağrıldığını göstermiştir.'),
  ('Shepard ve Metzler\'in zihinsel döndürme deneylerinde tepki süresi ile açısal fark arasındaki ilişki nasıldır?', 'Dönme açısı arttıkça tepki süresi doğrusal olarak artar', ['Açı arttıkça tepki süresi azalır ve hızlanır', 'Tepki süresi açıdan bağımsız, sabit kalır', 'Yalnızca 90 derecede süre uzar'], 'Bulgu, imgelerin gerçek nesnelerin döndürülmesine benzer analog bir süreçle işlendiğini düşündürür.'),
  ('Bir mimar, binanın yeni bir cephesini aklında canlandırıp döndürüyor. Bu zihinsel çalışma hangi bilişsel işlemle ilgilidir?', 'Görsel-uzamsal imgeleme', ['Fonolojik prova', 'Anlamsal hazırlama', 'Duyusal kaydetme'], 'Zihinsel imgeleme, bellekteki nesneleri görsel olarak yeniden oluşturmayı ve dönüştürmeyi sağlar.'),
  ('Kosslyn\'in imge tarama deneylerinde katılımcılar zihinsel haritada iki nokta arası uzaklık arttıkça nasıl yanıt verir?', 'Yanıt süresi uzaklıkla doğru orantılı artar', ['Yanıt süresi uzaklıkla azalır', 'Yanıt süresi uzaklıktan bağımsızdır', 'Katılımcılar hiç yanıt veremez'], 'İmge, gerçek uzaklıkları koruyan bir temsil gibi işlenir; bu, imgelerin uzamsal özellik taşıdığını gösterir.'),
  ('Meyer ve Schvaneveldt\'in sözcük karar görevinde "ekmek" sözcüğünden önce "tereyağı" gelince karar süresi nasıl değişir?', 'Kısalır', ['Uzar', 'Değişmez', 'Hata kaçınılmaz olur'], 'İlişkili sözcük anlamsal ağda yayılan etkinleştirme nedeniyle ilişkisiz bir sözcüğe göre daha hızlı tanınır.'),
  ('Hazırlama deneyinde hedef sözcük "doktor" iken hazırlayıcı olarak "hemşire" gösterilmesi neden tanımayı hızlandırır?', 'Anlamsal olarak ilişkili oldukları için', ['Aynı harfle başladıkları için', 'Hece sayıları eşit olduğu için', 'Aynı renkte yazıldıkları için'], 'İlişkili anlam alanları ağda yakın düğümlerdir; birinin işlenmesi diğerini önceden etkinleştirir.'),
  ('Fitts yasası hangi hareketin süresini öngörür?', 'Hedefe işaret etme hareketini, uzaklık ve genişliğe göre', ['Bellekte listeden sözcük aramayı ve bulma süresini', 'Renk adlandırma görevinde hata sayısını ve süresini', 'İki sesin ayırt edilme eşiğini ve şiddet farkını'], 'Hedef uzaklaştıkça ve küçüldükçe hareket süresi uzar; bilgisayar arayüzlerinde düğme boyutunu belirlemede kullanılır.'),
  ('Psikolojik refrakter dönem etkisi, iki ardışık görevde neyi gösterir?', 'İkinci uyarıcıya yanıtın, birinci görev sürerken gecikmesini', ['Dikkatin sınırsız bölünebildiğini ve gecikme olmadığını', 'Her iki uyarıcıya aynı hızla yanıt verilmesini', 'İkinci görevin birinciden çok daha hızlı yapılmasını'], 'İlk görevin yanıt seçme aşaması darboğaz oluşturur ve kısa aralıklı ikinci uyarıcıya yanıt gecikir.'),
  ('"Tüm kediler hayvandır; bazı hayvanlar evcildir; öyleyse bazı kediler evcildir" çıkarımı neden geçersizdir?', 'Ortak kapsama dayalı sonuç, öncüllerden zorunlu olarak çıkmaz', ['Öncüller yanlış olduğu için çıkarım geçersizdir', 'Sonuç doğru olduğundan çıkarım her zaman geçerlidir', 'Çıkarımda hiçbir terim ortak kullanılmadığı için'], 'Bazı hayvanların evcil olması, o hayvanların kedi olduğunu göstermez; sonuç doğru olsa bile akıl yürütme geçerli değildir.'),
  ('İnançlı önyargı (inanç yanlılığı) etkisi nedir?', 'Sonucun inandırıcılığının mantıksal geçerlilik yargısını etkilemesi', ['Yalnızca sayısal akıl yürütmenin bozulması', 'Mantık bilgisinin kendiliğinden artması durumu', 'Kanıtların her zaman doğru biçimde değerlendirilmesi'], 'Kişiler inandıkları sonucu içeren geçersiz çıkarımları geçerli sayma, inanmadıkları sonucu içeren geçerli çıkarımları ise reddetme eğilimindedir.'),
  ('Ekoik belleğin tutma süresi yaklaşık ne kadardır?', 'Birkaç saniye', ['Birkaç dakika', 'Birkaç saat', 'Birkaç gün'], 'Duyusal bellekte işitsel izlerin birkaç saniye (yaklaşık 2–4 sn) kalması, konuşmayı sürekli anlamaya yardım eder.'),
  ('Maskeleme deneylerinde hedef görüntüden hemen sonra bir desen sunulduğunda ne olur?', 'Hedefin tanınması bozulur', ['Hedefin tanınması kolaylaşır', 'Hedef bilinçli olarak daha uzun görünür', 'Hiç değişiklik olmaz'], 'Desen ikonik izi siler ya da karıştırır; böylece hedefin ayrıntılı işlenmesi sınırlanır.'),
];
